# 구단 판매 추진 시스템 (2026-07 신설, 신민용+GPT 다회 설계 확정, v5)
# ══════════════════════════════════════════════════════════════

_SALE_PUSH_AWARD_SCORE = {"MVP": -2, "득점왕": -1, "베스트11": -1, "올해의 수비수": -1,
                          "구단 올해의 선수": -1}


def _my_team_rank_category(p) -> str:
    """팀 내 OVR 순위로 에이스/핵심/주전/후보 분류(내 선수급 디테일 대신
    가벼운 OVR 순위만 사용 — AI 팀메이트는 출전비중 등 세부 트래킹이
    없어서 통일된 기준이 OVR뿐이다)."""
    tid = p.get("current_team_id", 0)
    if not tid:
        return "후보"
    conn = get_conn()
    teammates = conn.execute("SELECT ovr FROM ai_players WHERE team_id=?", (tid,)).fetchall()
    my_ovr = p.get("ovr", 50)
    ovrs = sorted([r["ovr"] for r in teammates] + [my_ovr], reverse=True)
    rank = ovrs.index(my_ovr) + 1
    if rank == 1:
        return "에이스"
    if rank <= 3:
        return "핵심"
    if rank <= 6:
        return "주전"
    return "후보"


def _calc_sale_push_score(p, cur_year):
    """판매추진 점수를 계산한다. 반환: (score, reasons).

    [2026-08 재설계, 15-2-F] 기존엔 강등/계약만료임박/전력외/감독불화/
    본인불만 5개 조건을 +1씩만 더했다 — 그래서 "4년 계약 갓 체결한
    핵심 선수"도 강등 한 번이면 나머지 조건 몇 개만 겹쳐 쉽게 판매
    대상이 됐다(신민용 리포트 사례: 강등 다음 시즌에 4년 계약 중인
    선수가 강제로 해외 이적). 문제는 이 5개 조건 중 어느 것도 "이
    선수를 파는 게 구단에 손해인가"를 안 본다는 것 — 연봉 부담(파는
    이유)과 장기계약/핵심선수/좋은 폼(파는 걸 막는 이유)이 반대 방향
    요인으로 전혀 없었다. 판매 압력(+)과 보유 유인(-)을 모두 반영하도록
    확장한다.
    """
    score = 0
    reasons = []
    tid = p.get("current_team_id", 0)
    conn = get_conn()

    # 1) 재정 압박 — 이번 시즌 강등 (기존 relegation 체크 로직 재사용)
    if tid:
        team_row = conn.execute("SELECT name FROM teams WHERE id=?", (tid,)).fetchone()
        if team_row:
            rl = conn.execute(
                """SELECT from_tier, to_tier FROM promotion_log
                   WHERE team_name=? AND year=? ORDER BY id DESC LIMIT 1""",
                (team_row["name"], cur_year)).fetchone()
            if rl and rl["to_tier"] > rl["from_tier"]:
                score += 1
                reasons.append("relegation")

    # 2) 계약 만료 임박 — 잔여 1년 이하를 "6개월 이하"의 근사치로 취급
    #    (연 단위 계약 데이터라 주 단위 정밀 계산은 못 하지만, "임박"
    #    판정 목적으로는 충분한 근사치다)
    contract_end = p.get("contract_end_year", 0)
    remaining_years = (contract_end - cur_year) if contract_end else None
    if contract_end and remaining_years is not None and remaining_years <= 0:
        score += 1
        reasons.append("contract")

    # 3) 전력 외 — 팀 내 순위 "후보" 구간만 해당 (에이스/핵심/주전/후보
    #    분류는 아래 9)에서 "핵심 선수 보유 유인"에도 재사용한다)
    _rank_cat = _my_team_rank_category(p)
    if _rank_cat == "후보":
        score += 1
        reasons.append("bench")

    # 4) 감독과 불화
    if p.get("manager_relation", 50) < 20:
        score += 1
        reasons.append("hostile")

    # 5) 본인 불만 — 기존 transfer_rejection_count(일반 성향) 재사용,
    #    2회 이상 누적이면 "불만 중"으로 본다
    if _effective_rejection_count(p, cur_year) >= 2:
        score += 1
        reasons.append("frustration")

    # ── 여기부터 신설 — form_score 연결 (15-2-F) ──────────────────────
    _form_score = None
    if tid:
        _total_matches = _get_season_total_matches(tid)
        _form_score = calc_season_form_score(p, total_matches=_total_matches)["form_score"]

    # 6) [신설] 연봉 부담 — 실제 연봉이 이 선수 OVR 기준 "적정 연봉"보다
    #    과도하게 높으면 구단 입장에서 판매(임금 절감) 유인이 커진다.
    #    부상/징계 자체가 아니라 "돈이 안 맞는다"는 재정적 신호로만 본다.
    if tid:
        try:
            from economy import _calc_salary
            _team_ctx = conn.execute(
                """SELECT l.tier as tier, cn.name as country, cn.grade as grade, t.name as tname
                   FROM teams t JOIN leagues l ON t.league_id=l.id
                   JOIN countries cn ON l.country_id=cn.id WHERE t.id=?""", (tid,)).fetchone()
            if _team_ctx:
                from constants import get_league_grade
                _wealth = get_league_grade(_team_ctx["country"], _team_ctx["grade"])
                fair_salary = _calc_salary(_wealth, _team_ctx["tier"], p.get("ovr", 50),
                                            country=_team_ctx["country"], team_name=_team_ctx["tname"],
                                            year=cur_year, team_id=tid)
                actual_salary = p.get("salary", 0)
                if fair_salary > 0 and actual_salary / fair_salary >= 1.3:
                    score += 1
                    reasons.append("salary_burden")
        except Exception:
            pass

    # 7) [신설] 이번 시즌 폼 부진 — 구단이 "이 선수 더 데리고 있을 가치가
    #    있나" 판단하는 직접적 근거. 임계값(0.45)은 15-2-D 단위테스트
    #    기준 "사례 선수(레드3+낮은평점) 0.400"이 걸리고 "평범~보통
    #    (0.483)"은 안 걸리도록 그 사이로 잡았다.
    if _form_score is not None and _form_score < 0.45:
        score += 1
        reasons.append("poor_form")

    # ── 판매를 막는 요소(감산) ──────────────────────────────────────
    # 8) [신설] 장기 계약 잔여 — 최근 재계약/이적으로 계약이 3년 이상
    #    남아있다면 구단이 그만큼 이 선수에게 투자한 것 — 강등 한 번으로
    #    바로 헐값에 팔기보다는 데리고 가거나 비싸게 팔 유인이 크다.
    if contract_end and remaining_years is not None and remaining_years >= 3:
        score -= 1
        reasons.append("long_contract_retain")

    # 9) [신설] 핵심 선수(에이스/핵심 등급) — 팀 내 상위 랭크 선수는
    #    강등됐다고 쉽게 안 판다(오히려 승격 재도전의 핵심 자산).
    if _rank_cat in ("에이스", "핵심"):
        score -= 1
        reasons.append("core_player_retain")

    # 10) [신설] 폼이 좋음 — 최근 활약이 좋으면(threshold는 7)의 poor_form
    #     과 대칭적으로 잡되 살짝 더 엄격하게 — "부진 판정은 아니지만
    #     그렇다고 확실히 잘한 것도 아닌" 애매한 구간은 중립으로 둔다.
    if _form_score is not None and _form_score >= 0.65:
        score -= 1
        reasons.append("good_form_retain")

    # 수상 감산 (이번 연도 awards, is_mine=1)
    try:
        awards = conn.execute(
            "SELECT award_type FROM awards WHERE year=? AND is_mine=1", (cur_year,)).fetchall()
        for a in awards:
            at = a["award_type"] or ""
            for key, delta in _SALE_PUSH_AWARD_SCORE.items():
                if key in at:
                    score += delta
    except Exception:
        pass

    return max(0, score), reasons


_SALE_PUSH_REASON_TEXT = {
    "relegation": "구단은 강등으로 재정 압박을 받고 있습니다.",
    "contract": "계약 만료가 임박했습니다.",
    "bench": "감독은 당신을 다음 시즌 계획에 포함하지 않았습니다.",
    "hostile": "감독과의 관계가 좋지 않습니다.",
    "frustration": "최근 이적 요청이 반복해서 거절되어 불만이 쌓여 있습니다.",
}

# [2026-08 신설, 2단계: 판매 압박, 신민용+GPT 검토 확정] 판매추진 점수
# 자체는 이미 있었지만("구단이 이 선수를 얼마나 팔고 싶어하는가"), 그
# 강도를 플레이어에게 문구로 구분해서 보여주는 장치가 없었다 — 점수
# 2점이든 7점이든 항상 같은 "검토하고 있습니다" 문구였다. 이제 점수
# 구간별로 어조를 달리한다: 낮으면 담담하게, 높으면 강하게. 오직
# 메시지 톤만 다르고 실제 강제 이적으로는 이어지지 않는다(1단계에서
# 이미 제거).
_SALE_PUSH_INTENSITY_STAGES = [
    (6, "구단이 선수 매각을 강하게 요구하고 있습니다."),
    (4, "구단이 해당 선수의 판매를 적극적으로 추진하고 있습니다."),
    (2, "구단은 이 선수를 판매하는 방안을 검토하고 있습니다."),
]


def _sale_push_intensity_text(score: int) -> str:
    for threshold, text in _SALE_PUSH_INTENSITY_STAGES:
        if score >= threshold:
            return text
    return _SALE_PUSH_INTENSITY_STAGES[-1][1]


# [2026-08 신설, 2단계] club_sale_pressure(장기 누적 지표) 단계별 라벨 +
# manager_relation 페널티. sale_push_refused_count(사이클 내 카운터)와
# 달리 사이클이 끝나도 리셋되지 않는다 — "계속 거부당한 구단이 인내심을
# 잃어가는" 흐름을 표현한다. 아직은 manager_relation 소폭 하락 정도의
# 가벼운 효과만 연결한다(예산/재계약 등 더 무거운 연결은 추후 단계).
_SALE_PRESSURE_STAGES = [
    (5, "구단 프런트가 선수 보유 방침에 강한 불만을 갖고 있습니다.", 4),
    (3, "구단이 선수의 잔류 결정에 우려를 표하고 있습니다.", 2),
    (1, "", 0),
]


def _sale_pressure_stage(pressure: int):
    for threshold, text, penalty in _SALE_PRESSURE_STAGES:
        if pressure >= threshold:
            return text, penalty
    return "", 0


# [2026-08 신설, 3단계: 판매추진 전용 UI, 신민용+GPT 검토 확정: "판매금액은
# 오퍼 이적료의 30~70% 할인 — 구단이 얼마나 절박하게 팔려고 하는지에
# 비례"] 판매추진 점수(구단의 판매 의향 강도)가 높을수록 더 크게
# 할인한다. 시장가(estimate_transfer_fee 기준) 자체는 안 바뀐다 — 이건
# "이 선수의 가치"가 아니라 "구단이 지금 얼마나 급하게 팔고 싶어하는지"
# 를 나타내는 별도의 축이라는 걸 DB/로그에서도 분리해서 남긴다
# (market_fee와 transfer_fee를 proposal에 각각 저장).
_SALE_DISCOUNT_BY_SCORE = {2: 0.30, 3: 0.37, 4: 0.47, 5: 0.55, 6: 0.62, 7: 0.68}


def _sale_discount_pct(score: int) -> float:
    score = max(2, min(7, score))
    return _SALE_DISCOUNT_BY_SCORE[score]


def _weekly_sale_push_check(p, cur_year, cur_week):
    """매주 호출 — 판매추진 점수를 재계산하고 상태 전환을 처리한다.
    알림은 상태가 실제로 바뀔 때만(평상시→판매추진 전환 시 1회) 띄운다.

    [2026-07 재수정, 신민용 리포트: "판매 추진을 억제한다기보단 구단에서
    보내는 판매 서류를 다 무시한다는 의미인데, 결과가 같게 적용되는
    건가?"] 예전 구현은 allow_club_sale_push가 꺼지면 이 함수 자체를
    건너뛰고 sale_push_active를 즉시 0으로 리셋했다 — 이러면 "구단은
    계속 판매를 추진 중인데 나만 안 본다"가 아니라 "구단이 애초에 판매
    추진 자체를 안 한다"가 되어버려서, 4점+ 강제판매(_check_sale_push_
    forced_sale, 토글 무관하게 발동해야 함)가 sale_push_active=1을
    전제로 하는데 토글이 꺼지는 순간 그 전제 자체가 사라지는 모순이
    있었다. 이제 점수 계산과 상태(sale_push_active 등)는 토글과 완전히
    무관하게 항상 그대로 돌아가고, 토글은 "예고 알림을 보여줄지"에만
    관여한다 — 구단은 서류를 계속 만들고(상태 갱신), 플레이어만 그
    서류를 안 보는(알림 억제) 것.
    """
    score, reasons = _calc_sale_push_score(p, cur_year)
    was_active = bool(p.get("sale_push_active", 0))
    _show_notice = bool(p.get("allow_club_sale_push", 1))

    if score >= 2:
        if not was_active:
            # 평상시 → 판매추진 전환: 예고 알림 1회(토글 켜져 있을 때만 표시)
            update_player(sale_push_active=1, sale_push_start_year=cur_year,
                          sale_push_start_week=cur_week, sale_push_low_score_weeks=0)
            if _show_notice:
                reason_lines = "\n".join(_SALE_PUSH_REASON_TEXT.get(r, "") for r in reasons)
                _intensity = _sale_push_intensity_text(score)
                add_log(f"📋 구단 동향\n{_intensity}\n{reason_lines}",
                        "event", cur_year, cur_week)
        else:
            # 계속 판매추진 상태 — 저점수 연속주차 카운터만 리셋
            if p.get("sale_push_low_score_weeks", 0):
                update_player(sale_push_low_score_weeks=0)
            # [2026-07] 유효기간 — 2시즌(104주) 동안 오퍼 없으면 자동 종료
            start_y, start_w = p.get("sale_push_start_year", cur_year), p.get("sale_push_start_week", cur_week)
            weeks_elapsed = (cur_year - start_y) * 52 + (cur_week - start_w)
            last_offer_y = p.get("sale_push_last_offer_year", 0)
            if weeks_elapsed >= 104 and not last_offer_y:
                update_player(sale_push_active=0, sale_push_refused_count=0,
                              sale_push_low_score_weeks=0)
    else:
        if was_active:
            # [2026-07] 종료 디바운스 — 저점수가 연속 4주 유지돼야 실제 종료
            weeks_low = p.get("sale_push_low_score_weeks", 0) + 1
            if weeks_low >= 4:
                # [2026-08 신설, 2단계] 판매추진이 자연스럽게(강제 없이)
                # 해소됐다는 건 구단이 결국 이 선수를 계속 데리고 가기로
                # 했다는 뜻 — 장기 압박도 아주 조금은 누그러뜨린다(완전
                # 리셋은 아님, "한숨 돌렸다" 정도).
                _cur_pressure = p.get("club_sale_pressure", 0)
                update_player(sale_push_active=0, sale_push_refused_count=0,
                              sale_push_low_score_weeks=0,
                              club_sale_pressure=max(0, _cur_pressure - 1))
            else:
                update_player(sale_push_low_score_weeks=weeks_low)


def _find_sale_push_candidate(c, my_tid, grades, ovr_lo, ovr_hi, exclude_ids=None):
    """[2026-08 신설, 1단계-C: 판매 대상 구단 탐색 개편] 예전엔 무조건
    `l.tier = 1`(각국 1부리그)만 봐서, 원래 하위리그 소속이었어도 후보가
    항상 세계 각국 1부로 잡히는 문제가 있었다(신민용+GPT 검토: "tier=1
    고정은 버그에 가까운 설계"). 이제 내 현재 소속팀 tier 기준 ±1
    범위에서, 임대 탐색(_try_loan_player)과 같은 원리로 자국 → 같은
    대륙 → 전세계 순으로 찾는다 — "K리그 선수가 아무 이유 없이 모로코
    1부로 이적"류 사례를 원천적으로 줄인다.

    exclude_ids: [2026-08 신설, 3단계] "관심 구단" 목록을 여러 개 뽑을 때
    이미 뽑은 팀을 제외하기 위한 집합. None/빈 집합이면 기존과 동일."""
    origin = c.execute("""SELECT cn.id AS country_id, cn.continent, l.tier AS my_tier
                           FROM teams t JOIN leagues l ON t.league_id=l.id
                           JOIN countries cn ON l.country_id=cn.id
                           WHERE t.id=?""", (my_tid,)).fetchone()
    if not origin:
        return None
    my_tier = origin["my_tier"] or 1
    tier_lo, tier_hi = max(1, my_tier - 1), my_tier + 1
    grade_ph = ",".join("?" * len(grades))
    _exclude = exclude_ids or set()
    _exclude_sql = ""
    _exclude_params = ()
    if _exclude:
        _exclude_sql = f" AND t.id NOT IN ({','.join('?' * len(_exclude))})"
        _exclude_params = tuple(_exclude)

    def _find(extra_where, params):
        return c.execute(f"""
            SELECT t.id, t.name, l.id as lid, l.name as lname, l.tier,
                   cn.name as country, cn.flag, cn.grade
            FROM teams t
            JOIN leagues l ON t.league_id=l.id
            JOIN countries cn ON l.country_id=cn.id
            WHERE t.id != ? AND l.tier BETWEEN ? AND ?
              AND cn.grade IN ({grade_ph})
              AND (SELECT AVG(ovr) FROM ai_players WHERE team_id=t.id) BETWEEN ? AND ?
              {_exclude_sql}
              {extra_where}
            ORDER BY RANDOM() LIMIT 1
        """, (my_tid, tier_lo, tier_hi, *grades, ovr_lo, ovr_hi, *_exclude_params, *params)).fetchone()

    row = _find("AND cn.id=?", (origin["country_id"],))          # 1순위: 자국
    if not row:
        row = _find("AND cn.continent=? AND cn.id!=?",            # 2순위: 같은 대륙
                     (origin["continent"], origin["country_id"]))
    if not row:
        row = _find("", ())                                       # 3순위: 전세계
    return row


def _check_sale_push_forced_sale(p, cur_year, cur_week):
    """[2026-07 신설, 구단판매추진 v5] → [2026-08 재설계, 1단계-B] → [2026-08
    재설계, 3단계: 판매추진 전용 UI + 예약이적, 신민용+GPT 검토 확정]
    판매추진 점수 4점+ 이면 후보 팀(+관심 구단 목록)을 탐색해 "판매
    제안"을 만들어 저장한다. 예전(1단계)엔 후보를 찾을 때마다 그냥
    "관심을 보였다" 로그만 남기고 끝났는데, 이제는 실제로 플레이어가
    화면에서 수락/거절을 선택할 수 있는 완성된 제안(구매팀/리그/국가/
    부/제시연봉/판매금액/계약기간)을 만들어 sale_push_proposal_json에
    저장한다 — UI(ui/sale_push_window.py)가 이걸 읽어서 보여준다.

    이미 대기 중인 제안이 있으면(플레이어가 아직 결정 안 함) 새로
    만들지 않고, 거절 이후에는 쿨다운(sale_push_next_proposal_year/week)
    을 둬서 매주 스팸처럼 뜨지 않게 한다.

    판매금액은 시장가(estimate_transfer_fee, effective_ovr 반영)에
    판매추진 점수 기반 할인(30~70%, _sale_discount_pct)을 적용한 값 —
    "선수 가치가 낮아진 것"이 아니라 "구단이 급하게 팔려는 것"이라는
    걸 market_fee/transfer_fee를 분리 저장해 명확히 구분한다.
    """
    if not p.get("sale_push_active"):
        return
    if p.get("sale_push_proposal_json"):
        return  # 이미 대기 중인 제안이 있음 — 플레이어 결정을 기다림
    _next_y = p.get("sale_push_next_proposal_year", 0)
    _next_w = p.get("sale_push_next_proposal_week", 0)
    if _next_y and (cur_year, cur_week) < (_next_y, _next_w):
        return  # 거절 후 쿨다운 중
    score, reasons = _calc_sale_push_score(p, cur_year)
    if score < 4:
        return

    try:
        conn = get_conn()
        c = conn.cursor()
        my_tid = p.get("current_team_id", 0)
        if not my_tid:
            conn.close()
            return
        grades = _suitable_grades(p.get("ovr", 40), p.get("agent_grade", AGENT_NONE))
        cur_ovr = p.get("ovr", 40)

        # 주 후보(실제 판매안이 되는 팀) + 관심 구단 목록(최대 4개 추가,
        # 이미 뽑힌 팀은 제외) — "이 선수를 구매할 의향이 있는 여러 팀
        # 중 하나로 구단이 판매안을 확정했다"는 서사를 위한 장식용 목록.
        main_row = _find_sale_push_candidate(c, my_tid, grades, cur_ovr - 8, cur_ovr + 5)
        if not main_row:
            conn.close()
            return
        interest_ids = {main_row["id"]}
        interest_teams = []
        # [2026-08 수정, 신민용 요청: "관심 구단이 장식용 이름만 뜨는데,
        # 클릭하면 그 팀이 원하는 조건이 뜨게 하고 싶다"] 이름 문자열만
        # 저장하던 걸 팀 식별 정보(팀id/이름/리그/국가/부/등급) 전체로
        # 확장 — UI에서 이 정보로 get_sale_push_alt_offer(team_id)를 불러
        # 그 팀 기준 조건을 즉석 계산해 보여줄 수 있게 한다.
        for _ in range(4):
            _r = _find_sale_push_candidate(c, my_tid, grades, cur_ovr - 8, cur_ovr + 5,
                                           exclude_ids=interest_ids)
            if not _r:
                break
            interest_ids.add(_r["id"])
            interest_teams.append({
                "team_id": _r["id"], "team_name": _r["name"],
                "league_name": _r["lname"], "country": _r["country"],
                "flag": _r["flag"], "tier": _r["tier"], "grade": _r["grade"],
            })

        my_age = p.get("age", 25)
        contract_years = _calc_contract_years(my_age, main_row["tier"], main_row["country"])

        salary = _calc_salary(main_row["grade"], main_row["tier"], p.get("ovr", 40),
                              main_row["country"], main_row["name"], year=cur_year,
                              team_id=main_row["id"], talent_tier=p.get("talent_tier"))

        _contract_end = p.get("contract_end_year", 0)
        _remain = (max(0, _contract_end - cur_year) if _contract_end else None)
        market_fee = estimate_transfer_fee(
            main_row["grade"], main_row["tier"], p.get("ovr", 0),
            country=main_row["country"], team_name=main_row["name"],
            position=get_field_pos(p), age=p.get("age"),
            talent_cap=p.get("talent_cap"), contract_remaining_years=_remain,
            year=cur_year, team_id=main_row["id"],
            effective_ovr=calc_effective_ovr(p, ovr=p.get("ovr", 0)),
        )
        discount = _sale_discount_pct(score)
        sale_fee = int(market_fee * (1 - discount))
        conn.close()

        proposal = {
            "team_id": main_row["id"], "team_name": main_row["name"],
            "league_name": main_row["lname"], "country": main_row["country"],
            "flag": main_row["flag"], "tier": main_row["tier"],
            "grade": main_row["grade"], "salary": salary,
            "market_fee": market_fee, "transfer_fee": sale_fee,
            "discount_pct": discount, "contract_years": contract_years,
            "interest_teams": interest_teams,
            "score": score, "reasons": reasons,
            "gen_year": cur_year, "gen_week": cur_week,
        }
        update_player(sale_push_proposal_json=json.dumps(proposal, ensure_ascii=False))
        add_log(f"📋 구단이 판매 제안을 준비했습니다 — {main_row['name']}({main_row['lname']})",
                "event", cur_year, cur_week)
    except Exception as e:
        print("_check_sale_push_forced_sale 오류(건너뜀):", e)


def get_sale_push_alt_offer(team_id):
    """[2026-08 신설, 신민용 요청: "관심 구단을 클릭하면 그 팀이 원하는
    조건이 뜨게"] 판매추진 제안의 "관심 구단" 목록에 있는 팀 하나를 골라
    클릭했을 때, 그 팀 기준으로 실제 조건(연봉/이적료/계약기간)을 즉석
    계산해서 반환한다 — main_row(주 후보)를 만들 때와 완전히 동일한
    계산식(할인율만 지금 대기 중인 제안의 discount_pct를 그대로 재사용,
    "판매 결심 자체"는 이미 확정된 것이라 팀마다 새로 굴리지 않음).
    반환: 성공 시 proposal 형식과 동일한 dict, 실패 시 None."""
    p = get_player()
    if not p:
        return None
    raw = p.get("sale_push_proposal_json") or ""
    if not raw:
        return None
    try:
        base_proposal = json.loads(raw)
    except Exception:
        return None

    conn = get_conn()
    row = conn.execute(
        """SELECT t.id, t.name, l.name as lname, l.tier,
                  cn.name as country, cn.flag, cn.grade
           FROM teams t JOIN leagues l ON t.league_id=l.id
           JOIN countries cn ON l.country_id=cn.id WHERE t.id=?""",
        (team_id,)).fetchone()
    conn.close()
    if not row:
        return None

    st = get_state() or {}
    cur_year = st.get("current_year", 0)
    my_age = p.get("age", 25)
    contract_years = _calc_contract_years(my_age, row["tier"], row["country"])
    salary = _calc_salary(row["grade"], row["tier"], p.get("ovr", 40),
                          row["country"], row["name"], year=cur_year,
                          team_id=row["id"], talent_tier=p.get("talent_tier"))
    _contract_end = p.get("contract_end_year", 0)
    _remain = (max(0, _contract_end - cur_year) if _contract_end else None)
    market_fee = estimate_transfer_fee(
        row["grade"], row["tier"], p.get("ovr", 0),
        country=row["country"], team_name=row["name"],
        position=get_field_pos(p), age=p.get("age"),
        talent_cap=p.get("talent_cap"), contract_remaining_years=_remain,
        year=cur_year, team_id=row["id"],
        effective_ovr=calc_effective_ovr(p, ovr=p.get("ovr", 0)),
    )
    discount = base_proposal.get("discount_pct", 0.3)
    sale_fee = int(market_fee * (1 - discount))

    return {
        "team_id": row["id"], "team_name": row["name"],
        "league_name": row["lname"], "country": row["country"],
        "flag": row["flag"], "tier": row["tier"],
        "grade": row["grade"], "salary": salary,
        "market_fee": market_fee, "transfer_fee": sale_fee,
        "discount_pct": discount, "contract_years": contract_years,
        "interest_teams": base_proposal.get("interest_teams", []),
        "score": base_proposal.get("score", 4),
        "reasons": base_proposal.get("reasons", []),
        "gen_year": base_proposal.get("gen_year", cur_year),
        "gen_week": base_proposal.get("gen_week", 0),
    }


def accept_sale_push_proposal(team_id=None):
    """[2026-08 신설, 3단계] 판매 제안 수락 — 즉시 이적하지 않고
    pending_sale_transfer_json에 "예약"해둔다. 실제 이적은 다음 비시즌
    전환 시점(_end_of_season → _execute_pending_sale_transfer)에
    실행된다. 반환: True면 성공적으로 예약됨.

    team_id: [2026-08 신설] 주어지고 지금 대기 중인 제안의 주 후보와
    다르면(=관심 구단 목록에서 다른 팀을 클릭해 골랐으면), 그 팀 기준
    조건(get_sale_push_alt_offer)으로 대체해서 예약한다."""
    p = get_player()
    if not p:
        return False
    raw = p.get("sale_push_proposal_json") or ""
    if not raw:
        return False
    try:
        proposal = json.loads(raw)
    except Exception:
        return False

    if team_id and team_id != proposal.get("team_id"):
        alt = get_sale_push_alt_offer(team_id)
        if alt:
            proposal = alt

    update_player(sale_push_proposal_json="",
                  pending_sale_transfer_json=json.dumps(proposal, ensure_ascii=False),
                  sale_push_active=0, sale_push_refused_count=0,
                  sale_push_low_score_weeks=0)
    add_log(f"✅ {proposal['team_name']}로의 이적 제안을 수락했습니다 — "
            f"시즌이 끝나면 이적이 진행됩니다.", "event")
    return True


def reject_sale_push_proposal():
    """[2026-08 신설, 3단계] 판매 제안 거절 — 이번 사이클 거절 카운터와
    장기 압박 지표를 함께 올린다(2단계 로직 재사용). 쿨다운(8주)을 둬서
    바로 다음 주에 또 뜨지 않게 한다. 반환: True면 정상 처리됨."""
    p = get_player()
    if not p:
        return False
    raw = p.get("sale_push_proposal_json") or ""
    if not raw:
        return False
    try:
        proposal = json.loads(raw)
    except Exception:
        return False

    st = get_state() or {}
    cur_year = st.get("current_year", 0)
    cur_week = st.get("current_week", 0)
    _next_week = cur_week + 8
    _next_year = cur_year
    if _next_week > 52:
        _next_week -= 52
        _next_year += 1

    _new_refused = p.get("sale_push_refused_count", 0) + 1
    _new_pressure = p.get("club_sale_pressure", 0) + 1
    _pressure_text, _rel_penalty = _sale_pressure_stage(_new_pressure)
    _update_kwargs = dict(sale_push_proposal_json="",
                          sale_push_refused_count=_new_refused,
                          club_sale_pressure=_new_pressure,
                          sale_push_next_proposal_year=_next_year,
                          sale_push_next_proposal_week=_next_week)
    if _rel_penalty:
        _update_kwargs["manager_relation"] = max(0, p.get("manager_relation", 50) - _rel_penalty)
    update_player(**_update_kwargs)

    _msg = f"🚫 {proposal['team_name']}로의 이적 제안을 거절했습니다."
    if _pressure_text:
        _msg += f"\n⚠️ {_pressure_text}"
    add_log(_msg, "event", cur_year, cur_week)
    return True


def _execute_pending_sale_transfer(p, year):
    """[2026-08 신설, 3단계] 비시즌 전환 시점(_end_of_season)에 호출 —
    판매 제안을 수락해 예약해둔 이적이 있으면 실제로 실행한다."""
    raw = p.get("pending_sale_transfer_json") or ""
    if not raw:
        return
    try:
        proposal = json.loads(raw)
    except Exception:
        update_player(pending_sale_transfer_json="")
        return

    update_player(pending_sale_transfer_json="")
    offer = {"transfer_fee": proposal.get("transfer_fee", 0),
             "contract_years": proposal.get("contract_years")}
    join_team(proposal["team_id"], proposal.get("salary", 0),
              transfer_type="판매추진", offer=offer)
    add_log(f"💼 예약 이적 실행 — {proposal['team_name']}로 이적했습니다  "
            f"(판매금액 {fmt_money(proposal.get('transfer_fee', 0))})", "event", year, 52)


def reserve_join_transfer(team_id, salary, team_name, transfer_type="오퍼", offer=None):
    """[2026-08 신설, 신민용 요청: "클럽월드컵 도중 소속이 바뀌면 오류날
    수 있다"] 오퍟/입단 수락 시 join_team()을 즉시 부르지 않고 여기 예약만
    해둔다 — pending_sale_transfer_json(판매추진)과 완전히 동일한 패턴.
    같은 필드를 덮어쓰는 구조라, 이 시즌 구간 안에서 더 좋은 오퍟를 다시
    수락하면 자동으로 "가장 마지막에 고른 팀"으로 교체된다(이전 예약은
    그냥 덮어써져서 사라짐 — 원한 동작 그대로).
    offer: join_team에 그대로 넘길 offer dict(계약연수 등) — UI가 만든
    dlg.chosen을 그대로 넘기면 된다(JSON 직렬화 가능한 값들만 있어야 함)."""
    proposal = {"team_id": team_id, "salary": salary, "team_name": team_name,
                "transfer_type": transfer_type, "offer": offer or {}}
    st = get_state() or {}
    try:
        update_player(pending_join_transfer_json=json.dumps(proposal, ensure_ascii=False))
    except (TypeError, ValueError) as e:
        # [안전장치] offer dict에 직렬화 불가능한 값이 섞여 있으면 예약
        # 자체가 조용히 실패해서 오퍟가 통째로 증발하는 것보다는, 예전
        # 방식(즉시 이적)으로 폴백하는 게 낫다.
        print(f"reserve_join_transfer 직렬화 실패, 즉시 이적으로 폴백: {e}")
        join_team(team_id, salary, transfer_type=transfer_type, offer=offer)
        return
    add_log(f"📋 {team_name} 이적 확정 — 다음 시즌 구간이 시작되면 실제로 이적합니다",
            "event", st.get("current_year"), st.get("current_week"))


def _execute_pending_join_transfer(p, year, week):
    """[2026-08 신설] _advance_week가 상/하반기 시작 주차(FIRST_HALF_START/
    SECOND_HALF_START)에 진입할 때 호출 — reserve_join_transfer로 예약해둔
    이적이 있으면 이 시점에 실제로 실행한다. 클럽월드컵 등 비시즌 대회가
    전부 끝난 뒤(새 시즌 구간이 열리는 순간)이므로 대회 진행 중 소속이
    바뀌는 정합성 문제가 생기지 않는다."""
    raw = p.get("pending_join_transfer_json") or ""
    if not raw:
        return
    try:
        proposal = json.loads(raw)
    except Exception:
        update_player(pending_join_transfer_json="")
        return

    update_player(pending_join_transfer_json="")
    join_team(proposal["team_id"], proposal.get("salary", 0),
              transfer_type=proposal.get("transfer_type", "오퍼"),
              offer=proposal.get("offer") or None)
    add_log(f"✅ 예약 이적 실행 — {proposal['team_name']}에 입단했습니다",
            "event", year, week)


def _advance_week(p, base_week, n_weeks=4, progress_cb=None):
    new_week = base_week + n_weeks
    new_year = p["current_year"]
    new_season = p["current_season"]
    # [2026-09 신설, 신민용+GPT 설계: "main/hist 저장 시점 불일치" 대응]
    # 이 호출에서 진짜 연도전환(발롱도르/야신상 등 hist 즉시커밋 포함)이
    # 일어났는지 추적 — 아래에서 season_state를 새 연도로 갱신한 직후,
    # 이 플래그가 True일 때만 강제로 flush_to_disk를 한 번 더 걸어서
    # main도 hist와 같은 시점으로 디스크에 반영되게 한다(주기 자동저장은
    # 4주 단위라 51·52주차 전환 직후엔 다음 자동저장 전까지 공백이 있었다).
    _year_transition_happened = False

    if new_week > 52:
        new_week -= 52
        new_year += 1
        new_season += 1
        _year_transition_happened = True
        # [2026-07 신설, 진단용] "52주차→내년 4초" 리포트 대응 — 어느 단계가
        # 실제로 오래 걸리는지 추측 대신 숫자로 확인하기 위한 프로파일링.
        # 콘솔(터미널/exe 콘솔창)에 [PERF] 태그로 단계별 소요시간(초)이
        # 찍힌다. 게임플레이에는 전혀 영향 없음(단순 time.perf_counter()
        # 측정 + print) — 다음에 이 로그를 보고 진짜 병목 지점(예: AI
        # 생애주기 vs 승강제 vs 일정 재생성)을 정확히 짚어서 거기만
        # 추가로 최적화할 수 있다.
        import time as _time_perf
        try:
            from database import perf_wait_snapshot as _pws
            _pws(reset=True)
        except Exception:
            _pws = None
        _t0 = _time_perf.perf_counter()
        _tc0 = _time_perf.thread_time()
        # 연도 넘어갈 때 현재 팀 커리어 항목 닫기 (연도별 분리)
        if p.get("current_team_id"):
            _close_career_entry(p, new_year - 1, 52)
        _t1 = _time_perf.perf_counter()
        # [귀화] 거주 연수 갱신 + 자격 체크는 _end_of_season 안에서 처리
        #   (그 시점에 current_team_id가 아직 살아있어 소속국가를 읽을 수 있음)
        _end_of_season(p, new_year-1, progress_cb=progress_cb)
        _t2 = _time_perf.perf_counter()
        # [실시간 전환] 승강제 결과가 반영된 뒤(= teams.league_id 확정 후) 전 세계
        # 모든 리그의 새 시즌 일정을 미리 깔아 둔다. 이후 매주 _sim_all_ai_matches가
        # 실시간으로 채우므로 더 이상 연말에 몰아서 처리할 필요가 없다.
        _generate_all_league_schedules(new_season, new_year)
        _t3 = _time_perf.perf_counter()
        # [2026-08 신설, 파워랭킹 기반] _generate_all_league_schedules() 안에서
        # archive_old_seasons()가 이미 실행돼 league_season_standings에
        # 방금 끝난 시즌(new_year-1) 순위가 확정돼 있고, 그 해 열린 대륙컵/
        # 지역컵/챔피언스~클럽월드컵 대회들도(43~52주 구간에서 이미 끝남)
        # 전부 winner가 채워진 상태다 — 파워랭킹 계산에 필요한 데이터가
        # 전부 갖춰지는 시점이 바로 여기라 여기서 실행한다. 실패해도(예:
        # 아직 한 시즌도 못 채운 극초반 세이브) 연도 전환 자체를 막으면
        # 안 되므로 다른 [PERF] 블록들과 같은 방어적 try/except로 감싼다.
        try:
            import power_ranking
            power_ranking.run_year_end_power_ranking_update(get_conn(), new_year - 1)
        except Exception as e:
            print("파워랭킹 갱신 오류(건너뜀):", e)
        _t3p = _time_perf.perf_counter()
        # [2026-09 신설] 국내 슈퍼컵(domestic_super_cup_engine) — Y년 대회가
        # (Y-1)년 리그/컵 결과를 쓰므로, 그 (Y-1)년 최종 순위(방금 위
        # archive_old_seasons가 이미 league_season_standings에 확정해둠)가
        # 갖춰지는 바로 이 시점에 전 세계 나라를 한 번에 만든다. 실제 경기
        # 배정 요일(_pick_dsc_day)이 4주차 국내리그 일정을 조회하는데, 그
        # 일정은 바로 위 _generate_all_league_schedules에서 이미 생성돼
        # 있어 여기서 만들어도 안전하다.
        try:
            domestic_super_cup_engine.start_all_domestic_super_cups(new_year, new_season)
        except Exception as e:
            print("국내 슈퍼컵 생성 오류(건너뜀):", e)
        _t3c = _time_perf.perf_counter()
        # [2026-07 추가, 신민용 리포트: "연도전환이 갈수록 느려진다"] SQLite는
        # ANALYZE로 모은 테이블 통계를 바탕으로 실행계획(어느 인덱스를 쓸지)을
        # 정하는데, 이 게임은 한 번도 ANALYZE를 돌린 적이 없어서 테이블이
        # 텅 비어있던 초반 통계(또는 무통계 상태의 대략적 추정치)에 계속
        # 의존했다. 특히 match_results_archive처럼 시즌이 쌓일수록 몇 배씩
        # 커지는 테이블에서는 이 괴리가 갈수록 벌어져 실행계획이 점점
        # 부정확해질 수 있다. PRAGMA optimize는 SQLite 공식 문서가 권장하는
        # 가벼운 주기적 통계 갱신 방법이라(필요할 때만 선별적으로 ANALYZE를
        # 돌림, 매번 전체 재분석하는 비용 없음) 연 1회, 무거운 연도전환
        # 작업 직후에 실행해 다음 해 쿼리 계획을 최신 상태로 유지한다.
        try:
            get_conn().execute("PRAGMA optimize")
        except Exception:
            pass
        _t3b = _time_perf.perf_counter()
        _live_debug(f"[PERF] 연도전환 총 {_t3b-_t0:.2f}s "
              f"(커리어정리 {_t1-_t0:.2f}s | _end_of_season {_t2-_t1:.2f}s | "
              f"일정생성 {_t3-_t2:.2f}s | 파워랭킹 {_t3p-_t3:.2f}s | 국내슈퍼컵생성 {_t3c-_t3p:.2f}s | "
              f"PRAGMA optimize {_t3b-_t3c:.2f}s)")
        if _pws is not None:
            _w = _pws(reset=True)
            _tc = _time_perf.thread_time() - _tc0
            _live_debug(f"[PERF-WAIT] 연도전환 중 대기: 벽시계 {_t3b-_t0:.2f}s / 이 스레드 CPU {_tc:.2f}s "
                        f"(차이 {max(0.0, (_t3b-_t0) - _tc):.2f}s = 대기) | 풀커넥션 락(다른 스레드) "
                        f"{_w['s']:.2f}s({_w['n']}회) | hist writer 대기 {_w['drain_s']:.2f}s")
    else:
        # 리그 시즌 종료 주(신규 캘린더: 43주) 다음 주 진입 시: 커리어 스탯
        # 중간 업데이트만 (항목은 닫지 않음 - 연도 변경 시 _close_career_entry가 닫음)
        from constants import SEASON_PHASES as _SP
        _league_end_wk = _SP["second_half"][1]   # 43
        if base_week <= _league_end_wk and new_week >= _league_end_wk + 1:
            if p.get("current_team_id") and p.get("season_matches", 0) > 0:
                _update_career_stats(p, new_year, new_week)
            # [우승 확정] 리그 경기는 _league_end_wk주에 끝나므로, 그 다음 주 진입 시
            #   그 시점 소속 팀이 1위면 그 즉시 우승을 기록한다.
            #   (연말까지 안 기다리고 바로 '성적'에 반영)
            _lock_league_title_after_season(p, new_year)

    # [2026-08 신설, 신민용 요청: "입단/오퍟 반영을 시즌 시작 순간으로"]
    # 상반기 시작(FIRST_HALF_START=4주)이나 하반기 시작(SECOND_HALF_START)
    # 주차에 진입하는 바로 이 순간, 그 전까지 쌓아둔 예약 이적이 있으면
    # 실행한다 — 프리시즌/국제오프시즌 구간에 수락한 오퍟는 다음 상반기
    # 시작에, 중간휴식기(겨울 이적시장) 구간에 수락한 오퍟는 하반기 시작에
    # 반영된다. 이 시점은 클럽월드컵 등 비시즌 대회가 전부 끝난 뒤라 대회
    # 도중 소속이 바뀌는 정합성 문제가 없다.
    if new_week in (FIRST_HALF_START, SECOND_HALF_START):
        _p_pending = get_player()
        if _p_pending:
            _execute_pending_join_transfer(_p_pending, new_year, new_week)

    # [2026-09 신설, 신민용+GPT 협업 확정: "강팀 오퍼가 너무 잦다"] 프리시즌
    # 오퍼 구간(1~3주차)에 열어뒀던 "강팀 오퍼 빈자리"의 마감 기한 — 4주차
    # (정규시즌 시작)가 되는 이 순간, 바로 위에서 예약 입단(내가 그 팀에
    # 들어갔는지)을 이미 반영한 뒤이므로, 그래도 여전히 안 채워진 자리만
    # AI 유망주로 강제 보충해 26명을 맞춘다. ai_lifecycle._roll_offer_
    # vacancy_teams/_fill_offer_vacancies 참고.
    if new_week == FIRST_HALF_START:
        try:
            from ai_lifecycle import _fill_offer_vacancies
            _fill_offer_vacancies(new_year)
        except Exception as _e:
            add_log(f"⚠ 강팀 오퍼 빈자리 마감 보충 오류: {_e}", "event", new_year, new_week)

    # [2026-08 신설, 상반기/하반기 이적 기록 분리 기능, 신민용 요청:
    # "1993 기록이 2개로 나뉘며 상반기는 이팀 하반기는 2팀... 상황에
    # 따라 중간에도 AI 선수들 이적이 가능하긴 하나 이때는 0~2명 정도만"]
    # 하반기 시작 주차에 진입하는 이 순간 (1) 지금까지(=상반기) 치른
    # 경기만 반영된 순위표를 스냅샷으로 남기고 — 시즌이 끝나면 원본
    # match_results가 결국 요약/압축돼 상반기 시점을 나중엔 복원할 수
    # 없으므로 지금 미리 떠둬야 한다 — (2) 아주 작은 규모(리그당 팀 수
    # 기준 오프시즌의 약 1/10)로 AI끼리 이적 창구를 한 번 더 연다.
    # 세계 축구 기록실 "선수 검색"이 이 스냅샷 + ai_transfer_log.
    # is_mid_season을 보고 그 해 기록을 상반기/하반기 두 줄로 쪼갠다.
    if new_week == SECOND_HALF_START:
        # [2026-09 계측 추가, 신민용 리포트: "28주차가 3.2초인데 PERF-TM
        # 합계는 2.06초뿐 — 나머지 1.2초가 어디서 나오는지 모르겠다"]
        # 이 블록은 하위컵 생성 / 상반기 순위 스냅샷 / 겨울 이적시장
        # 세 가지를 연달아 하는데 계측이 겨울 이적시장(PERF-TM)에만
        # 있었다. 게다가 28주차는 실기기 로그에서 시즌마다 2.70→3.24s로
        # 자라는 유일한 구간이라(5시즌 실측) 어느 조각이 자라는지
        # 구분이 필요하다. [RESET]/[CREATE]/[PERF]와 같은 패턴으로
        # 구간만 찍는다 — 로직은 한 줄도 안 바꾼다.
        import time as _time_half
        _hf0 = _time_half.perf_counter()
        # [2026-09 신설] 3부/4부 국내컵(lower_cup_engine) 개막 — 국내 컵대회
        # (1~2부, 5주차 시작)와 달리 이 대회는 하반기 시즌에 들어가는 대회라
        # (신민용 확정: "리그 사이사이에 하는거지") 하반기 시작 주차에 연다.
        # 매 시즌 승강 직후라 이번 시즌 실제 3/4부 소속 팀 명단이 확정된
        # 뒤라는 점도 이 시점을 고르는 이유(요청: "이건 하반기 시즌에 들어갈
        # 대회야... 승강이 매 시즌 바뀌니까").
        try:
            lower_cup_engine.start_lower_cup(new_year, new_season)
        except Exception as e:
            add_log(f"⚠ 3부·4부컵 생성 오류: {e}", "event")
        _hf1 = _time_half.perf_counter()
        _half_n_leagues = 0
        try:
            _conn_half = get_conn()
            _league_ids = [r[0] for r in _conn_half.execute(
                "SELECT DISTINCT league_id FROM match_results WHERE season=?",
                (new_season,)).fetchall()]
            _half_n_leagues = len(_league_ids)
            _hf1b = _time_half.perf_counter()
            _half_rows = []
            for _lid in _league_ids:
                for _row in get_league_standings(_lid, season=new_season, conn=_conn_half):
                    _half_rows.append((_lid, new_season, new_year, _row["id"],
                                        _row["wins"], _row["draws"], _row["losses"],
                                        _row["goals_for"], _row["goals_against"]))
            _hf1c = _time_half.perf_counter()
            if _half_rows:
                _conn_half.executemany(
                    """INSERT OR REPLACE INTO league_season_standings_half
                       (league_id, season, year, team_id, wins, draws, losses,
                        goals_for, goals_against)
                       VALUES (?,?,?,?,?,?,?,?,?)""", _half_rows)
                _conn_half.commit()
            # [2026-09 신설, 진단용] "스냅샷INSERT" 버킷(아래 _hf2-_hf1c)이
            # 15년 실측에서 +125% 늘었는데 원인을 못 찾아, standings_half
            # INSERT/그 commit/_snapshot_team_lineup_half(내부는 자체
            # [PERF-SNAPSHOT]으로 더 쪼갬)/그 commit/close()를 전부
            # 따로 잰다. 로직은 그대로.
            _hfx1 = _time_half.perf_counter()   # standings_half INSERT+commit 끝
            # [2026-09 신설, 신민용 요청: "상반기/하반기 포메이션을 따로
            # 보여달라"] 위 상반기 순위 스냅샷과 완전히 같은 시점(겨울
            # 이적시장이 열리기 직전, ap.team_id가 아직 상반기 로스터인
            # 순간)에 팀별 상반기 포메이션도 같이 찍어둔다 — 아래
            # ai_lifecycle.run_ai_mid_season_transfer가 이 team_id들을
            # 바꾸기 전에 반드시 먼저 실행돼야 한다.
            # [2026-09, hist 비동기 writer 검증 완료 후 제거] 이 블록을
            # 감싸고 있던 VDBE 스텝 계측/페이지·freelist 카운트/WAL 크기
            # diff/PASSIVE·TRUNCATE 체크포인트(별도 커넥션) 진단 코드는
            # "스냅샷INSERT 버킷의 그 commit이 15년간 0.1s→1.6s로 자란
            # 원인"을 찾기 위한 것이었다 — 원인(hist.db 동기 커밋 자체의
            # 비용)이 확인되고 비동기 writer로 해결된 뒤, 실제 19시즌
            # 세이브로 재검증한 결과 "그 commit"은 0.000~0.001s로 평탄화된
            # 반면, 이 진단 코드 자체(특히 매년 강제로 돌리던 TRUNCATE
            # 체크포인트)가 hist.db 파일 크기에 비례해 0.36s→1.9s로 자라는
            # "진단 도구가 새로 만든 부하"로 남아있음을 실측으로 확인(신민용
            # 확인) — 역할이 끝났으므로 제거한다. 로직·데이터는 무관, 순수
            # 계측 코드만 삭제.
            try:
                from ai_lifecycle import _snapshot_team_lineup_half
                _snapshot_team_lineup_half(_conn_half, new_year)
            except Exception as _e:
                add_log(f"⚠ 상반기 포메이션 스냅샷 오류: {_e}", "event", new_year, new_week)
            _hfx2 = _time_half.perf_counter()   # snapshot 함수 자체 끝
            try:
                _snap_msg = (f"[PERF-SNAPSHOT] {new_year}년 스냅샷INSERT 버킷 세부: "
                             f"standings_half INSERT+commit {_hfx1-_hf1c:.3f}s "
                             f"({len(_half_rows)}건) | "
                             f"_snapshot_team_lineup_half {_hfx2-_hfx1:.3f}s")
                print(_snap_msg, flush=True)
                _live_debug(_snap_msg)
            except Exception:
                pass
        except Exception as _e:
            _hf1b = _hf1c = _time_half.perf_counter()
            add_log(f"⚠ 상반기 순위 스냅샷 오류: {_e}", "event", new_year, new_week)

        _hf2 = _time_half.perf_counter()
        try:
            from ai_lifecycle import run_ai_mid_season_transfer
            run_ai_mid_season_transfer(new_year, verbose_log=add_log, my_team_id=p.get("current_team_id"))
        except Exception as _e:
            add_log(f"⚠ 겨울 이적시장 처리 중 오류: {_e}", "event", new_year, new_week)
        _hf3 = _time_half.perf_counter()
        # 상반기 순위 스냅샷은 리그마다 get_league_standings를 한 번씩
        # 부르는 구조(리그 수 × match_results 조회)라 시즌이 쌓일수록
        # 자랄 후보 1순위다 — 리그 수도 같이 찍어 "리그당 비용"을
        # 비교할 수 있게 한다.
        try:
            print(f"[PERF-HALF] {new_year}년 28주차 하반기 진입 총 {_hf3-_hf0:.3f}s "
                  f"(3·4부컵 생성 {_hf1-_hf0:.3f}s | "
                  f"상반기순위 리그조회 {_hf1b-_hf1:.3f}s | "
                  f"순위계산루프 {_hf1c-_hf1b:.3f}s | "
                  f"스냅샷INSERT {_hf2-_hf1c:.3f}s | "
                  f"겨울이적시장 {_hf3-_hf2:.3f}s) (대상리그 {_half_n_leagues}개)",
                  flush=True)
            _live_debug(f"[PERF-HALF] {new_year}년 28주차 하반기 진입 총 {_hf3-_hf0:.3f}s "
                        f"(3·4부컵 생성 {_hf1-_hf0:.3f}s | "
                        f"상반기순위 리그조회 {_hf1b-_hf1:.3f}s | "
                        f"순위계산루프 {_hf1c-_hf1b:.3f}s | "
                        f"스냅샷INSERT {_hf2-_hf1c:.3f}s | "
                        f"겨울이적시장 {_hf3-_hf2:.3f}s) (대상리그 {_half_n_leagues}개)")
        except Exception:
            pass

    # [2026-07 신설, 신민용+GPT 다회 설계 확정: "구단 판매 추진" 시스템]
    # 매주(정확히는 _advance_week가 호출될 때마다) 5개 조건 점수를
    # 재계산 — 오퍼가 매주 뜨는 기존 구조와 맞추기 위해 연말 1회가 아니라
    # 주 단위로 판정한다.
    if p.get("current_team_id"):
        try:
            _weekly_sale_push_check(p, new_year, new_week)
        except Exception as e:
            print("_weekly_sale_push_check 오류(건너뜀):", e)
        _p_after_push = get_player()
        if _p_after_push and _p_after_push.get("current_team_id"):
            _check_sale_push_forced_sale(_p_after_push, new_year, new_week)

    # [최적화] my_player + season_state 갱신을 하나의 커넥션으로 묶어 커밋 2회→1회
    conn_adv = get_conn()
    conn_adv.execute(
        "UPDATE my_player SET current_year=?,current_week=?,current_season=? WHERE id=1",
        (new_year, new_week, new_season))
    rows_ss = conn_adv.execute("SELECT id FROM season_state WHERE id=1").fetchone()
    if rows_ss:
        conn_adv.execute(
            "UPDATE season_state SET current_year=?,current_week=?,current_season=? WHERE id=1",
            (new_year, new_week, new_season))
    else:
        conn_adv.execute(
            "INSERT INTO season_state(id,current_year,current_week,current_season) VALUES(1,?,?,?)",
            (new_year, new_week, new_season))
    conn_adv.commit()
    conn_adv.close()
    # [2026-08 신설] get_state() 캐시에도 같은 값을 바로 반영(무효화 대신
    # patch) — 주/시즌 경계마다 도는 경로라 다음 get_state() 호출들이
    # 다시 DB를 조회하지 않아도 되게 한다.
    if _state_cache is not None:
        _state_cache["current_year"] = new_year
        _state_cache["current_week"] = new_week
        _state_cache["current_season"] = new_season

    # [2026-09 신설] 시즌 전환 완료 직후 강제 저장 — 위 _year_transition_happened
    # 코멘트 참고. season_state가 이미 새 연도로 커밋된 "바로 이 시점"에
    # main을 디스크에 반영해두면, 이 직후 비정상 종료(터미널 강제종료 등)가
    # 나더라도 hist(이미 커밋된 발롱도르 등)와 main이 같은 시점을 가리키게
    # 된다. 기존 4주 단위 주기저장은 그대로 유지(크래시 대비 안전장치) —
    # 이건 그 사이의 유일한 공백(51·52주차 부근)만 추가로 메우는 것.
    if _year_transition_happened:
        try:
            from database import flush_to_disk_async
            flush_to_disk_async()
        except Exception as e:
            print(f"[SEASON-END-FLUSH] 시즌전환 직후 강제저장 실패(무시하고 계속): {e}")

    # 1주차: 새 시즌 시작 시 완전히 만료된(냉각기 끝난) 오퍼 거절 기록 삭제
    # [2026-08 수정, 신민용 확정] 예전엔 "year < 현재연도"(1년만 지나면
    # 바로 삭제)였는데, 이제 냉각기 규칙이 "거절연도+2까지 차단"이라
    # 그 기준(year+2 <= 현재연도)에 맞춰야 실제로 만료된 것만 지운다.
    # (아직 냉각기가 안 끝난 기록을 여기서 지워버리면 그 팀이 바로 다음
    # 해부터 다시 오퍼를 보낼 수 있게 되는 버그가 생긴다.)
    if new_week == 1:
        conn_cl = get_conn()
        st_yr = conn_cl.execute("SELECT current_year FROM season_state WHERE id=1").fetchone()
        if st_yr:
            conn_cl.execute("DELETE FROM offer_refused WHERE year + 2 <= ?", (st_yr["current_year"],))
            conn_cl.commit()
        conn_cl.close()

    # 겨울 이적시장 시작 1주 전: 그 시점까지의 평점 스냅샷 저장 (겨울 오퍼 확률용)
    from constants import OFFER_ZONES
    _winter_zone_start = OFFER_ZONES[1][0]   # 겨울 이적시장 시작 주차
    if new_week == _winter_zone_start - 1:
        p_snap = get_player()
        if p_snap:
            rc_s = p_snap.get("season_rating_cnt", 0)
            rs_s = p_snap.get("season_rating_sum", 0.0)
            update_player(first_half_rating=round(rs_s/rc_s, 2) if rc_s else 0.0)

    # [2026-07 재수정, 신민용 리포트: "예선 소집이 28주에 오는데 27주에
    # 와야 할듯"] 28주(휴식기 첫 주) 시작 시점에 예선을 생성하면, 27주
    # 일정을 짜는 시점엔 아직 예선 대회가 DB에 없어서 "경기 전날 휴식
    # 강제"(_get_match_for_day(d+1)로 다음날 경기 있는지 미리 확인하는
    # 로직)가 27주 마지막 날(189일)에서 다음날(190일, 예선 첫 경기)을
    # 확인해도 아직 존재하지 않는 대회라 놓친다 — 그 결과 대회 시작
    # 전날 휴식이 안 뜬다. 트리거를 한 주 앞당겨(27주 진입 시점) 생성하면
    # 27주 일정을 짜는 시점에 이미 예선 대회가 존재해서 정상적으로
    # 휴식이 뜬다. 실제 경기 날짜(day190~) 자체는 그대로다 — 데이터가
    # 미리 만들어질 뿐 매치데이는 안 당겨진다.
    from constants import INTL_QUAL_WEEK
    if new_week == INTL_QUAL_WEEK - 1:
        try:
            intl_engine.start_qualifying_if_needed(new_year)
        except Exception as e:
            add_log(f"⚠ 월드컵 예선 생성 오류: {e}", "event")

    # [2026-07 버그수정, 신민용 리포트: "10월29일 클럽월드컵 첫 경기 바로
    # 전날(10월28일)이 강제 휴식이 아니라 그냥 훈련으로 뜬다"] 예선과
    # 완전히 동일한 원인이다(위 INTL_QUAL_WEEK-1 주석 참고) — 대회가
    # INTL_CALLUP_WEEK '그 주 첫날'에 생성되는데, 그날의 바로 전날(오프
    # 시즌 진입 전 마지막 날) 일정을 화면에 그릴 때는 아직 대회 자체가
    # DB에 없어서 "내일 경기 있음" 체크가 못 찾는다. 트리거를 한 주
    # 앞당기면(INTL_CALLUP_WEEK-1 진입 시점) 그 전날 일정을 그릴 때 이미
    # 대회가 존재해서 정상적으로 휴식이 뜬다. 실제 경기 날짜 자체는
    # 그대로다(TOURNAMENT_SCHEDULE_RULES가 day를 결정, 트리거는 그저
    # 데이터를 미리 만들 뿐).
    from constants import INTL_CALLUP_WEEK
    if new_week == INTL_CALLUP_WEEK - 1:
        try:
            intl_engine.start_intl_tournament(new_year)
        except Exception as e:
            add_log(f"⚠ 국제대회 생성 오류: {e}", "event")

    # [2026-09 신설] 랭킹 평가전(power_eval) — 클럽월드컵 해 25주(발탁/
    # 조추첨) 진입 시 생성. 첫 매치데이가 26주(day176)라 위 두 훅과
    # 동일 원칙으로 "경기 시작 전 주"에 미리 만들어둔다(25주 자체가
    # 원래 발탁 전용이라 -1 보정 불필요 — POWER_EVAL_CALLUP_WEEK가 이미
    # 그 "전 주" 역할).
    from constants import POWER_EVAL_CALLUP_WEEK
    if new_week == POWER_EVAL_CALLUP_WEEK:
        try:
            intl_engine.start_power_eval_if_needed(new_year)
        except Exception as e:
            add_log(f"⚠ 랭킹 평가전 생성 오류: {e}", "event")

    # CL_START_WEEK(8주차) 진입: 클럽 대항전(챔스/유로파/컨퍼런스) 3개
    # 동시 시작 (매년). 출전팀 선발은 직전 시즌(이미 끝난 시즌)의 최종
    # 순위 기준 — continental_qualification이 대륙당 국가 순위 계산을
    # 1번만 하고 세 대회에 나눠준다(2026-08, 예전엔 챔스만 있었음).
    from competition.champions_engine import CL_START_WEEK
    if new_week == CL_START_WEEK:
        try:
            continental_qualification.start_all_continental_competitions(new_year, new_season)
        except Exception as e:
            add_log(f"⚠ 클럽 대항전 생성 오류: {e}", "event")

    # [2026-07 신설] 5주차 진입: 국내 컵대회(FA컵식) 개막 (챔스 시작보다
    # 앞서서, 1~2부 팀 전체로 대진을 짠다).
    if new_week == 5:
        try:
            cup_engine.start_domestic_cup(new_year, new_season)
        except Exception as e:
            add_log(f"⚠ 컵대회 생성 오류: {e}", "event")

    # 새 시즌 시작(1주차 진입 시 1회) 내 리그 + 인접 리그 일정 생성
    # generate_season_schedule는 멱등하지만, 1주차에만 호출해 불필요한 중복 조회 방지
    if new_week == 1 and p.get("current_team_id"):
        p_fresh = get_player()
        if p_fresh and p_fresh.get("current_league_id"):
            _generate_adjacent_schedules(
                p_fresh["current_league_id"], new_season, new_year)


def _calc_clean_sheets_for_player(p, team_id=None, matches=None):
    """소속 팀의 이번 시즌 클린시트 수 (수상 산정용).
    team_id/matches를 넘기면 그 팀·그 팀에서의 출전수 기준으로 계산한다
    (기본값은 현재 팀 — 이적 없이 쓰던 기존 호출부는 그대로 동작).
    [2026-08] 시즌 중 이적 시 시상은 '주 소속팀'(_primary_club_this_season)
    기준으로 계산해야 하므로 이 오버라이드가 필요해졌다."""
    tid = team_id if team_id is not None else p.get("current_team_id", 0)
    if not tid:
        return 0
    conn = get_conn(); c = conn.cursor()
    try:
        season = p.get("current_season", 1)
        _m = matches if matches is not None else p.get("season_matches", 0)
        return _calc_clean_sheets(c, tid, season, matches=_m)
    except Exception:
        return 0
    finally:
        conn.close()


# [2026-09 성능] 아래 세 추정 함수는 시즌 전환 한 번에 합쳐서 100만 회
# 넘게 불린다(_snapshot_season_ratings만으로 _estimate_ai_season 496,699회
# + _estimate_ai_clean_sheets 496,699회). 그 규모에서는 random.uniform
# 호출 자체의 오버헤드가 계산보다 크다 — CPython 구현이 정확히
# `a + (b-a)*random()`이므로 그대로 인라인한다.
#
# [주의] (b-a)를 손으로 계산한 리터럴로 바꾸면 안 된다. 1.2-0.8은
# 0.4가 아니라 0.40000000000000013이라 결과가 최하위 비트에서 갈리고,
# 그게 round() 경계에서 골/도움을 1 다르게 만들 수 있다. 반드시 뺄셈
# 식을 그대로 상수로 접어둔다.
_U08_LO, _U08_SPAN = 0.8, 1.2 - 0.8          # random.uniform(0.8, 1.2)
_U085_LO, _U085_SPAN = 0.85, 1.15 - 0.85     # random.uniform(0.85, 1.15)

# [2026-09 신설, 신민용+GPT 협의: "18*uniform(0.8,1.2)면 이론상 최댓값이
# 21.6골 — 아무리 뛰어난 선수라도 23~28골짜리 득점왕 시즌이 구조적으로
# 불가능하다"] OVR을 골 수에 직접 곱하지 않는다는 원칙(_estimate_ai_season
# 설계 변경 코멘트 참고)은 그대로 유지하면서, "평소엔 다들 비슷하지만
# 아주 가끔 역대급 시즌이 나온다"는 현실적인 꼬리를 순수 랜덤 쪽에 만든다
# — 실력(OVR)이 아니라 "그 시즌 폼"이 터진 것으로 취급하는 셈이다.
# 기존 uniform(0.8,1.2) 구간은 그대로 "평범한 시즌"(약 90%)으로 보존하고,
# 그 위에 좋은/폭발적/역대급 3단계 꼬리를 얹는다 — _rand() 호출 1번을
# 4구간으로 쪼개 쓰므로 난수 소비 횟수는 기존과 동일하다(goals 1회 +
# assists 1회, 이전과 완전히 같은 소비 패턴).
#   평범(90.0%): ×0.80~1.20  (기존 그대로, ST 기준 14~22골)
#   좋은 시즌(7.0%): ×1.20~1.50  (22~27골)
#   폭발적 시즌(2.5%): ×1.50~1.80  (27~32골)
#   역대급 시즌(0.5%): ×1.80~2.50  (32골+, 상한 45골 상당에서 사실상 클램프)
_TAIL_P1, _TAIL_P2, _TAIL_P3 = 0.90, 0.97, 0.995   # 누적 확률 경계
def _tailed_season_mult(u):
    """u는 0~1 균등난수 한 개. 위 4단계 분포를 따르는 배율을 반환한다."""
    if u < _TAIL_P1:
        return _U08_LO + _U08_SPAN * (u / _TAIL_P1)
    if u < _TAIL_P2:
        return 1.20 + 0.30 * ((u - _TAIL_P1) / (_TAIL_P2 - _TAIL_P1))
    if u < _TAIL_P3:
        return 1.50 + 0.30 * ((u - _TAIL_P2) / (_TAIL_P3 - _TAIL_P2))
    return 1.80 + 0.70 * ((u - _TAIL_P3) / (1.0 - _TAIL_P3))

# [2026-09 재보정, 신민용 리포트: "주전/로테이션/대기 GK끼리 선방률이
# 같아 보인다" → game.db 실측(2001시즌 GK 24,844명)으로 확인: 같은 팀
# 안에서 OVR 15점+ 차이나는 GK 430쌍의 선방률 차이가 평균 3.8%p(표준편차
# 5.0%p)뿐이고 역전 사례도 다수 — OVR 신호(50~99 전체 범위 20%p 폭,
# 1점당 ~0.41%p)보다 개인별 독립 노이즈(±5%p)가 더 커서 신호가 묻힘.
# 신민용 확정: "노이즈만 줄이지 말고 신호도 같이 키우자" — OVR 신호 폭
# 20%p→28%p(base_save_pct 담당), 노이즈 ±5%p→±2%p로 동시 조정한다.
# 개인 편차 자체를 완전히 없애는 것(±0%p)은 지양 — "OVR85가 OVR80보다
# 항상 정확히 높지는 않다"는 자연스러운 변동은 남겨둔다는 것이 확정 방향.
_U005_LO, _U005_SPAN = -0.02, 0.02 - (-0.02)  # random.uniform(-0.02, 0.02)
_rand = random.random

# [2026-09 성능 2차] _estimate_ai_season 전용 메모.
#  _SCALE_MEMO:   full_season_matches -> (fsm/38.0)**0.35
#  _POS_SUB_MEMO: (position, sub_role) -> (골기준치, 도움기준치, g_mult, a_mult)
# 둘 다 "같은 입력 → 같은 계산"을 캐시할 뿐이라 값이 비트 단위로 동일하다.
# 키 종류가 각각 수십 개 수준(경기수 값, 포지션×서브롤 조합)이라 메모리
# 부담이 없고, 세이브가 바뀌어도 상수에서만 유도되므로 초기화가 필요 없다.
_SCALE_MEMO = {}
_POS_SUB_MEMO = {}

# [2026-09 신설, 신민용 리포트: "GK도 득점은 가능하지, 무조건 하는게 문제인거지"]
# 실측(2005시즌 GK 25,670명): 0골 83.4% / 1골 13.3% / 2골 3.0% / 3골 0.2% /
# 4골 0.03% — 전 세계 GK의 1/6이 매 시즌 득점하는 상태였다. 원인은 두 가지가
# 겹친 것이다:
#   (1) AWARD_POS_GOAL/ASSIST(constants.py)에 GK 항목이 아예 없어서
#       .get(pos, 1) 기본값 1로 떨어졌다 — CB와 완전히 같은 기대치.
#   (2) 그 위에 팀 강도항(_d*0.2)이 포지션과 무관하게 그대로 더해졌다.
#       실측 d 분포는 p99에서 +8.16(=+1.63골), 최대 +12.41(=+2.48골)이라,
#       (1)을 고쳐 기준치를 0에 가깝게 낮춰도 강팀 GK는 여전히 2~3골을
#       "확정으로" 받는다 — GK 득점은 소속팀이 강하다고 늘어나는 성질의
#       기록이 아니므로 GK만 이 항의 계수를 0으로 둔다.
# 세트피스 담당 같은 새 능력치는 만들지 않는다(신민용 확정) — 기준치만
# 낮추고 기존 _tailed_season_mult의 꼬리(상위 0.5%에서 1.8~2.5배)로 "아주
# 드물게 2~3골 넣는 GK"를 그대로 남긴다.
#   pos -> (골 팀강도계수, 도움 팀강도계수).  미등록 포지션은 기존 (0.2, 0.1).
_POS_TEAM_STRENGTH_COEF = {"GK": (0.0, 0.0)}
_DEFAULT_TEAM_STRENGTH_COEF = (0.2, 0.1)


def _estimate_ai_season(ovr, pos, team_avg, league_avg, sub_role=None, full_season_matches=14,
                         goal_env_mult=1.0):
    """AI 선수의 시즌 성적(골/도움/평점)을 추정.

    [2026-09 신설, 신민용 요청: "국가별로 리그 득점 계수를 하나 두는 게
    좋다 — EPL 85 OVR ST와 베트남 85 OVR ST는 실제 득점 기대치가 달라야
    한다"] goal_env_mult: constants.get_goal_env_mult(country_name)에서
    구해 넘기는 국가별 득점 환경 배율(1.00=EPL/라리가 기준). 기본값 1.0
    (호출부가 안 넘기면 기존과 100% 동일하게 동작 — CL/CWC/월드11 후보
    풀처럼 특정 국가 하나로 좁혀지지 않는 범리그/국제 풀은 굳이 이 계수를
    적용하지 않고 기존 방식 그대로 둔다).
    [설계 변경] 골/도움은 더 이상 OVR로 스케일링하지 않는다 — 신민용 지적:
    "OVR 70이든 90이든 99든 같은 조건이어야 한다"(주전 스트라이커는 실력과
    무관하게 팀 내 슈팅 기회를 비슷하게 가져간다). 포지션별 고정 기준치
    (AWARD_POS_GOAL/ASSIST)에 소속팀 강도(team_avg-league_avg)만 살짝
    반영하고, 실력 차이는 rating(평점)에서만 OVR로 반영한다.
    [2026-07 신설] sub_role(인버티드/클래식윙어 등)별로 골:도움 비율을
    다르게 만든다 — _player_perf에 쓰는 _SUB_ROLE_MATCH_MOD를 그대로
    재사용해 두 계산 경로(내 선수 개별경기 vs AI 시즌추정)가 같은 기준을
    쓰게 한다.

    [2026-07 버그수정, 신민용 지적: "상 기준이 예전 14경기 설계 그대로인
    것 같다"] AWARD_POS_GOAL/ASSIST(constants.py)는 "14경기 풀시즌" 기준
    절대치로 주석에 명시돼 있는데, 이 함수는 실제 리그가 몇 경기짜리인지
    전혀 모른 채 그 절대치를 그대로 썼다. 이후 경기수 비례로 스케일하는
    수정을 넣었었지만(full_season_matches/14 선형 스케일), 이는 "시즌
    전체 기대 골 수"라는 상수의 설계 의도를 "경기당 득점 비율"로 잘못
    재해석한 것이었다 — 그 결과 20팀 리그(38경기)에서 ST가 56골, 30팀
    리그(58경기)에서는 76골까지 추정돼 실제 축구 통계(득점왕 24~35골
    선)를 크게 벗어났다.

    [2026-07 재수정, 신민용 확정: "상수(AWARD_POS_GOAL/ASSIST)는 이미
    밸런싱 끝난 값이니 건드리지 않는다. 대신 선형 스케일을 없애고
    완만한 지수 스케일만 적용한다"] 골/도움은 경기 수보다 선수 능력·
    전술·팀·운의 영향이 훨씬 크므로(반대로 클린시트는 경기 수 영향이
    커서 아래 _estimate_ai_clean_sheets의 38경기 기준 선형 스케일은
    유지), 리그 표준 규모(20팀=38경기)를 기준(scale=1.0)으로 삼아
    경기수 차이는 지수 0.35승만큼만 반영한다 — 28경기 0.90배, 46경기
    1.07배, 58경기 1.16배 정도로, 리그가 아무리 길어져도 득점이
    폭주하지 않는다."""
    # [2026-09 성능] 계산식·상수·랜덤 소비 순서는 그대로다. 바뀐 것은
    # (1) (team_avg-league_avg)를 두 번 계산하던 것을 한 번으로,
    # (2) max(0, ...) 이중 호출 제거 — round()에 넣는 값이 이미 음수가
    #     아니므로 바깥 max(0, ...)는 항상 무의미했다,
    # (3) random.uniform 인라인(위 _U08_* 주석 참고).
    # 실제 선수 6만 명 파라미터로 기존 구현과 결과 완전 일치 확인(×1.75).
    # [2026-09 성능 2차] 이 함수는 연도전환 한 번에 66만 번 호출된다
    # (리그 26만 + 대회별 40만). 계산식·상수·랜덤 소비 순서는 그대로 두고
    # 파이썬 레벨 연산 수만 줄인다:
    #  (1) scale = (fsm/38.0)**0.35 — fsm은 팀·대회마다 고정된 작은 정수라
    #      실제로 나오는 값이 수십 종류뿐이다. 나눗셈+거듭제곱을 매번 하지
    #      말고 메모한다(같은 입력에 같은 계산을 캐시하는 것이므로 비트
    #      단위로 동일한 float이 나온다).
    #  (2) AWARD_POS_GOAL / AWARD_POS_ASSIST / _SUB_ROLE_MATCH_MOD 3번
    #      조회를 (pos, sub_role) 키 하나로 합친다. mod가 없을 때는 배율
    #      1.0을 곱하는데, IEEE754에서 x*1.0은 x와 완전히 같은 값이라
    #      기존 "mod가 있을 때만 곱한다"와 결과가 다르지 않다.
    _sc = _SCALE_MEMO.get(full_season_matches)
    if _sc is None:
        _sc = _SCALE_MEMO[full_season_matches] = (full_season_matches / 38.0) ** 0.35
    scale = _sc
    _pskey = (pos, sub_role or "")
    _ps = _POS_SUB_MEMO.get(_pskey)
    if _ps is None:
        _m = _SUB_ROLE_MATCH_MOD.get(_pskey)
        _gd0, _ad0 = _POS_TEAM_STRENGTH_COEF.get(pos, _DEFAULT_TEAM_STRENGTH_COEF)
        _ps = _POS_SUB_MEMO[_pskey] = (
            AWARD_POS_GOAL.get(pos, 1), AWARD_POS_ASSIST.get(pos, 1),
            _m.get("g_mult", 1.0) if _m else 1.0,
            _m.get("a_mult", 1.0) if _m else 1.0,
            _gd0, _ad0)
    _gp, _ap, _gm, _am, _gd, _ad = _ps
    _d = team_avg - league_avg
    g_base = (_gp + _d*_gd) * scale * goal_env_mult * _gm
    a_base = (_ap + _d*_ad) * scale * goal_env_mult * _am
    if g_base < 0.0:
        g_base = 0.0
    if a_base < 0.0:
        a_base = 0.0
    goals = round(g_base * _tailed_season_mult(_rand()))
    assists = round(a_base * _tailed_season_mult(_rand()))
    # [2026-07 재보정, 신민용 수비수 QA 확정: "AI 후보(rating~7.8, OVR95)가
    # 실제 시뮬레이션 결과(_player_perf 기반, 같은 OVR95 CB 실측 평균
    # rating~7.2)보다 항상 후하게 나와서 베스트11/MVP/올해의 수비수 후보
    # 경쟁에서 실제 플레이한 내 선수가 구조적으로 밀린다"] OVR→평점
    # 기울기(/20.0)가 실제 엔진의 dominance 압축(고OVR끼리 붙으면 평점이
    # 완만하게만 오르는 구조)을 전혀 반영 못 하고 선형으로 계속 올라가는
    # 게 원인이었다. 실측 CB OVR99·8시즌 평균(rating 7.20)을 기준점으로
    # 기울기를 /20.0→/35.0으로 완화했다 — OVR60→6.0(불변), OVR95→~7.0,
    # OVR99→~7.11(+goals/assists 소폭 가산)로 실측 범위에 맞춘다. 골/도움
    # 가산(goals*0.02/assists*0.015)은 그대로 유지 — 다득점 시즌(ST 등)이
    # 여전히 그만큼 더 높게 평가되는 구조는 보존한다.
    rating = round(6.0 + (ovr-60)/35.0 + goals*0.02 + assists*0.015, 2)
    # [2026-07 버그수정, 신민용 리포트(GPT 분석 인용): "K3/K4처럼 약한
    # 리그에서 평점 5.0~5.8 정도의 평범한 시즌으로도 베스트11을 계속
    # 받는다"] 원인은 이 하한(5.0)이었다 — OVR이 낮은 약체 리그에서는
    # 공식(6.0 + (ovr-60)/20)이 자연스럽게 5.0 밑으로 내려가야 정상인데,
    # 강제로 5.0 바닥에 몰아버리니 그 리그의 AI 후보 전원이 사실상 거의
    # 같은 값(5.0 근방)에 뭉치게 됐다. 그러면 내 선수가 딱히 잘한 것도
    # 아닌 평범한 시즌(5.0~5.8)만 보내도 "바닥에 몰린 AI 풀"보다 쉽게
    # 이겨버려서 베스트11/MVP를 계속 가져가는 현상이 생겼다. 하한을 3.0
    # 으로 낮춰서 약체 리그 AI끼리도 실력 차이(낮은 OVR일수록 더 낮은
    # 평점)가 제대로 갈리게 한다.
    if rating < 3.0:
        rating = 3.0
    elif rating > 9.5:
        rating = 9.5
    return goals, assists, rating


def _make_season_estimate_rng(scope: str, year, salt=None):
    """[2026-09 신설, NumPy 난수 결정화] estimate_ai_season_batch 전용 numpy
    Generator를 (월드 salt, 연도, scope)에서 결정론적으로 만든다.

    왜 이게 필요한가: 이 함수가 생기기 전 estimate_ai_season_batch는
    np.random.random(전역 legacy RandomState)을 썼는데, 그 스트림엔 아무도
    시드를 주지 않는다 — 파이썬 random 모듈을 고정 시드로 돌려도 이 추정치만은
    실행마다 달라졌고, 그 차이가 _apply_ace_concentration의 분기(골/도움)를
    가르면서 파이썬 난수 소비 횟수까지 바꿔 세계 전체가 갈라졌다(같은 세이브·
    같은 시드로 400일 2회 실측: 파이썬 rng_calls 3,057,664 vs 3,059,368,
    선수 122명·이적 279건 차이). 2026-08에 _age_and_progress에서 고친 것과
    같은 병이다.

    [설계] _age_and_progress처럼 random.getrandbits()로 시드를 뽑지 않는다 —
    그러면 파이썬 전역 스트림을 호출마다 1회씩 소비해서, 나중에 파이썬 쪽
    난수 순서를 바꾸는 최적화를 할 때마다 무관해야 할 시즌 스탯 추정치까지
    통째로 흔들린다. 대신 _make_goal_seed과 완전히 같은 철학으로, 결정적인
    입력(salt/연도/scope)을 crc32로 접어 시드를 만든다 — 파이썬 스트림을 한
    번도 건드리지 않으므로 두 난수 스트림이 완전히 분리된다.

    scope는 호출부가 리그/대회별로 반드시 다르게 준다(league, comp:cup,
    comp:cl, ...). 같은 scope를 쓰면 두 대회가 같은 난수열을 받는다."""
    import zlib
    if salt is None:
        from database import get_world_salt
        salt = get_world_salt()
    key = f"{salt}:{year}:{scope}:season_stat_estimate"
    seed = zlib.crc32(key.encode("utf-8")) & 0xFFFFFFFF
    import numpy as _np
    return _np.random.default_rng(seed)


def estimate_ai_season_batch(ovr, pos, sub_role, team_avg, league_avg, fsm, goal_env_mult,
                              rng=None):
    """_estimate_ai_season + _estimate_ai_clean_sheets + _estimate_ai_gk_saves를
    선수 묶음 단위로 한 번에 계산한다(numpy). 입력은 모두 길이 n의 시퀀스.
    반환: (goals, assists, rating, clean_sheets, saves, goals_conceded) — 전부
    길이 n의 파이썬 리스트(sqlite에 그대로 넣을 수 있는 int/float).

    [2026-09 신설, 신민용 확정: "기존 세이브는 신경쓸 필요 없어"] 계산식은
    한 줄도 바꾸지 않고(같은 계수·같은 분포·같은 상·하한·같은 반올림 규칙),
    "한 명씩 파이썬으로 도는 것"만 배열 연산으로 바꾼다. 난수는 선수마다
    같은 개수·같은 용도로 뽑되 뽑는 순서(random 모듈 → numpy)가 달라지므로
    개별 선수의 성적은 예전 실행과 달라진다 — 분포는 같다(시즌평점/득점
    분포로 검증). 43주차 스냅샷에서만 69만 회 호출되던 구간이다.
    """
    import numpy as _np
    # [2026-09 신설, NumPy 난수 결정화] rng는 _make_season_estimate_rng이
    # 만들어 넘기는 결정론적 Generator다. 안 넘어오면(옛 호출부·테스트) 예전
    # 그대로 시드 없는 전역 난수를 쓴다 — 계산은 100% 같지만 재현은 안 된다.
    _rr = rng if rng is not None else _np.random
    n = len(ovr)
    if n == 0:
        return [], [], [], [], [], []
    ovr_a = _np.asarray(ovr, dtype=_np.float64)
    ta = _np.asarray(team_avg, dtype=_np.float64)
    la = _np.asarray(league_avg, dtype=_np.float64)
    fsm_a = _np.asarray(fsm, dtype=_np.float64)
    gem = _np.asarray(goal_env_mult, dtype=_np.float64)
    # 포지션·서브롤별 상수(_POS_SUB_MEMO와 같은 값) — 종류가 수십 개뿐이라
    # 고유 조합만 계산해서 인덱스로 펼친다.
    gp = _np.empty(n); ap = _np.empty(n); gm = _np.empty(n); am = _np.empty(n)
    gd = _np.empty(n); ad = _np.empty(n)
    _seen = {}
    for i in range(n):
        key = (pos[i], sub_role[i] or "")
        v = _seen.get(key)
        if v is None:
            _ps = _POS_SUB_MEMO.get(key)
            if _ps is None:
                _m = _SUB_ROLE_MATCH_MOD.get(key)
                _gd0, _ad0 = _POS_TEAM_STRENGTH_COEF.get(key[0], _DEFAULT_TEAM_STRENGTH_COEF)
                _ps = _POS_SUB_MEMO[key] = (
                    AWARD_POS_GOAL.get(key[0], 1), AWARD_POS_ASSIST.get(key[0], 1),
                    _m.get("g_mult", 1.0) if _m else 1.0,
                    _m.get("a_mult", 1.0) if _m else 1.0,
                    _gd0, _ad0)
            v = _seen[key] = _ps
        gp[i], ap[i], gm[i], am[i], gd[i], ad[i] = v
    scale = (fsm_a / 38.0) ** 0.35
    d = ta - la
    g_base = _np.maximum((gp + d * gd) * scale * gem * gm, 0.0)
    a_base = _np.maximum((ap + d * ad) * scale * gem * am, 0.0)

    def _tailed(u):      # _tailed_season_mult의 배열판(구간·계수 동일)
        return _np.select(
            [u < _TAIL_P1, u < _TAIL_P2, u < _TAIL_P3],
            [_U08_LO + _U08_SPAN * (u / _TAIL_P1),
             1.20 + 0.30 * ((u - _TAIL_P1) / (_TAIL_P2 - _TAIL_P1)),
             1.50 + 0.30 * ((u - _TAIL_P2) / (_TAIL_P3 - _TAIL_P2))],
            1.80 + 0.70 * ((u - _TAIL_P3) / (1.0 - _TAIL_P3)))

    goals = _np.round(g_base * _tailed(_rr.random(n)))
    assists = _np.round(a_base * _tailed(_rr.random(n)))
    rating = _np.clip(_np.round(6.0 + (ovr_a - 60.0) / 35.0
                                + goals * 0.02 + assists * 0.015, 2), 3.0, 9.5)
    # 클린시트(_estimate_ai_clean_sheets와 동일 식)
    cs = _np.maximum(_np.round(
        7.5 * (1.0 + d * 0.03) * (1.0 + _np.maximum(ovr_a - 70.0, 0.0) * 0.01)
        * (fsm_a / 38.0) * (_U08_LO + _U08_SPAN * _rr.random(n))), 0.0)
    # GK 세이브/실점(_estimate_ai_gk_saves와 동일 식) — GK만 계산
    saves = _np.zeros(n); conceded = _np.zeros(n)
    gk = _np.fromiter((p == "GK" for p in pos), dtype=bool, count=n)
    if gk.any():
        k = _np.flatnonzero(gk)
        spg = _np.clip(_GK_SHOTS_PER_MATCH_BASE * (1.0 - d[k] * 0.01), 2.0, 7.0)
        shots = _np.maximum(_np.round(
            spg * fsm_a[k] * (_U085_LO + _U085_SPAN * _rr.random(k.size))), 0.0)
        base_pct = 0.60 + _np.clip(ovr_a[k] - 50.0, 0.0, 50.0) / 50.0 * 0.28
        save_pct = _np.clip(base_pct + d[k] * 0.001
                            + (_U005_LO + _U005_SPAN * _rr.random(k.size)), 0.45, 0.92)
        sv = _np.round(shots * save_pct)
        saves[k] = sv
        conceded[k] = _np.maximum(shots - sv, 0.0)
    return ([int(x) for x in goals], [int(x) for x in assists],
            [float(x) for x in rating], [int(x) for x in cs],
            [int(x) for x in saves], [int(x) for x in conceded])


def _estimate_ai_clean_sheets(pos, ovr, team_avg, league_avg, full_season_matches=14):
    """[2026-07 신설] GK AI 후보의 시즌 클린시트 추정 — 팀 평균 대비
    소속팀 전력(team_avg-league_avg)과 GK 본인 OVR을 같이 반영한다.
    실제 골든글러브 판정 기준(season_cs>=10, 38경기 기준)과 같은 축으로
    맞추기 위해, 38경기 기준 클린시트 베이스를 잡고 리그 길이로 스케일."""
    # [2026-07 재보정, 신민용 수비수 QA 확정] base_cs_per_38=11.0은
    # SS등급(전원 엘리트) 환경에서 실측된 실제 CB 클린시트(OVR99·8시즌
    # 평균 7.75)보다 크게 높았다 — team_factor가 (team_avg-league_avg)
    # 기준이라 "모든 팀이 엘리트"인 SS리그에서는 사실상 0에 수렴해
    # 보정이 안 먹히고, ovr_factor만으로 OVR95+ 선수 전원이 CS 13~17에
    # 몰렸다. 실측 평균(7.75)에 맞춰 7.5로 낮춘다.
    base_cs_per_38 = 7.5  # 평균적 GK의 38경기 기준 클린시트 베이스
    team_factor = 1.0 + (team_avg - league_avg) * 0.03      # 강팀일수록 클린시트↑
    ovr_factor = 1.0 + max(0, ovr - 70) * 0.01                # GK 본인 실력도 소폭 반영
    scale = full_season_matches / 38.0
    cs = base_cs_per_38 * team_factor * ovr_factor * scale * (_U08_LO + _U08_SPAN * _rand())
    return max(0, round(cs))


# [2026-09 신설, 신민용+GPT 협의: "concede_score(_score_ballon_candidate)에서
# matches 대신 shots_faced로 역산할 때 쓰는 경기당 피슈팅수를 여기 있는
# 4.2와 다른 값으로 하드코딩하면, 나중에 이 값을 튜닝할 때 선방 생성과
# 발롱도르/야신상 채점이 서로 다른 기준을 쓰게 된다"] 두 곳이 항상 같은
# 값을 쓰도록 이름 붙은 상수 하나로 뺀다.
_GK_SHOTS_PER_MATCH_BASE = 4.2


def _estimate_ai_gk_saves(ovr, team_avg, league_avg, full_season_matches=14):
    """[2026-09 신설, 신민용 요청: "클린시트 말고 선방:14 실점:1 선방률:
    93.5% 이런식으로 떠야한다"] 이 함수도 위 _estimate_ai_season/_estimate_
    ai_clean_sheets와 완전히 같은 철학이다 — 이 게임은 개별 슈팅이든
    개별 골이든 실제로 이벤트 단위로 시뮬레이션하지 않는다(그건 GK뿐
    아니라 골/도움/평점도 전부 마찬가지 — _estimate_ai_season도 실제
    슈팅 데이터가 아니라 포지션·OVR·팀전력 기반 통계적 추정치다). 그러니
    "선방률" 역시 같은 방식(GK 본인 OVR+소속팀 전력으로 통계적으로
    그럴듯한 수치를 추정)으로 얼마든지 만들 수 있다 — "개별 슈팅을
    시뮬레이션 안 해서 못 만든다"는 이전 답변은 틀렸다.

    설계: (1) 경기당 피슈팅수 기준치(4.2, 리그 평균 유효슈팅 실측 근사)에서
    소속팀이 평균보다 강할수록 상대의 유효슈팅 자체가 줄어든다고 보고
    낮춘다. (2) 기본 선방률은 GK 본인 OVR에서 산출(OVR50→60%, OVR99→
    약 88% — [2026-09 재보정] 원래 OVR60→64%/OVR99→79.6% 폭(20%p)이던
    것을, "같은 팀 GK끼리 OVR 차이가 커도 선방률이 안 갈린다"는 실측
    리포트로 28%p 폭으로 넓힘 — 아래 team_bonus/개인 노이즈 상수 주석
    참고)하고 소속팀 전력에 따라 소폭 가산(강팀 뒤에서는 상대적으로 질
    좋은 기회만 걸러져 옴). (3) 피슈팅수×선방률로 선방을, 나머지를
    실점으로 역산해 saves+conceded=shots_faced가 항상 정확히 맞물리게
    한다(표시 시점에 선방률을 saves/(saves+conceded)로 재계산해도 항상
    일치).
    반환: (saves, goals_conceded)."""
    shots_per_game = max(2.0, min(7.0, _GK_SHOTS_PER_MATCH_BASE * (1.0 - (team_avg - league_avg) * 0.01)))
    shots_faced = max(0, round(shots_per_game * full_season_matches
                                * (_U085_LO + _U085_SPAN * _rand())))
    # [2026-09 재보정] OVR 신호 폭 0.20→0.28(위 _U005_* 주석 참고) —
    # OVR 50→60%, OVR 99→약 88%.
    base_save_pct = 0.60 + max(0, min(50, ovr - 50)) / 50.0 * 0.28
    team_bonus = (team_avg - league_avg) * 0.001
    save_pct = max(0.45, min(0.92, base_save_pct + team_bonus
                              + (_U005_LO + _U005_SPAN * _rand())))
    saves = round(shots_faced * save_pct)
    goals_conceded = max(0, shots_faced - saves)
    return saves, goals_conceded


def _cap_additive_bonus(raw_bonus: float, base_score: float, cap_ratio: float = 0.10) -> float:
    """[2026-07 신설, GPT 2차 피드백 반영: "빅게임 보너스도 상한이 있어야
    한 경기 때문에 MVP가 뒤집히는 걸 막을 수 있다"] 결승/준결승 같은
    빅게임 활약을 '가산'으로 얹을 때, 기준 점수(base_score)의 cap_ratio
    (기본 10%)를 넘지 못하게 상한을 씌운다. 원본 GPT 제안은 고정 숫자
    (+0.3 등)였지만, 그러면 결승 평점 6점과 9점이 같은 보너스를 받는
    문제가 있어 '실제 빅게임 기록에서 계산한 값에 상한만 씌우는' 방식으로
    수정했다."""
    if base_score <= 0 or raw_bonus <= 0:
        return 0.0
    cap = base_score * cap_ratio
    return max(0.0, min(raw_bonus, cap))


def _gk_quality_ok(saves: int, conceded: int, matches: int, full_season_matches: float,
                    min_play_ratio: float = 0.35,
                    min_save_pct: float = 0.65, max_ga_rate: float = 1.3) -> bool:
    """[2026-07 신설, GPT 피드백: "골든글러브가 클린시트 개수만 본다,
    세이브율·평균실점도 반영해야 한다"] AI 골키퍼는 클린시트 추정치만
    있고 세이브·실점 자체를 추정하지 않으므로, 세이브율·평균실점을 AI와
    직접 비교할 방법이 없다 — 그래서 'AI 대비 클린시트 1위'라는 기존
    비교 기준은 그대로 두고, 내 선수 자신의 세이브율·평균실점이 최소
    품질 기준을 넘는지를 별도 게이트로 추가한다. 세이브율만 보면 "많이
    맞고 많이 막아서 세이브율만 높은 약팀 골키퍼"가 유리해질 수 있어
    평균 실점 상한도 같이 요구한다. 표본이 너무 적으면(최소 출전 비율
    미달) 신뢰할 수 없으므로 무조건 탈락시킨다."""
    min_m = max(6, round(min_play_ratio * full_season_matches))
    if matches < min_m:
        return False
    save_pct = saves / (saves + conceded) if (saves + conceded) > 0 else 0.0
    ga_rate = conceded / matches if matches > 0 else 999.0
    return save_pct >= min_save_pct and ga_rate <= max_ga_rate


def _team_rank_mult(team_rank: int, n_teams: int) -> float:
    """[2026-07 신설, 신민용 확정: "꼴찌 팀 센터백이 리그 베스트11인 건
    현실에서 상당히 드문 사례"] 베스트11/MVP 점수가 순수 개인 활약(평점·
    클린시트·골·도움)만 보고 팀 성적은 전혀 안 봤다 — 실제 축구는 개인
    활약 80~90% + 팀 성적 10~20% 정도가 항상 섞인다(같은 실점이어도
    "우승팀 수비수"와 "꼴찌팀 수비수"는 심사에서 다르게 보임). 큰 페널티
    (예: 1위 +20%, 꼴찌 -20%)는 반대 — 그러면 개인 성적 좋은 선수가
    팀 사정만으로 떨어지는 경우가 너무 많아진다. 대신 순위를 4분위로
    나눠 아주 작은 보정만 준다 — "당락선에 있는 애매한 선수만 걸러내는"
    정도. 좋은 시즌(예: 평점 7.2)은 이 보정을 받아도 여전히 수상권이고,
    애매한 시즌(예: 평점 6.7 + 꼴찌팀)만 자연스럽게 탈락하게 된다."""
    if n_teams <= 1:
        return 1.0
    pct = team_rank / n_teams   # 0에 가까움=최상위, 1에 가까움=최하위
    if pct <= 0.25:
        return 1.03
    elif pct <= 0.5:
        return 1.01
    elif pct <= 0.75:
        return 1.00
    else:
        return 0.97


def _league_team_ranks(c, league_id) -> dict:
    """그 리그 팀들의 순위(1부터)를 {team_id: rank} 딕셔너리로 반환.
    승점(승*3+무) → 득실차 순으로 정렬 — 승강제 판정과 별개로 상 심사용
    '대략적인' 순위라 match_results 재계산 없이 teams 누적치를 그대로 쓴다."""
    rows = c.execute(
        """SELECT id, wins, draws, losses, goals_for, goals_against
           FROM teams WHERE league_id=?""", (league_id,)).fetchall()
    ranked = sorted(rows, key=lambda r: (-(r["wins"]*3 + r["draws"]),
                                          -(r["goals_for"] - r["goals_against"])))
    return {r["id"]: i + 1 for i, r in enumerate(ranked)}, len(ranked)


def _position_award_score(pos, goals, assists, rating, ovr, cs=0):
    """[2026-07 신설, 신민용 지적: "MVP가 무조건 공격수 유리한 공식(_best11_score)을
    전 포지션에 그대로 쓴다"] MVP/월드컵 골든볼/챔스 시즌MVP처럼 '포지션 무관,
    그 대회 최고의 선수 1명'을 뽑는 상에 쓰는 포지션별 가중 점수식.
    _best11_score(포워드 전용, 골 가중치 높음)와 달리, 포지션마다 실제로
    영향력을 만드는 경로가 다르다는 걸 반영한다:
      - GK: 클린시트·평점이 압도적 비중(골/도움은 사실상 없는 포지션)
      - DF: 평점 비중을 높이고, 공격포인트는 보조적으로만
      - MF: 어시스트(창조력) 비중을 골보다 높게
      - FW: 기존 _best11_score와 동일(골 비중 최고)
    """
    if pos in GK_POS:
        return cs * 3.0 + rating * 8.0 + ovr * 0.3
    if pos in DF_POS:
        return goals * 1.0 + assists * 1.5 + rating * 7.0 + ovr * 0.3
    if pos in MF_POS:
        return goals * 1.5 + assists * 2.0 + rating * 6.0 + ovr * 0.3
    return goals * 2.0 + assists * 1.0 + rating * 5.0 + ovr * 0.3  # FW/기타


def _club_award_score(pos, goals, assists, rating, ovr, cs=0):
    """[2026-07 신설, 신민용 확정] 구단 올해의 선수(Club Player of the
    Year) 전용 점수식. 리그 MVP(_position_award_score)와 포지션별 계수를
    그대로 쓰면 "리그 최고"와 "구단 내 최고"가 사실상 같은 기준이 되어
    성격이 겹친다 — 이 상은 "그 팀에서 가장 중요했던 선수"라는 더 넓은
    개념이라, 포지션 구분 없이 단일 공식으로 골/도움/평점/OVR/클린시트를
    고르게 반영해서 공격수 쏠림을 줄이고 수비수·GK도 자기 팀에서는
    핵심으로 평가받을 여지를 준다. 후보 풀 자체가 이미 내 팀 로스터로
    좁혀져 있으므로(club_pool), 점수식은 MVP보다 단순하게 유지한다.
    """
    return rating * 50.0 + goals * 2.0 + assists * 2.0 + ovr * 0.5 + cs * 1.0


def _rank_among_ai(my_val, ai_vals_desc):
    """[2026-09 신설, 공유함수] 내 값이 AI 값들(내림차순 정렬된 리스트) 사이에서
    몇 등인지(1부터) 반환 — 동점이면 내가 우선(기존 관례 유지). 원래
    intl_engine._award_intl_awards 안에 로컬 함수로 중복 정의돼 있던 걸
    여기로 뽑아 도메스틱(베스트11 top-K 등)과 국제대회 양쪽이 공유한다."""
    rank = 1
    for v in ai_vals_desc:
        if v > my_val:
            rank += 1
        else:
            break
    return rank


# [2026-09 신설] 베스트11 포지션군별 정원 — 기존 주석에 이미 있던 실제
# 포메이션(GK1/DF4/MF3/FW3) 그대로. "그룹 1등만 수상"에서 "그 정원만큼
# 상위권 전원 수상"으로 바뀌면서 상수로 뽑음.
_BEST11_GROUP_SLOTS = {"GK": 1, "DF": 4, "MF": 3, "FW": 3}


# [2026-09 신설, 신민용 확정: "주전은 출전 70% 이상, 로테는 40~70%,
# 대기는 40% 미만 — 이 %를 코드에 넣을 필요는 없고 역할 자체가 그
# 요약이니 이걸 토대로 수상을 설계하면 된다"] 수상 후보 자격에서
# 제외되는 역할. 원래 _get_ballon_candidates 안에 지역 상수
# (_EXCLUDED_ROLES)로만 있어서 발롱도르/야신상에만 걸렸는데, 평점 기반
# 상(베스트11/영플레이어/올해의 수비수/리그 MVP)에는 전혀 안 걸려 있었다
# — "38경기 중 14경기만 뛴 고평점 선수가 베스트11에 뽑힌다"는 문제가
# 정확히 그 구멍이다. 모듈 레벨로 올려 양쪽이 같은 자격 기준을 쓰게 한다.
#
# [설계 확정, 왜 계수가 아니라 게이트인가] 역할별 점수 계수(주전 1.0 /
# 로테 0.9 ...)를 평점에 곱하는 안을 검토했으나 두 가지 이유로 기각했다.
#   (1) 이중 페널티 — _apply_squad_depth_decay가 이미 역할을 보고 골·
#       도움·클린시트·선방을 깎고 있다(대기 ×0.18 / 전력외 ×0.07).
#       _get_ballon_candidates 주석이 같은 이유로 "점수가 아니라 후보
#       자격 쪽에만 건다"고 명시해뒀다 — 그 판단을 그대로 따른다.
#   (2) 스케일 붕괴 — AI 평점은 6.0 + (ovr-60)/35 + ... 라서 실질 편차가
#       1.0 남짓인데, 여기 0.9를 곱하면 7.0이 6.3이 되어 역할 하나가
#       다른 모든 항을 압도한다(깎이는 0.7이 전체 편차의 70%).
# 게이트로 가면 계수값을 정할 필요 자체가 없고, "주전/로테는 후보,
# 대기/전력외/유망주는 제외"라는 원안이 그대로 규칙이 된다.
_AWARD_EXCLUDED_ROLES = ("대기", "전력외", "유망주")


def _role_award_eligible(role) -> bool:
    """그 시즌 역할(hist.ai_player_position_history.role)이 수상 후보
    자격을 갖는가. role이 비어 있으면(이 기능 신설 이전 과거 시즌,
    아직 역할 스냅샷이 없는 경로, 애초에 role을 안 싣는 국제대회 풀)
    무조건 통과시킨다 — _get_ballon_candidates가 이미 쓰고 있는 원칙
    그대로다: "데이터 공백을 자격 박탈로 오인하면 안 됨".

    이 관용 규칙 덕분에 게이트를 공용 픽 함수(_pick_comp_extra_winners)에
    걸어도 role을 싣지 않는 풀에서는 자동으로 무효가 된다 — 국제대회는
    클럽 역할이 아니라 실제 출전수(intl_squad.appearances)를 쓰는 것이
    맞으므로, 그쪽 동작은 이 게이트 도입 전과 100% 동일하게 유지된다."""
    return not role or role not in _AWARD_EXCLUDED_ROLES


def _role_from_play_ratio(matches, full_season_matches) -> str:
    """내 선수 전용 — 실제 출전수를 AI와 같은 역할 라벨로 환산한다.

    [왜 내 선수만 따로 환산하나] AI의 역할은 스쿼드 내 OVR 순위로 근사한
    값이지만(formation_logic.compute_squad_roles), 내 선수는 진짜 출전
    기록이 있다. 같은 게이트를 걸려면 둘을 같은 축으로 올려놔야 하는데,
    내 선수를 OVR 순위로 근사하는 건 있는 실측값을 버리는 짓이다 —
    반대로 실측값을 역할 라벨로 올리면 AI와 같은 기준으로 비교된다.

    구간은 신민용이 확정한 값 그대로다(주전 70%+ / 로테이션 40~70% /
    대기 40% 미만). 이 비율이 게임 규칙으로 코드 여기저기 퍼지면 안 되므로
    쓰는 곳은 이 함수 하나뿐이고, 나머지는 전부 역할 라벨로만 이야기한다.
    "전력외"는 내보내지 않는다 — AI 쪽에서 그 라벨은 마지막 구간의 성인
    선수라는 뜻(나이로 유망주와 갈린 결과)이지 출전 0을 뜻하지 않아서,
    출전 비율만 보고 같은 라벨을 붙이면 의미가 어긋난다. 게이트 기준으로는
    "대기"와 어차피 동일하게 탈락 처리된다."""
    if not full_season_matches or full_season_matches <= 0:
        return "주전"      # 분모를 모르면 자격을 박탈하지 않는다(위와 같은 원칙)
    ratio = (matches or 0) / full_season_matches
    if ratio >= 0.70:
        return "주전"
    if ratio >= 0.40:
        return "로테이션"
    return "대기"


def _evaluate_extra_awards(pool, my_pos, my_age=25, weight_fn=None, young_age_cutoff=21):
    """[2026-09 재설계, 신민용 확정: "베스트11은 포지션별로 평점 최상위
    (포메이션 정원만큼)가 받고, 영플레이어는 어린 선수 중 평점 1위가
    받는 원리가 맞다"] 기존엔 골/도움/OVR/클린시트를 섞은 가중치 공식
    (_best11_score 등)으로 그룹 1등 한 명만 뽑았는데, 이제 순수 평점
    하나로만 비교하고 — 베스트11은 실제 포메이션 정원(GK1/DF4/MF3/FW3,
    _BEST11_GROUP_SLOTS)만큼 상위권 전원에게 준다. 내 평점이 내가 속한
    그룹의 AI들 중 그 정원 등수 안에 들면(동점은 나 우선, _rank_among_ai)
    수상. weight_fn(팀순위/국제대회 진출라운드 가중치)은 기존처럼 베스트11
    비교에만 적용하고, 영플레이어는 순수 평점만 본다(가중치 없음 — 리그
    쪽 기존 관례를 국제대회 쪽에도 통일).

    pool의 각 원소는 {"position","rating","age","is_mine"} 키만 있으면
    된다(goals/assists/ovr/cs는 더 이상 안 씀). 반환: 내가 받은 상 이름
    리스트(예: ["베스트11","영플레이어"])."""
    def _w(x):
        return weight_fn(x) if weight_fn else 1.0
    won = []
    # [2026-09 신설] "내가 받았는가" 판정도 세계 수상자 산출(_pick_comp_
    # extra_winners)과 같은 역할 게이트를 써야 둘이 안 어긋난다 — role을
    # 안 싣는 풀에서는 _role_award_eligible이 전부 True라 무효가 된다.
    pool = [x for x in pool if _role_award_eligible(x.get("role"))] or pool
    _grp_pos = {"GK": GK_POS, "DF": DF_POS, "MF": MF_POS, "FW": FW_POS}
    for gname, poslist in _grp_pos.items():
        if my_pos not in poslist:
            continue
        group = [x for x in pool if x["position"] in poslist]
        me = next((x for x in group if x["is_mine"]), None)
        if me is None:
            break
        ai_vals = sorted((x["rating"] * _w(x) for x in group if not x["is_mine"]), reverse=True)
        my_val = me["rating"] * _w(me)
        if _rank_among_ai(my_val, ai_vals) <= _BEST11_GROUP_SLOTS[gname]:
            won.append("베스트11")
        break

    young_cands = [x for x in pool if x.get("age", 30) <= young_age_cutoff]
    if young_cands:
        best_young = max(young_cands, key=lambda x: x["rating"])
        if best_young["is_mine"]:
            won.append("영플레이어")
    return won


def _best11_score(goals, assists, rating, ovr):
    """FW(포워드) 포지션용 점수식 — 골 가중치 높음"""
    return goals*2 + assists*1.0 + rating*5 + ovr*0.3


def _best11_score_gk_df(clean_sheets, rating, ovr):
    """GK/DF(골키퍼, 수비수) 포지션용 점수식 — 클린시트 가중치"""
    return clean_sheets*2.5 + rating*5 + ovr*0.3


def _best11_score_mf(goals, assists, rating, ovr):
    """MF(미드필더) 포지션용 점수식 — 골과 도움 균형"""
    return goals*1.5 + assists*1.5 + rating*5 + ovr*0.3


def _team_goal_scale_factors(team_estimated_goals, team_goals_for):
    """[2026-09 신설, 신민용 리포트: "세계 축구 기록실에 뜨는 골(_snapshot_
    season_ratings, hist.ai_player_season_stats)은 팀 실제 득점에 맞게
    보정됐는데, 득점왕/도움왕 같은 개인수상 판정(_process_awards→
    _collect_league_candidates)은 여전히 순수 OVR 추정치라 서로 안 맞을 수
    있다"] — "화면에 보이는 골"과 "수상 판정에 쓰이는 골"이 항상 같은
    보정을 받도록, ai_lifecycle._snapshot_season_ratings와 여기
    _collect_league_candidates가 이 함수 하나를 공유한다.

    team_estimated_goals: {team_id: 그 팀 선수 전원의 _estimate_ai_season
      골 합계}, team_goals_for: {team_id: 그 팀이 이번 시즌 실제로 넣은 골
      (teams.goals_for 스냅샷)}. 반환: {team_id: scale_factor}(실제/추정
      비율) — 실제값이 없거나 0이거나 추정합계가 0인 팀은 키 자체가
      없으므로, 호출부는 항상 .get(tid)이 None이면 원본 그대로 둔다."""
    scale = {}
    for tid, real_total in (team_goals_for or {}).items():
        est_total = team_estimated_goals.get(tid, 0)
        if real_total and real_total > 0 and est_total > 0:
            scale[tid] = real_total / est_total
    return scale


def _alloc_int_by_weights(weights, total):
    """가중치에 비례해 정수 total개를 배분한다(최대잔여법 / Hare quota).

    반환 리스트의 합은 정확히 total이고, 어떤 항목도 total을 넘지 않는다.
    동점 잔여는 인덱스 순으로 깨므로 같은 입력이면 항상 같은 결과 —
    난수를 전혀 쓰지 않아 재현성에 영향이 없다."""
    n = len(weights)
    if n == 0 or total <= 0:
        return [0] * n
    s = 0.0
    for w in weights:
        if w > 0:
            s += w
    if s <= 0:
        return [0] * n
    raw = [(w * total / s) if w > 0 else 0.0 for w in weights]
    base = [int(x) for x in raw]
    rem = total - sum(base)
    if rem > 0:
        # [2026-09 성능, 43주차 스냅샷] 정렬 키를 파이썬 람다(호출당 튜플
        # 1개 생성 + raw/base 인덱싱 2번)에서 미리 계산한 리스트의 C 레벨
        # __getitem__으로 바꾼다. 잔여가 같을 때의 순서는 sorted가 안정
        # 정렬이라 range(n)의 오름차순 인덱스가 그대로 유지되므로, 예전
        # (-(잔여), i) 튜플 키와 결과가 비트 단위로 같다(동점 케이스만
        # 6천 건 포함한 12,000 케이스 대조: 전부 일치).
        _negfrac = [b - x for x, b in zip(raw, base)]
        order = sorted(range(n), key=_negfrac.__getitem__)
        for i in order[:rem]:
            base[i] += 1
    return base


def _apply_team_goal_budget(rows, key_fn, team_goals_for, allow_zero=False):
    """[2026-09 신설, 신민용 확정: "모든 대회가 그렇게 되어야 한다"]
    팀이 그 대회에서 실제로 넣은 골 수에 '정확히' 맞춰 선수들에게 정수로
    나눠준다. rows는 {"goals","assists"}를 가진 dict 리스트(in-place 수정),
    key_fn(row)은 팀 식별자(리그·클럽대항전은 team_id, 국제대회는
    (대회, 국가)), team_goals_for는 {키: 실제 득점}.

    예전 방식(_team_goal_scale_factors로 계수만 구해 선수마다 곱하고
    각자 반올림)은 합계가 목표와 크게 어긋났다. 컵처럼 한 팀이 1~3경기만
    뛰고 2골 넣는 대회에서는 23명 전원의 몫이 0.5 미만이 되어 통째로 0으로
    내려앉거나(팀 득점이 증발), 반대로 몇 명이 올라가 팀 합계를 넘겼다 —
    2002 헤드리스 실측에서 국내컵 팀별 "AI 골합/실제 골"의 중앙값이 0.50
    이었다. 최대잔여법으로 배분하면 합계가 목표와 정확히 같아지고, 어떤
    선수도 팀 득점을 넘을 수 없다(신민용 리포트의 "팀 11골인데 개인 14골"
    이 구조적으로 불가능해진다).

    도움은 그 팀의 추정 도움/추정 골 비율을 유지한 예산으로 같은 방식
    배분하되 실제 득점을 넘지 않게 자른다 — 한 골에 어시스트는 최대
    1개이므로 팀 도움 합계는 팀 득점을 넘을 수 없다.

    allow_zero: team_goals_for의 키가 "실제로 경기를 치렀고 0골"임이
      보장되는 호출부(대회별 집계·국제대회 — 둘 다 치른 경기 행에서만
      키를 만든다)만 True. True면 0골 팀의 선수 기록도 0으로 맞춘다.
      기본 False는 예전과 동일하게 0/음수는 건드리지 않고 넘어간다
      (리그는 teams.goals_for 전체를 넘겨받아 미집계 팀이 섞일 수 있음)."""
    if not team_goals_for:
        return
    groups: dict = {}
    # [2026-09 성능, 43주차 스냅샷] setdefault는 이미 있는 키에도 빈 리스트를
    # 매번 새로 만들어 넘긴다(56만 행이면 56만 개). get으로 먼저 보고 없을
    # 때만 만든다 — 그룹 구성도 그룹 안의 순서도 예전과 완전히 같다.
    _gget = groups.get
    for r in rows:
        _k = key_fn(r)
        _members = _gget(_k)
        if _members is None:
            groups[_k] = [r]
        else:
            _members.append(r)
    for k, members in groups.items():
        real = team_goals_for.get(k)
        if real is None:
            continue
        real = int(real)
        if real < 0 or (real == 0 and not allow_zero):
            continue
        # [2026-09 성능, 43주차 스냅샷] 예전엔 행마다 float()과 max()를
        # 각각 불렀다(56만 행 × 2필드 = 224만 회의 파이썬 호출). 값이
        # 양수면 float()만, 아니면 0.0 — None/0/음수/NaN 전부 예전
        # max(0.0, float(v or 0))과 같은 값이 나온다.
        gw = []
        aw = []
        _gwa = gw.append
        _awa = aw.append
        for m in members:
            _v = m.get("goals")
            _gwa(float(_v) if _v and _v > 0 else 0.0)
            _v = m.get("assists")
            _awa(float(_v) if _v and _v > 0 else 0.0)
        # [주의] 이 합계는 반드시 내장 sum()이어야 한다 — 파이썬 3.12의
        # sum()은 float에 보정합(Neumaier)을 쓰므로, 직접 루프로 더하면
        # 마지막 자리가 달라져 도움 예산과 배분 결과가 바뀐다(에이스
        # 집중 뒤의 대회 경로는 값이 float이라 실제로 해시가 깨졌다).
        g_sum, a_sum = sum(gw), sum(aw)
        g_alloc = _alloc_int_by_weights(gw, real)
        a_budget = 0
        if real > 0 and g_sum > 0:
            a_budget = min(real, int(round(real * a_sum / g_sum)))
        a_alloc = _alloc_int_by_weights(aw, a_budget)
        for m, g, a in zip(members, g_alloc, a_alloc):
            m["goals"], m["assists"] = g, a


# [2026-09 신설, 신민용 리포트: "팀 골이 30개면 애들이 골고루 나눠 갖는
# 것 같다 — 득점왕이 10골 정도밖에 안 된다"] 원인 진단: _estimate_ai_
# season의 득점 기대치는 포지션 고정 기준치(AWARD_POS_GOAL)에 ±20%
# 랜덤만 곱하고 OVR로는 전혀 스케일하지 않는다(의도된 설계 — 위 문서
# 참고). 그런데 한 팀 로스터엔 보통 같은 포지션에 주전 1명 + 백업
# 1~2명이 함께 있어서(예: ST 2명), 백업도 주전과 거의 같은 값(기준치
# ±20%)을 받아버린다 — 그 결과 팀 전체 득점이 "주전 한 명이 몰아치는"
# 게 아니라 로스터의 같은 포지션 선수들에게 고르게 흩뿌려지는 모양이
# 된다. _apply_ballon_team_trophy_decay와 완전히 같은 패턴으로 고친다
# — (team_id, position) 그룹 안에서 OVR 내림차순 등수를 매기고, 등수별
# 감쇠 배율을 곱한다. 1등(그 포지션의 사실상 주전)은 오히려 소폭
# 가산(1.15배 — 실제로 에이스가 평균보다 더 넣는 효과)하고, 2등부터는
# 급격히 낮춘다.
_SQUAD_DEPTH_DECAY = [1.15, 0.45, 0.18, 0.07]


def _apply_squad_depth_decay(rows, key_fn):
    """rows: {"goals":..,"assists":..,"ovr":..} 등을 담은 dict의 리스트
    (in-place로 goals/assists/clean_sheets/saves/goals_conceded를 덮어씀
    — 뒤 세 개는 키가 있는 행에만 적용, 없으면 기존과 100% 동일).
    key_fn(row) -> (team_id, position) 같은 그룹 키. 그룹 크기가 1이면
    (그 팀에 그 포지션이 한 명뿐) 건드리지 않는다 — 백업이 없으면 애초에
    나눠 가질 대상이 없으므로 원래 추정치가 곧 그 선수의 실질적인 득점
    기대치와 같다.

    정렬 기준 우선순위: rows에 "role"(주전/로테이션/대기/전력외/유망주)이
    있으면 그걸 1순위로 쓰고(아래 2026-09 버그수정 참고), 없고 "apps"가
    있으면 출전 여부를 1순위로, 둘 다 없으면 OVR만 쓴다(기존과 동일).

    [2026-09 버그수정, 신민용 리포트: "월드컵 골든부츠가 4골밖에 안 된다"]
    등수를 OVR만으로 매기면 "그 대회에 한 경기도 안 나온 선수"가 OVR이
    높다는 이유로 1등(1.15배) 자리를 차지하고, 실제로 뛴 주전이 2등
    (0.45배)으로 밀려 반토막 난다. 그 1등의 추정치는 어차피 출전 0 →
    기대 골 0이므로 배율을 곱해봐야 0 — 결과적으로 그 포지션의 '에이스
    가산'이 통째로 증발한다. 2002 월드컵 세이브 실측에서 (국가, 포지션)
    그룹 220개 중 62개(28%)가 이 상태였다. rows에 "apps"가 있으면
    출전 여부를 1순위 정렬키로 써서 실제로 뛴 선수가 항상 앞에 오게
    한다(클럽 경로는 로스터 전원이 같은 경기수를 받으므로 "apps"를 안
    넘기고, 그 경우 기존과 100% 동일하게 OVR 순만 쓴다).

    [2026-09 확장, 신민용 리포트: "역할은 전력외인데 105선방/38경기가
    찍혀 있다 — 다른 포지션은 안 그러잖아"] 정확한 지적 — goals/assists는
    이미 이 감쇠를 받아서 후보 선수가 에이스와 비슷한 득점을 찍는 일이
    없는데, GK의 saves/goals_conceded/clean_sheets는 이 감쇠 대상에서
    빠져 있어 4번째 GK도 주전과 거의 같은 '풀시즌' 선방/실점을 그대로
    가졌다. goals/assists와 완전히 같은 그룹·같은 등수·같은 배율
    (_SQUAD_DEPTH_DECAY)로 세 필드도 같이 깎는다 — saves와 goals_conceded를
    "같은 배율"로 같이 줄이므로 선방률(saves/(saves+goals_conceded)) 자체는
    거의 그대로 유지되고(백업이라고 실력 자체가 나빠 보이면 안 됨), 총
    출전량(볼륨)만 뎁스 순위에 맞게 줄어든다."""
    groups: dict = {}
    for r in rows:
        groups.setdefault(key_fn(r), []).append(r)
    # [2026-09 성능 2차] 정렬 키 람다는 그룹 원소마다 한 번씩 불린다(연도전환
    # 한 번에 59만 회). 호출부는 "apps를 전부 넣거나 전부 안 넣거나" 둘 중
    # 하나이므로 한 번만 판별해서 전용 키를 쓴다 — 클럽 경로는 apps 조회
    # 자체가 사라진다. 정렬 결과는 기존과 완전히 동일하다(같은 순서 규칙 +
    # list.sort가 안정 정렬이라 동순위 원본 순서도 그대로).
    if rows and rows[0].get("role"):
        # [2026-09 버그수정, 신민용 리포트: "OVR이 같은 주전과 대기 중
        # 대기가 골을 더 넣었다"] 클럽 경로는 "apps"가 없어서(로스터
        # 전원이 같은 경기수를 받는 단순 모델이라 apps 자체가 의미 없음)
        # 항상 OVR만으로 순위를 매겼는데, OVR이 같거나 비슷한 선수끼리는
        # 이 정렬이 사실상 동률/리스트 순서에 가까워진다 — "주전"이라는
        # 라벨과 무관하게 1등(×1.15)/2등(×0.45)이 갈릴 수 있었다. role이
        # 있으면(호출부가 hist.ai_player_position_history에서 이미
        # 계산해둔 그 해 실제 역할을 같이 넘겨주면) 그걸 1순위로 써서
        # "주전이 항상 에이스 배율을 받는다"를 보장하고, 같은 역할
        # 안에서만 OVR로 세부 순위를 매긴다. role을 안 넘기는 기존
        # 호출부(월드컵 등)는 100% 그대로 동작한다.
        _role_rank = {"주전": 0, "로테이션": 1, "대기": 2, "전력외": 3, "유망주": 4}
        _sk = lambda x: (_role_rank.get(x.get("role"), 2), -(x["ovr"] or 0))
    elif rows and "apps" in rows[0]:
        _sk = lambda x: (0 if (x["apps"] or 0) > 0 else 1, -(x["ovr"] or 0))
    else:
        _sk = lambda x: -(x["ovr"] or 0)
    _decay = _SQUAD_DEPTH_DECAY
    _last = len(_decay) - 1
    for members in groups.values():
        if len(members) < 2:
            continue
        members.sort(key=_sk)
        i = 0
        for r in members:
            decay = _decay[i if i < _last else _last]
            i += 1
            # 0은 어떤 배율을 곱해도 0이라 round/max를 돌 필요가 없다.
            g = r["goals"]
            if g:
                r["goals"] = max(0, round(g * decay))
            a = r["assists"]
            if a:
                r["assists"] = max(0, round(a * decay))
            cs = r.get("clean_sheets")
            if cs:
                r["clean_sheets"] = max(0, round(cs * decay))
            sv = r.get("saves")
            if sv:
                r["saves"] = max(0, round(sv * decay))
            gc = r.get("goals_conceded")
            if gc:
                r["goals_conceded"] = max(0, round(gc * decay))
    return rows


# ═══════════════════════════════════════════════════════════════════
# [2026-09 신설, 신민용 확정: "여러 명이 3~4골씩 나눠 갖는 게 아니라
# 한 명이 몰아넣어야 한다 — 다만 팀 상황에 따라 여러 명이 4골씩 갖는
# 대회도 있어야 하고, 어떤 팀은 결국 6골 이상을 넣어 골든부츠를 받아야
# 한다"]
#
# 문제: _apply_squad_depth_decay는 '같은 포지션 안에서만' 주전에게
# 몰아준다. 포지션이 다르면(ST vs LW vs CAM vs CM) 서로 감쇠를 안 걸어서
# 팀 득점이 포지션별로 고르게 흩어진다. 2002 월드컵 세이브 실측 —
# 크로아티아 11골이 [4,2,2,1,1,1], 이탈리아 9골이 [4,1,1,1,1,1],
# 대회 전체 골든부츠가 4골. 실제 월드컵 득점왕은 5~8골이고(역대 평균
# 약 7.1골, 2006~2022 평균 약 6.4골), 대개 그 팀 득점의 절반쯤을 혼자
# 넣는다(케인 6/12, 하메스 6/12, 퐁텐 13/23).
#
# 해결: 팀 골 예산 배분(_apply_team_goal_budget)에 넘기기 '직전'에
# 가중치를 거듭제곱으로 날카롭게 만든다. 순위를 바꾸지 않고 상위 쪽
# 비중만 키우는 변환이라 "누가 에이스인가"는 기존 로직(포지션 기준치 ×
# 팀 강도 × 뎁스 감쇠)이 그대로 정하고, 여기서는 그 에이스가 몇 %를
# 가져가느냐만 조정된다.
#
# 신민용이 명시적으로 금지한 것 — "if 월드컵: top_scorer = max(6, ...)"
# 같은 하한 강제는 넣지 않는다. 저득점 대회에서 억지로 6골짜리가 나오는
# 문제가 생기기 때문이다. 여기 있는 건 어디까지나 '분포를 기울이는' 것
# 뿐이라, 팀이 3골밖에 못 넣었으면 에이스도 2골에서 끝난다.
#
# 세 가지 조절 축:
#  (1) 대회 길이 — 짧은 대회일수록 강하게 집중시킨다(_ACE_REF_MATCHES
#      기준 선형). 7경기 월드컵은 한 명이 몰아넣는 게 정상이지만 38경기
#      리그는 로테이션·부상·상대 분석 때문에 훨씬 고르게 퍼진다.
#      계수가 0 이하가 되는 대회(38경기 이상)는 통째로 건너뛴다 —
#      난수도 소비하지 않으므로 리그 경로는 비트 단위로 기존과 동일하다.
#  (2) 대회별 랜덤 — 감마를 팀·대회마다 새로 뽑는다. 낮게 뽑히면
#      [3,3,2,1] 같은 균등 분배, 높게 뽑히면 [7,2,1,1] 같은 독식.
#      "매번 반드시 6골"이 아니라 "6골 이상이 나올 확률이 높다"가 된다.
#  (3) 선수별 폼 — 대회 한 번의 컨디션. 이게 있어야 골든부츠가 항상
#      최고 OVR 스트라이커에게만 가지 않는다(실제로도 스네이더르·
#      하메스처럼 공격형 미드필더가 받는 대회가 있다).
#
# 도움은 골의 절반 강도로만 집중시킨다(_ACE_ASSIST_MIX) — 도움은
# 원래 골보다 여러 명에게 퍼지는 기록이라 같은 세기로 몰면 "도움 8개
# 짜리 한 명 + 나머지 0"이라는 비현실적인 모양이 된다.
#
# 실측 튜닝(2002 월드컵 실제 스쿼드·실제 팀 득점 고정, 400회 반복,
# game_engine 함수 그대로 사용):
#   수정 전  골든부츠 평균 5.05골(범위 4~6), 팀 톱1 비중 45.5%, 득점자 4.31명
#   수정 후  골든부츠 평균 6.50골(범위 5~10), 팀 톱1 비중 51.1%, 득점자 3.92명
#            4~5골 14% / 6골 40% / 7~8골 42% / 9~10골 4%
# 실제 월드컵 득점왕의 "팀 득점 대비 비중"이 대체로 50% 안팎이다
# (케인 6/12, 하메스 6/12, 퐁텐 13/23) — 그 수치에 맞춘 것이다.
#
# 이 실측은 팀 최다 득점이 11골로 고정된 한 대회만 쓴 것이라 양 끝
# 꼬리가 실제보다 좁게 나온다. 팀 실득점을 스케일해서 확인한 감도:
#   팀 득점 ×0.6 → 골든부츠 평균 3.96골 (4~5골이 98%)
#   팀 득점 ×1.0 → 6.37골
#   팀 득점 ×1.3 → 8.11골 (9~10골 30%, 11골+ 4%)
#   팀 득점 ×1.6 → 10.06골 (11골+ 34%)
# 즉 대회마다 득점 수준이 다르면 신민용이 제시한 목표 분포("2~3회
# 4~5골, 3~4회 6골, 2~3회 7~8골, 1회 9~10골, 극히 드물게 11~13골")가
# 강제 조건 없이 저절로 나온다. 저득점 대회에서 억지로 6골을 만들지
# 않는다는 점이 중요하다.
# ═══════════════════════════════════════════════════════════════════
_ACE_REF_MATCHES = 38.0     # 이 경기수 이상이면 집중 없음(리그 기준 시즌)
_ACE_GAMMA_LO    = 0.00     # 감마 추가분 하한(0 = 그 대회는 집중 없이 균등 분배)
_ACE_GAMMA_SPAN  = 0.50     # 감마 추가분 폭(상한 = LO + SPAN)
_ACE_FORM_K      = 1.05     # 선수별 폼 배율 = exp(±K) → 약 0.35~2.86배
_ACE_ASSIST_MIX  = 0.5      # 도움에 적용할 집중 강도(골 대비 비율)

# [2026-09 신설, "에이스 지분 상한", 신민용 리포트: "북미 챔스 10경기
# 22골을 한 선수가 사실상 전부 가져갔다 — UCL 역대 한 시즌 최다도
# 호날두 17골(2013-14, 41골 중 41%)인데 비현실적"] 위 감마 집중은
# 월드컵(7경기, 이미 실측·승인된 분포 — "팀 톱1 비중 51.1%, 극히
# 드물게 9~10/11골") 기준으로 잡은 것인데, short=1-m/38 공식이 7경기
# (short 0.82)든 10~15경기짜리 대륙대항전(short 0.61~0.74)이든 거의
# 같은 세기로 걸려서, 극단적으로는 감마·개인폼이 둘 다 높게 뽑히면
# 팀 골 전부(100%)를 한 명이 가져가는 사례까지 나온다 — 이건 애초에
# 승인된 목표 분포(월드컵 51% 평균, 최대치도 9~10/11≈82~91%)를 훨씬
# 넘어서는 값이다. 월드컵/국내컵처럼 이미 실측·승인된 초단기 대회
# (_ACE_SHARE_CAP_SKIP_MATCHES 이하)는 그대로 두고, 그보다 긴(대략
# 9~20경기대) 대륙대항전·클럽월드컵에만 대회 길이에 따라 낮아지는
# 지분 상한을 추가로 건다 — 실제 정수 배분은 뒤따르는
# _apply_team_goal_budget이 하므로, 여기선 그 배분에 넘길 '상대
# 가중치'만 상한 이하로 눌러서(초과분은 나머지 인원에게 비례 재배분)
# 팀 실제 골 합계 불변식은 그대로 유지한다."""
_ACE_SHARE_CAP_SKIP_MATCHES = 8     # 이 경기수 이하는 상한 없음(월드컵/국내컵 기존 튜닝 유지)
_ACE_SHARE_CAP_HI = 0.62            # 상한 시작점(9경기 근방)
_ACE_SHARE_CAP_LO = 0.40            # _ACE_REF_MATCHES(38경기)에 가까워질 때 하한
# [2026-09 수정, 신민용 리포트: "극히 희귀하다는 건 나올 수 있다는건데
# 이 최댓값이면 안 뜨는 거 아님?"] — 정확한 지적. 위 상한을 매번
# 딱딱하게(hard cap) 걸면 18~20골("극히 희귀") 같은 상위 등급이 확률과
# 무관하게 영원히 못 뜬다. _tailed_season_mult(평범/좋음/폭발/역대급
# 4단계 확률)와 같은 발상으로, 이 대회 이 팀의 지분 상한 자체를
# 확률적으로 "이번엔 거의 안 건다"로 가끔 뒤집는다 — 상한은 여전히
# '보통' 케이스의 기본값이고, 극히 드물게 대기록이 뚫고 나올 문을
# 남겨둔다.
_ACE_SHARE_CAP_BREAKTHROUGH_PROB = 0.03   # 이 대회·이 팀에서 이번엔 상한을 아예 안 걸 확률

# [2026-09 신설] 도움 전용 지분 상한 — 골 상한(0.62~0.40)보다 훨씬
# 낮다. _ace_assist_share_cap() 문서 참고.
_ACE_ASSIST_SHARE_CAP_HI = 0.30
_ACE_ASSIST_SHARE_CAP_LO = 0.18


def _ace_share_cap(matches_played, hi=_ACE_SHARE_CAP_HI, lo=_ACE_SHARE_CAP_LO):
    """대회에서 실제로 뛴 최대 경기수 -> 에이스 1인이 가져갈 수 있는
    지분의 상한(0~1). _ACE_SHARE_CAP_SKIP_MATCHES 이하는 None(상한
    없음 — 기존 승인된 튜닝 그대로). 그 이상은 9경기 근방 hi에서
    _ACE_REF_MATCHES(38경기)에 가까워질수록 lo까지 선형 감소 —
    로테이션·상대 분석이 늘수록 실제로도 한 명 독식은 줄어든다는
    현실을 반영한다. hi/lo를 넘기면 골 대신 도움 등 다른 상한 곡선에도
    같은 모양을 재사용할 수 있다(_ace_assist_share_cap 참고)."""
    if matches_played <= _ACE_SHARE_CAP_SKIP_MATCHES:
        return None
    span = _ACE_REF_MATCHES - _ACE_SHARE_CAP_SKIP_MATCHES
    t = min(1.0, (matches_played - _ACE_SHARE_CAP_SKIP_MATCHES) / span)
    return hi - (hi - lo) * t


def _ace_assist_share_cap(matches_played):
    """[2026-09 신설, "도움왕/득점왕 비율" 신민용 요청: "리그 득점왕20/
    도움왕13, 챔스 득점왕11~12/도움왕7 — 도움왕은 국가별 표 대신 그
    리그 득점환경·경기수 기반으로"] 골 지분 상한(_ace_share_cap)과 같은
    모양(경기수 기반 선형감소)이지만 상한 자체는 훨씬 낮다 — 실측
    결과, 골 지분 상한을 도입한 뒤로 도움에는 아무 상한이 없어 챔스급
    (13경기)에서 득점왕/도움왕 비율이 0.70~0.78까지 나왔다(목표
    0.60~0.65). _ACE_ASSIST_MIX(0.5)로 감마 자체는 이미 절반 세기로
    줄여놨지만 이것만으로는 비율이 거의 안 줄어, 골과 마찬가지로
    지분 자체에 별도 상한을 걸어 9경기 근방 30%에서 38경기에 가까울수록
    18%까지 낮춘다 — 이러면 별도 국가별 표 없이도 "그 대회 득점왕
    수준에 연동된" 도움왕이 자연스럽게 나온다(합성 검증: 13경기·팀
    38골 기준 득점왕 12.3/도움왕 7.2, 비율 0.58 — 리그 쪽은 원래
    ace-concentration을 안 타므로 이 상한과 무관하게 기존 0.63 그대로)."""
    return _ace_share_cap(matches_played,
                           hi=_ACE_ASSIST_SHARE_CAP_HI, lo=_ACE_ASSIST_SHARE_CAP_LO)


def _apply_ace_concentration(rows, key_fn):
    """rows: {"goals","assists","matches"}를 가진 dict 리스트(in-place로
    goals/assists를 float 가중치로 덮어씀 — 정수 확정은 곧바로 뒤따르는
    _apply_team_goal_budget이 한다). key_fn(row) -> 팀 식별자.

    반드시 _apply_squad_depth_decay '뒤', _apply_team_goal_budget '앞'에
    호출해야 한다. 앞뒤가 바뀌면 (감쇠 전이면) 백업이 에이스보다 커질 수
    있고, (배분 후면) 이미 정수로 확정된 값을 다시 흔들어 팀 합계가
    깨진다.

    ※ 이 함수는 난수를 소비한다. 순수 성능 리팩터링이 아니라 의도된
      동작 변경이므로 verify_determinism의 TOTAL_HASH·rng_calls는
      당연히 달라진다 — 같은 시드에서 재현되기만 하면 된다. 그래서
      그룹 순회는 dict 삽입 순서가 아니라 sorted(키)로 고정한다.
    """
    groups: dict = {}
    for r in rows:
        groups.setdefault(key_fn(r), []).append(r)
    _exp = math.exp
    for k in sorted(groups):
        members = groups[k]
        m = 0
        for r in members:
            _mm = r.get("matches") or 0
            if _mm > m:
                m = _mm
        short = 1.0 - m / _ACE_REF_MATCHES
        if short <= 0.0:
            # 리그 길이 이상 — 집중시키지 않는다. 난수도 안 쓴다.
            continue
        gamma = 1.0 + (_ACE_GAMMA_LO + _ACE_GAMMA_SPAN * _rand()) * short
        a_gamma = 1.0 + (gamma - 1.0) * _ACE_ASSIST_MIX
        g_before = a_before = g_after = a_after = 0.0
        for r in members:
            g = r["goals"]
            if g > 0:
                g_before += g
                g = (g * _exp(_ACE_FORM_K * (2.0 * _rand() - 1.0))) ** gamma
                r["goals"] = g
                g_after += g
            a = r["assists"]
            if a > 0:
                a_before += a
                a = (a * _exp(_ACE_FORM_K * (2.0 * _rand() - 1.0))) ** a_gamma
                r["assists"] = a
                a_after += a
        # [중요] 도움 예산 비율 복구. 거듭제곱은 합계를 부풀리는데(예: 골
        # 합 30 → 90), 골과 도움에 서로 다른 감마를 쓰므로 부푸는 정도가
        # 달라진다. _apply_team_goal_budget의 도움 예산이 a_sum/g_sum
        # 비율로 정해지기 때문에 그대로 두면 도움이 증발한다 — 실측에서
        # 전세계 컵 도움 총합이 23,414 → 19,497로 17% 줄었다.
        #
        # 골 쪽은 정규화할 필요가 없다. 최대잔여법은 상대 비율만 보므로
        # 전체에 같은 수를 곱해도 배분 결과가 한 골도 안 바뀐다. 그래서
        # 도움에만 (원래 비율 / 지금 비율)을 한 번 곱해 끝낸다 — 전체를
        # 다시 훑는 패스가 하나 줄어든다(40만 행 실측 0.579s → 0.311s).
        if a_after > 0.0 and a_before > 0.0 and g_after > 0.0 and g_before > 0.0:
            _s = (a_before / g_before) * (g_after / a_after)
            for r in members:
                if r["assists"] > 0:
                    r["assists"] *= _s

        # [2026-09 신설, "에이스 지분 상한"] 위 _ace_share_cap() 문서 참고.
        # g_after(그룹 전체 골 가중치 합)는 이 시점까지 감마 변환 결과
        # 그대로다 — 초과분만 덜어 나머지 인원에게 비례 재배분한다
        # (2등 이하끼리의 상대 비율은 그대로 유지, 1등만 눌린다).
        if g_after > 0.0:
            _cap = _ace_share_cap(m)
            # [2026-09 수정] 매번 걸지 않고 _ACE_SHARE_CAP_BREAKTHROUGH_PROB
            # 확률로 이번 그룹은 상한을 건너뛴다 — 위 상수 문서 참고.
            if _cap is not None and _rand() < _ACE_SHARE_CAP_BREAKTHROUGH_PROB:
                _cap = None
            if _cap is not None:
                _scorers = [r for r in members if r["goals"] > 0]
                if len(_scorers) >= 2:
                    _top = max(_scorers, key=lambda r: r["goals"])
                    _rest_sum = g_after - _top["goals"]
                    if _rest_sum > 0.0:
                        _max_allowed = (_cap / (1.0 - _cap)) * _rest_sum
                        if _top["goals"] > _max_allowed:
                            _top["goals"] = _max_allowed

        # [2026-09 신설, "도움왕/득점왕 비율"] 골과 같은 방식 — 도움
        # 전용(훨씬 낮은) 상한을 같은 돌파 확률로 적용한다. _ace_assist_
        # share_cap() 문서 참고.
        if a_after > 0.0:
            _acap = _ace_assist_share_cap(m)
            if _acap is not None and _rand() < _ACE_SHARE_CAP_BREAKTHROUGH_PROB:
                _acap = None
            if _acap is not None:
                _assisters = [r for r in members if r["assists"] > 0]
                if len(_assisters) >= 2:
                    _atop = max(_assisters, key=lambda r: r["assists"])
                    _arest_sum = a_after - _atop["assists"]
                    if _arest_sum > 0.0:
                        _amax_allowed = (_acap / (1.0 - _acap)) * _arest_sum
                        if _atop["assists"] > _amax_allowed:
                            _atop["assists"] = _amax_allowed
    return rows


def _collect_league_candidates(c, league_id, exclude_my_team=None, full_season_matches=14,
                                team_goals_for=None, year=None, team_league_map=None):
    """리그 내 모든 팀의 AI 후보 선수들의 시즌 성적 → 후보 리스트.

    [최적화] 기존엔 팀마다 ai_players를 2번씩(전체 OVR 집계용 + 후보 목록용)
      조회해 20팀 리그면 40+ 쿼리(N+1)가 돌았다. teams JOIN으로 팀별 평균 OVR을
      1쿼리에, 후보 목록을 1쿼리에 모아 총 2쿼리로 줄였다. 결과·계산은 동일.

    [2026-09 재설계, 신민용 리포트: "세계기록실에 뜨는 그 선수 기록을 그대로
      갖다써서 비교하면 되는 거 아니야?"] year가 주어지면(자연스러운 시즌
      종료 경로) 여기서 다시 추정하지 않고, hist.ai_player_season_stats에
      이미 저장된 값을 그대로 읽는다 — game_engine._end_of_season이
      _process_awards를 부르기 '직전'에 ai_lifecycle._snapshot_season_
      ratings로 이번 시즌 AI 골/도움/평점을 먼저 archiving해두기 때문에,
      이 시점엔 그 저장이 이미 끝나 있다. 세계기록실 화면에 뜨는 숫자와
      수상 판정에 쓰는 숫자가 이제 완전히 같은 값(같은 계산·같은 랜덤
      드로우 결과)이라, 더 이상 팀 골 합계 스케일링을 여기서 다시 할
      필요도 없다(이미 저장 단계에서 다 반영됨).
      year가 없으면(시즌 중 은퇴 — finalize_season_for_retire — 처럼 그 해
      아카이브가 아직 없는 경로) 기존처럼 _estimate_ai_season으로 즉석
      추정하고, team_goals_for({team_id: 실제 시즌 골, 아직 리셋 전 값)가
      있으면 그 팀 후보 전원의 추정 골 합계 대비 실제 골 비율로 스케일링한다
      (_team_goal_scale_factors 공유 — 최선의 근사치일 뿐, 시즌이 아직 안
      끝난 시점이라 그 실제 골 자체도 최종치는 아니다). 도움은 실측
      대응치가 없어 스케일링하지 않는다(기존과 동일 원칙).

    [2026-09 버그수정 자체발견] 영플레이어상 판정(pool 안의 x.get("age",30))이
      쓸 age 필드가 이 함수의 반환값(cands)엔 원래 없었다 — 그래서 AI 후보는
      전부 기본값 30으로 취급돼 "23세 이하 젊은 풀"에 단 한 번도 안 들어갔고,
      결과적으로 영플레이어상은 사실상 AI 비교 없이 "내가 23세 이하기만
      하면 받는" 상이었다. ap.age를 SELECT에 추가해 실제 AI 나이가 반영되게
      고쳤다 — 이번 재설계(평점 기준 비교)가 실제로 작동하려면 반드시
      필요한 수정이라 같이 넣는다.

    [2026-09 버그수정, 신민용 리포트: "승격 시즌 리그 개인상(득점왕 등)이
      승격 이후 리그로 잘못 뜬다"] year가 주어지는 경로(시즌 종료, 아래
      참고)는 원래 t.league_id(teams의 "지금" 값)로 그 리그 후보를 걸렀다 —
      그런데 승강 처리(_process_promotion_relegation)는 클럽 시즌이 끝나는
      43주에 이미 실행돼 다음 시즌 리그로 반영되고, 개인상 계산은 훨씬 뒤인
      52주(_end_of_season)에 일어난다. 그 사이 승격/강등된 팀 소속 선수는
      "그 시즌 실제로 뛴 리그"가 아니라 "다음 시즌 리그"로 잘못 묶여
      득점왕/도움왕/MVP/베스트11/영플레이어/올해의 수비수/구단 올해의 선수가
      전부 엉뚱한 리그명으로 저장됐다. team_league_map({team_id: 그 시즌
      실제 리그id}, _team_league_id_map_for_year 참고)이 주어지면 그걸로
      "이 리그(league_id)에 그 시즌 실제로 있었던 팀" 목록을 구해 그 팀
      소속 후보만 모은다 — teams.league_id 조인 자체를 없애 승격/강등
      타이밍과 완전히 무관해진다. 그 시즌 경기 기록이 아예 없는 예외
      (신생 리그 등)만 기존처럼 teams.league_id 기준으로 폴백한다.
    """
    # 팀별 평균 OVR + 리그 평균을 단일 JOIN 집계로. (year 유무와 무관하게
    # 매번 계산 — league_avg 반환값은 호출부가 필요하면 쓰고, year 분기
    # 없이도 가벼운 쿼리라 분기 복잡도를 늘리지 않는 쪽을 택함.)
    team_rows = c.execute(
        """SELECT t.id AS tid, AVG(ap.ovr) AS avg_ovr, COUNT(ap.id) AS n,
                  SUM(ap.ovr) AS sum_ovr
           FROM teams t LEFT JOIN ai_players ap ON ap.team_id=t.id
           WHERE t.league_id=?
           GROUP BY t.id""", (league_id,)).fetchall()
    if not team_rows:
        return [], 50.0

    team_avg = {}
    tot_sum = 0
    tot_n = 0
    for r in team_rows:
        if r["n"]:
            team_avg[r["tid"]] = r["avg_ovr"]
            tot_sum += r["sum_ovr"] or 0
            tot_n   += r["n"]
    league_avg = (tot_sum / tot_n) if tot_n else 50.0

    # [2026-07 확장, 신민용 지적: "MVP가 무조건 공격수 유리한 공식을 전
    # 포지션에 그대로 쓴다"] 예전엔 ATTACK_POS(공격 6포지션)만 후보로
    # 모아서, 수비수·GK는 애초에 AI 경쟁 풀에 존재하지도 않았다 —
    # MVP 후보 비교 자체가 "내가 수비수/GK면 무조건 공격수 AI들이랑
    # 붙어서 진다"는 구조였다. 전 포지션을 다 모으고, 포지션별 가중치는
    # 아래 _position_award_score()가 따로 처리한다.
    ALL_AWARD_POS = GK_POS + DF_POS + MF_POS + FW_POS

    if year is not None:
        # [버그수정] t.league_id(현재값) 대신, 그 시즌 실제로 이 리그에
        # 있었던 팀 집합으로 후보를 거른다 — 위 docstring 참고.
        if team_league_map is None:
            team_league_map = _team_league_id_map_for_year(c, year)
        _team_ids = [tid for tid, lid in team_league_map.items() if lid == league_id]
        if not _team_ids:
            # 그 시즌 경기 기록이 아예 없는 예외(신생 리그 첫 해 등) — 기존처럼
            # 현재 소속 기준으로 폴백(승강 타이밍 이슈가 애초에 생길 수 없는 경우).
            _team_ids = [r["tid"] for r in c.execute(
                "SELECT id AS tid FROM teams WHERE league_id=?", (league_id,)).fetchall()]
        if not _team_ids:
            return [], league_avg
        _tid_ph = ",".join("?" for _ in _team_ids)
        # 아카이브에서 그대로 읽기 — _snapshot_season_ratings가 방금 저장한
        # 값(세계기록실 "기록 복사"에 보이는 것과 완전히 동일)을 그대로 쓴다.
        placeholders = ",".join("?" for _ in ALL_AWARD_POS)
        hist_rows = c.execute(
            f"""SELECT ap.id AS player_id, ap.team_id AS tid, ap.name, ap.position, ap.ovr,
                      ap.age AS age, h.goals AS goals, h.assists AS assists, h.rating AS rating,
                      h.clean_sheets AS cs, h.saves AS saves, h.goals_conceded AS goals_conceded,
                      h.matches AS matches, ph.role AS role
               FROM hist.ai_player_season_stats h
               JOIN ai_players ap ON ap.id = h.player_id
               LEFT JOIN hist.ai_player_position_history ph
                 ON ph.player_id = ap.id AND ph.year = h.year
               WHERE h.year=? AND ap.team_id IN ({_tid_ph}) AND ap.position IN ({placeholders})""",
            (year, *_team_ids, *ALL_AWARD_POS)).fetchall()
        # [2026-09 신설, "리그전 개인상" 세계 계산용] player_id를 추가했다 —
        # 예전엔 이 함수가 "내가 받았는가"만 판정하면 됐어서 AI 후보의
        # 실제 id가 필요 없었지만, 이제 season_individual_awards에 실제
        # AI 수상자를 저장해야 하므로 반드시 있어야 한다.
        cands = [{
            "player_id": r["player_id"], "name": r["name"], "position": r["position"],
            "ovr": r["ovr"], "age": r["age"] or 30,
            "goals": r["goals"], "assists": r["assists"], "rating": r["rating"],
            "is_mine": False, "cs": r["cs"] or 0,
            "saves": r["saves"] or 0, "goals_conceded": r["goals_conceded"] or 0,
            "matches": r["matches"] or full_season_matches, "team_id": r["tid"],
            "role": r["role"],
        } for r in hist_rows]
        return cands, league_avg

    # [2026-09 신설] 이 리그의 국가별 득점 환경 배율 — 한 리그는 항상
    # 한 나라 소속이므로 리그 하나당 한 번만 조회하면 된다.
    _country_row = c.execute(
        """SELECT cn.name AS country FROM leagues l
           JOIN countries cn ON l.country_id = cn.id WHERE l.id=?""",
        (league_id,)).fetchone()
    goal_env_mult = get_goal_env_mult(_country_row["country"] if _country_row else None)

    placeholders = ",".join("?" for _ in ALL_AWARD_POS)
    atk_rows = c.execute(
        """SELECT ap.id AS player_id, ap.team_id AS tid, ap.name, ap.position, ap.ovr,
                  ap.sub_role, ap.age AS age
           FROM ai_players ap JOIN teams t ON ap.team_id=t.id
           WHERE t.league_id=? AND ap.position IN ({})""".format(placeholders),
        (league_id, *ALL_AWARD_POS)).fetchall()

    cands = []
    for r in atk_rows:
        tavg = team_avg.get(r["tid"], league_avg)
        g, a, rt = _estimate_ai_season(r["ovr"], r["position"], tavg, league_avg, r["sub_role"],
                                        full_season_matches=full_season_matches,
                                        goal_env_mult=goal_env_mult)
        cs = _estimate_ai_clean_sheets(r["position"], r["ovr"], tavg, league_avg,
                                        full_season_matches) if r["position"] in GK_POS + DF_POS else 0
        sv, gc = _estimate_ai_gk_saves(r["ovr"], tavg, league_avg, full_season_matches) \
            if r["position"] in GK_POS else (0, 0)
        cands.append({
            "player_id": r["player_id"], "name": r["name"], "position": r["position"],
            "ovr": r["ovr"], "age": r["age"] or 30,
            "goals": g, "assists": a, "rating": rt, "is_mine": False, "cs": cs,
            "saves": sv, "goals_conceded": gc,
            "matches": full_season_matches, "team_id": r["tid"],
            # [2026-09] 이 분기(year 없음 = 시즌 중 은퇴, 그 해 아카이브가
            # 아직 없는 경로)는 역할 스냅샷도 아직 없다 — None으로 두면
            # _role_award_eligible이 전원 통과시켜 이 경로의 동작은 역할
            # 게이트 도입 전과 100% 동일하게 유지된다.
            "role": None,
        })

    # [2026-09 신설] 스쿼드 뎁스 감쇠 — team_goals_for 스케일링 전에 적용해야
    # "팀 추정 합계"가 이미 쏠린 모양이 되고, 그 다음 실제 골 합계로
    # 스케일링해도 쏠린 모양이 그대로 유지된다(자세한 이유는 _apply_squad_
    # depth_decay 문서 참고).
    _apply_squad_depth_decay(cands, key_fn=lambda x: (x["team_id"], x["position"]))
    # [2026-09 변경] 계수 곱셈 + 개별 반올림 → 최대잔여법 정수 배분.
    # ai_lifecycle._snapshot_season_ratings(세계기록실에 저장되는 값)와
    # 반드시 같은 함수를 써야 "화면에 보이는 골/도움"과 "득점왕·도움왕
    # 판정에 쓰이는 골/도움"이 안 어긋난다.
    _apply_team_goal_budget(cands, lambda x: x["team_id"], team_goals_for)

    return cands, league_avg


def _collect_all_league_candidates(c, year, fsm_by_league, team_league_map=None):
    """[2026-09 성능, N+1 제거] _collect_league_candidates(year=...)를 리그마다
    부르면 전세계 710개 리그 × 2쿼리 = 1,420회가 돈다. 개인수상산정
    프로파일에서 이 경로가 1.03초였다. 같은 결과를 쿼리 1회로 모아온다.

    [2026-09 버그수정, 신민용 리포트: "승격 시즌 리그 개인상이 승격 이후
    리그로 잘못 뜬다"] 아래 쿼리의 t.league_id(teams의 "지금" 값)로
    후보를 묶으면, 43주 승강처리 이후 52주에 도는 이 함수가 승격/강등된
    팀 소속 선수를 전부 "다음 시즌 리그"로 잘못 묶는다 — team_league_map
    ({team_id: 그 시즌 실제 리그id}, _team_league_id_map_for_year 참고)이
    있으면 그걸로 묶고, 그 팀이 맵에 없을 때만(그 시즌 경기기록이 아예
    없는 예외) t.league_id로 폴백한다.

    반환: {league_id: [후보 dict, ...]} — 원소의 키·값은 _collect_league_
    candidates의 year 분기가 만드는 것과 완전히 동일하다.

    [쿼리를 하나 통째로 없앤 근거] 원래 함수는 팀별 평균 OVR 집계 쿼리를
    먼저 돌려 league_avg를 만들어 함께 반환하는데, year 분기에서는 그
    team_avg를 쓰지 않고 league_avg도 유일한 호출부(_compute_league_
    individual_awards)가 `cands, _league_avg = ...`로 받아 그대로 버린다.
    즉 리그마다 teams×ai_players를 조인하던 집계가 이 경로에서는 처음부터
    아무 데도 쓰이지 않았다 — 그래서 배치판에는 넣지 않는다.

    [행 순서] 원본도 ORDER BY가 없어 리그 안 순서는 SQLite 실행계획에
    달려 있었고, 이 함수의 순서도 그와 다를 수 있다. 그래도 결과가 같은
    이유는 이 풀을 쓰는 모든 선정이 player_id를 마지막 타이브레이커로
    가진 전순서이기 때문이다(_pick_comp_extra_winners의 max/sorted,
    득점왕·MVP·구단 올해의 선수의 max 전부). 실제로 결과 해시가 바뀌지
    않는 것으로 검증한다.

    [2026-09 성능 실측 메모] 이 경로에서 진짜 비싼 것은 쿼리 횟수가
    아니라 24만 행을 파이썬 dict으로 옮기는 비용이었다(쿼리를 1,420회
    →1회로 줄여도 0.06초밖에 안 줄었다). 그래서 두 가지를 같이 한다.
      · sqlite3.Row를 문자열 키로 읽으면 컬럼 이름 목록을 매번 선형
        탐색한다 — 14컬럼×24만 행이면 그 조회만 340만 회다. 위치
        인덱스로 읽으면 같은 값을 O(1)에 가져온다(실측 0.44s → 0.23s).
      · name/ovr은 이 경로의 어떤 선정에도 안 쓰인다(_award_entry_from_
        pool·_pick_comp_extra_winners·득점왕/MVP/구단 올해의 선수가
        읽는 키를 전수 확인함) — SELECT에서 빼면 24만 행분의 TEXT
        전송이 통째로 사라진다. 원본 _collect_league_candidates는
        다른 호출부(_process_awards 등)를 위해 그대로 둔다.
    """
    if team_league_map is None:
        team_league_map = _team_league_id_map_for_year(c, year)
    ALL_AWARD_POS = GK_POS + DF_POS + MF_POS + FW_POS
    placeholders = ",".join("?" for _ in ALL_AWARD_POS)
    # [2026-09 성능 검토 메모 — 일부러 안 고침] 이 쿼리는 PK가 (player_id,
    # year)인 hist를 "WHERE h.year=?"로 읽어 플래너가 SCAN h(전 시즌 스캔)
    # 를 고른다. _get_ballon_candidates에서 했던 것처럼 ai_players를
    # CROSS JOIN으로 바깥에 고정하면 스캔이 사라지지만, 여기는 결과가
    # 24만 행(전세계 전원)이라 PK 프로브 20만 회 비용이 순차 스캔보다
    # 오히려 비쌌다 — 실측(20만 선수×20시즌): SCAN 646ms vs 프로브
    # 709ms로 역전. 결과가 4천여 행뿐인 _get_ballon_candidates와 정반대다.
    # 시즌이 더 쌓이면(대략 25~30시즌 부근) 역전될 수 있으니, 그때 다시
    # 재보고 바꾸는 게 맞다(바꾸는 방법은 _get_ballon_candidates 주석 참고).
    rows = c.execute(
        # [2026-09 확장, 신민용 확정: "역할이 곧 얼마나 뛰었는지의 요약"]
        # ph.role(그 시즌 주전/로테이션/대기/전력외/유망주)을 같이 끌어온다 —
        # 평점 기반 상(베스트11/영플레이어/올해의 수비수/MVP)의 후보 자격
        # 게이트(_role_award_eligible)에 쓴다. LEFT JOIN이라 역할 스냅샷이
        # 없는 과거 시즌도 행 수는 그대로 유지된다(role만 NULL → 자격 통과).
        # 컬럼은 맨 뒤에 붙여서 아래 위치 인덱스(r[0]~r[11])를 안 건드린다.
        """SELECT t.league_id, ap.id, ap.team_id, ap.position, ap.age,
                  h.goals, h.assists, h.rating, h.clean_sheets, h.saves,
                  h.goals_conceded, h.matches, ph.role
           FROM hist.ai_player_season_stats h
           JOIN ai_players ap ON ap.id = h.player_id
           JOIN teams t ON ap.team_id = t.id
           LEFT JOIN hist.ai_player_position_history ph
             ON ph.player_id = ap.id AND ph.year = h.year
           WHERE h.year=? AND ap.position IN ({})""".format(placeholders),
        (year, *ALL_AWARD_POS)).fetchall()
    out = {}
    for r in rows:
        _tid = r[2]
        lid = team_league_map.get(_tid, r[0])  # [버그수정] 그 시즌 실제 리그 우선, 없으면 t.league_id(현재값)로 폴백
        bucket = out.get(lid)
        if bucket is None:
            bucket = out[lid] = []
        bucket.append({
            "player_id": r[1], "team_id": r[2], "position": r[3], "age": r[4] or 30,
            "goals": r[5], "assists": r[6], "rating": r[7], "cs": r[8] or 0,
            "saves": r[9] or 0, "goals_conceded": r[10] or 0,
            "matches": r[11] or fsm_by_league.get(lid, 14), "is_mine": False,
            "role": r[12],
        })
    return out


def _zamora_tally(c, p, year, league_id, lname, live_matches, live_ga):
    """사모라상 산정용: '같은 시즌·같은 리그'에서 뛴 출전수·실점을 합산한다.

    [규칙] 시즌 중 이적해도, 이적 전후 리그가 같으면(예: 토트넘→첼시 모두
      프리미어리그) 두 팀의 리그 출전·실점을 한 시즌으로 합쳐서 사모라상을
      심사한다. 다른 리그로 옮기면(예: 토트넘→레알) 합치지 않는다.

      합산 소스는 career_entries(팀별로 matches·goals_against·league_name·
      start_year 저장). 현재 팀의 라이브 값(live_matches/live_ga)을 베이스로,
      같은 해(start_year==year)·같은 리그명(lname)인 '다른 팀(닫힌)' 항목을 더한다.

      ※ GA 폴백: 구버전 데이터는 career_entries.goals_against 가 0으로 누락돼
        있을 수 있다. matches>0 인데 GA==0 인 GK 항목은 match_results 에서
        그 팀이 그 시즌 리그에서 먹은 골을 재계산해 보정한다(출전수로 캡).

    반환: (총출전경기, 총실점)
    """
    total_m  = int(live_matches or 0)
    total_ga = int(live_ga or 0)
    cur_tid  = p.get("current_team_id", 0)
    try:
        rows = c.execute(
            """SELECT team_id, matches, goals_against
               FROM career_entries
               WHERE start_year=? AND league_name=? AND team_id<>? AND matches>0""",
            (year, lname, cur_tid)).fetchall()
    except Exception:
        rows = []
    for r in rows:
        m  = int(r["matches"] or 0)
        ga = int(r["goals_against"] or 0)
        # GA 누락 보정: match_results 에서 해당 팀이 그 리그·시즌에 먹은 골 합
        if ga == 0 and m > 0:
            try:
                q = c.execute(
                    """SELECT COALESCE(SUM(CASE
                            WHEN home_team_id=? THEN away_score
                            WHEN away_team_id=? THEN home_score END),0) AS ga,
                              COUNT(*) AS gp
                       FROM match_results
                       WHERE league_id=? AND home_score>=0
                         AND (home_team_id=? OR away_team_id=?)""",
                    (r["team_id"], r["team_id"], league_id,
                     r["team_id"], r["team_id"])).fetchone()
                team_ga = int(q["ga"] or 0) if q else 0
                team_gp = int(q["gp"] or 0) if q else 0
                # 팀 전체 실점을 선수 출전 경기 비율로 귀속(안 뛴 경기 실점 제외).
                if team_gp > 0:
                    ga = round(team_ga * min(m, team_gp) / team_gp)
            except Exception:
                ga = 0
        total_m  += m
        total_ga += ga
    return total_m, total_ga


def _league_full_season_matches(p, team_id=None) -> int:
    """[2026-07 추가] 이 선수가 뛰는 리그의 실제 '풀시즌 팀당 경기 수'를
    구한다(팀 수 + legs_for_team_count 다전제 반영, 8~30팀 리그마다
    14~58경기로 제각각). 개인 수상 최소 출전 기준(아래 '최소 10경기'
    게이트, 사모라상 등)이 전부 리그 규모와 무관하게 고정값이었던 걸
    이 헬퍼로 통일해서 스케일한다 — _process_awards 내부에서도 득점왕/
    도움왕/발롱도르 기준 계산에 동일한 로직을 쓴다(중복 계산이지만
    가벼운 COUNT 쿼리 하나라 성능에 영향 없음).
    [2026-08] team_id를 넘기면 그 팀 기준으로 계산한다(기본값은 현재
    팀) — 시즌 중 이적한 선수의 시상 게이트는 '주 소속팀' 리그 규모를
    봐야 하므로 이 오버라이드가 필요하다."""
    tid = team_id if team_id is not None else p.get("current_team_id", 0)
    if not tid:
        return 38  # 무소속 등 예외 상황의 안전 폴백(20팀 2전제 기준값)
    conn = get_conn()
    row = conn.execute(
        """SELECT COUNT(*) AS n FROM teams
           WHERE league_id = (SELECT league_id FROM teams WHERE id=?)""", (tid,)).fetchone()
    conn.close()
    n_teams = row["n"] if row and row["n"] else 20
    legs = legs_for_team_count(n_teams)
    return max(1, (n_teams - 1) * legs)


def team_matches_played_in_window(team_id: int, league_name: str,
                                   start_year, start_week, end_year, end_week):
    """[버그수정 2026-07, 신민용 리포트: "전체 이력이 33/3처럼 말이 안 되는
    분모로 나온다 / 팀 이력에서 분모(출전 X/Y의 Y)가 통째로 빠진다"]

    예전 버전은 team_name으로 '지금 이 순간' teams 테이블에서 그 팀을
    다시 찾았는데, 그 팀이 그 스탠트 이후 승격/강등으로 다른 리그(다른
    league_id)로 옮겨갔으면 "league_id=(그 스탠트 당시 리그) AND
    name=팀명" 조건에 걸리는 행이 하나도 없어서 조용히 실패했다(None
    반환 → 분모가 통째로 사라지거나, 다른 대회 출전만 분모에 남아
    "33/3"처럼 분자보다 작은 분모가 나옴). team_id는 승격/강등과 무관하게
    영구히 같은 값이고 career_entries에 이미 저장돼 있으므로, 팀을 다시
    찾을 필요 없이 이 함수는 그 team_id를 그대로 받아서 쓴다 — league_name은
    '그 스탠트 당시 어느 리그(=몇 부)에서 뛰었는지' 필터링 용도로만 쓴다.

    이 함수는 대신 "내가 그 팀 소속이었던 기간(start~end) 동안 그 팀이
    실제로 치른 리그 경기 수"를 센다 — 내가 직접 뛰었는지와 무관하게
    (벤치/부상/출전정지로 못 뛴 경기도) 그 기간에 열렸으면 전부 포함한다.
    분자(matches, 내가 실제로 뛴 경기)와 같은 기준(그 팀 소속 기간)으로
    분모를 맞춰야 "출전 X/Y"가 왜곡 없이 그 스탠트 안에서의 실제 출전율을
    보여준다.

    end_year가 0/미정이면(아직 그 팀 소속 = 현재 진행 중인 스탠트) 지금
    게임 시점까지로 계산한다."""
    if not team_id or not league_name or not start_year:
        return None
    conn = get_conn()
    lrow = conn.execute("SELECT id FROM leagues WHERE name=? LIMIT 1", (league_name,)).fetchone()
    if not lrow:
        conn.close()
        return None
    lid = lrow["id"]
    tid = team_id

    ey, ew = end_year, end_week
    if not ey:
        st = get_state()
        if st:
            ey, ew = st.get("current_year", start_year), st.get("current_week", 52)
        else:
            ey, ew = start_year, 52

    def _count(table):
        return conn.execute(
            f"""SELECT COUNT(*) AS n FROM {table}
                WHERE league_id=? AND (home_team_id=? OR away_team_id=?)
                  AND home_score>=0
                  AND (year > ? OR (year = ? AND week >= ?))
                  AND (year < ? OR (year = ? AND week <= ?))""",
            (lid, tid, tid, start_year, start_year, start_week or 1,
             ey, ey, ew or 52)).fetchone()["n"]

    try:
        n = _count("match_results") + _count("match_results_archive")
    except Exception:
        n = None
    conn.close()
    return n if n else None


def get_club_other_competitions_summary(team_id, start_year, end_year):
    """[2026-07 신설, 신민용 확정: "팀 이력에 리그 경기랑 클럽 경기가 섞여서
    헷갈린다 — 위(팀 이력 한 줄)는 리그 경기만, 아래는 리그 외 모든 경기
    (컵대회+챔피언스리그+클럽월드컵 합산)를 따로 보여주자"] career_entries
    한 줄(리그 전용 — season_goals 등은 _simulate_match에서만 누적되므로
    이미 리그 전용이다)에 이어서, 그 팀 소속 기간 동안 컵대회/챔피언스리그/
    클럽월드컵에서 뛴 경기를 전부 합산해 반환한다. team_id 기준으로 직접
    조회하므로(현재 소속팀 여부와 무관), 은퇴 후 오래된 스탠트를 조회해도
    정확하다 — get_my_cl_matches() 등 화면용 헬퍼는 "현재 소속팀"을
    기준으로 홈/원정을 판정해 과거 스탠트에서는 부정확할 수 있는 것과
    다르다.

    반환: {"matches":int,"goals":int,"assists":int,"avg_rating":float or None}
    (경기가 하나도 없으면 matches=0, avg_rating=None)"""
    if not team_id:
        return {"matches": 0, "goals": 0, "assists": 0, "avg_rating": None}
    ey = end_year if end_year else 9999
    conn = get_conn()
    total = {"matches": 0, "goals": 0, "assists": 0}
    rating_sum, rating_cnt = 0.0, 0
    for m_table, t_table in (("cup_matches", "cup_tournaments"),
                             ("cl_matches", "cl_tournaments"),
                             ("el_matches", "el_tournaments"),
                             ("ecl_matches", "ecl_tournaments"),
                             ("sc_matches", "sc_tournaments"),
                             ("cwc_matches", "cwc_tournaments")):
        rows = conn.execute(
            f"""SELECT m.my_goals, m.my_assists, m.my_rating FROM {m_table} m
                JOIN {t_table} t ON m.tournament_id = t.id
                WHERE (m.home_team_id=? OR m.away_team_id=?) AND m.my_played=1
                  AND t.year BETWEEN ? AND ?""",
            (team_id, team_id, start_year, ey)).fetchall()
        for r in rows:
            total["matches"] += 1
            total["goals"] += r["my_goals"] or 0
            total["assists"] += r["my_assists"] or 0
            if r["my_rating"]:
                rating_sum += r["my_rating"]
                rating_cnt += 1
    conn.close()
    total["avg_rating"] = round(rating_sum / rating_cnt, 2) if rating_cnt else None
    return total


def league_total_games_by_name(league_name: str):
    """[2026-07 추가] 리그 이름으로 그 리그의 '풀시즌 팀당 경기 수'를 구한다
    (커리어 이력처럼 예전에 뛰었던 리그 — 지금 내 팀 기준이 아닌 경우용).
    이제 리그마다 팀 수·다전제가 달라 풀시즌 경기 수가 14~58경기로 다
    다르므로, '출전 26경기'만 보면 그게 시즌을 거의 다 뛴 건지 절반만
    뛴 건지 알 수 없다 — 분모(그 리그 풀시즌 경기 수)를 같이 보여주기
    위한 조회 함수. 못 찾으면 None(호출부에서 분모 없이 표시)."""
    if not league_name:
        return None
    conn = get_conn()
    row = conn.execute("SELECT id FROM leagues WHERE name=? LIMIT 1", (league_name,)).fetchone()
    if not row:
        conn.close()
        return None
    n_teams = conn.execute(
        "SELECT COUNT(*) AS n FROM teams WHERE league_id=?", (row["id"],)).fetchone()["n"]
    conn.close()
    if n_teams < 2:
        return None
    legs = legs_for_team_count(n_teams)
    return max(1, (n_teams - 1) * legs)


def get_full_history_extras_for_period(team_id, nationality, start_year, end_year):
    """[2026-07 신설 → 재작성 → 재확장 → 2026-08 승강PO 추가, 신민용 요청:
    "테이블 컬럼에 추가해서 ㄱㄱ"] '전체 이력' 탭/표용 리그 외(컵+챔스+
    유로파+컨퍼런스+슈퍼컵+클럽월드컵+승강PO+국가대표) 합산.
    처음엔 컵대회/클럽월드컵에 슈팅·유효슈팅·기회창출·드리블·차단·패스%가
    저장 안 된다고 판단했었는데 다시 보니 챔스/국제전은 이미 저장하고
    있었고(cl_matches/intl_matches에 my_shots 등 컬럼 존재), _player_perf가
    계산까지 해준 detail을 cup_engine.py/club_world_cup_engine.py만 버리고
    있었다 — cup_matches/cwc_matches에도 같은 컬럼을 추가하고 그 두 엔진의
    UPDATE문도 detail을 저장하도록 고쳐서, 이제 4개 대회 전부 동일하게
    집계할 수 있다.
    반환 필드: matches_available/matches_played, goals/assists,
    rating_sum/rating_cnt(가중평균용), saves/goals_against/clean_sheets,
    shots/shots_on/key_passes/dribbles/blocks, pass_acc_sum/pass_acc_cnt
    (평균 낼 때 나누는 용도 — 0인 경기까지 나누면 왜곡되므로 값 있는
    경기 수로만 나눈다), red_cards(컵+챔스+클럽월드컵+국가대표 합산
    퇴장 횟수 — my_absence_reason이 'red_card' 또는 'second_yellow'(경고
    누적 퇴장)인 경기 수를 셈), yellow_cards(같은 범위 옐로카드 합산 —
    my_yellow_cards 컬럼을 그대로 합산)."""
    conn = get_conn(); c = conn.cursor()
    avail_m = played_m = goals = assists = 0
    rating_sum = rating_cnt = 0.0
    saves = goals_against = clean_sheets = 0
    shots = shots_on = key_passes = dribbles = blocks = 0
    pass_acc_sum = 0.0; pass_acc_cnt = 0
    # [2026-08 신설, 신민용 리포트: "전체 이력엔 그 해 컵대회/챔스/월드컵
    # 등 대회 레드카드가 안 잡힌다"] my_absence_reason='red_card'는
    # 퇴장이 발생한 바로 그 경기 행에 이미 저장돼 있다(cup_engine.py 등
    # _apply_red_card_dismissal 호출부에서 my_played=1과 함께 기록) —
    # my_player.total_red_cards_all(커리어 통산 합계)은 이미 정확했지만,
    # '전체 이력' 표(기간별 합산)는 이 필드를 아예 안 읽고 있었다.
    red_cards = 0
    yellow_cards = 0
    _RED_REASONS = ("red_card", "second_yellow")
    # [2026-07 신설, 신민용 리포트: "전체 이력에 승패 표시가 사라졌어"]
    # 팀 이력의 승무패(e.wins/draws/losses)는 '내가 뛴 경기'가 아니라
    # '그 시즌 그 팀의 전적'(match_results 전체)이다 — 여기서도 같은
    # 원칙으로, 컵/챔스/클럽WC는 내가 안 뛴 경기까지 포함해 그 팀의
    # 승무패를 세고, 국가대표도 마찬가지로 그 나라 대표팀 전적을 센다.
    team_w = team_d = team_l = 0

    for tbl, tour_tbl in (("cup_matches", "cup_tournaments"),
                          ("cl_matches", "cl_tournaments"),
                          ("el_matches", "el_tournaments"),
                          ("ecl_matches", "ecl_tournaments"),
                          ("sc_matches", "sc_tournaments"),
                          ("cwc_matches", "cwc_tournaments")):
        avail_row = c.execute(
            f"""SELECT COUNT(*) n FROM {tbl} m JOIN {tour_tbl} t ON m.tournament_id=t.id
                WHERE (m.home_team_id=? OR m.away_team_id=?) AND t.year BETWEEN ? AND ?""",
            (team_id, team_id, start_year, end_year)).fetchone()
        avail_m += avail_row["n"] or 0

        wdl_rows = c.execute(
            f"""SELECT m.home_team_id, m.home_score, m.away_score
                FROM {tbl} m JOIN {tour_tbl} t ON m.tournament_id=t.id
                WHERE m.home_score>=0 AND (m.home_team_id=? OR m.away_team_id=?)
                  AND t.year BETWEEN ? AND ?""",
            (team_id, team_id, start_year, end_year)).fetchall()
        for wr in wdl_rows:
            my_score = wr["home_score"] if wr["home_team_id"] == team_id else wr["away_score"]
            opp_score = wr["away_score"] if wr["home_team_id"] == team_id else wr["home_score"]
            if my_score > opp_score: team_w += 1
            elif my_score == opp_score: team_d += 1
            else: team_l += 1

        rows = c.execute(
            f"""SELECT m.home_team_id, m.home_score, m.away_score, m.my_goals,
                       m.my_assists, m.my_saves, m.my_rating, m.my_shots,
                       m.my_shots_on, m.my_key_passes, m.my_dribbles,
                       m.my_blocks, m.my_pass_acc, m.my_absence_reason, m.my_yellow_cards
                FROM {tbl} m JOIN {tour_tbl} t ON m.tournament_id=t.id
                WHERE m.my_played=1 AND (m.home_team_id=? OR m.away_team_id=?)
                  AND t.year BETWEEN ? AND ?""",
            (team_id, team_id, start_year, end_year)).fetchall()
        for r in rows:
            played_m += 1
            goals += r["my_goals"] or 0
            assists += r["my_assists"] or 0
            if r["my_rating"]:
                rating_sum += r["my_rating"]; rating_cnt += 1
            saves += r["my_saves"] or 0
            conceded = r["away_score"] if r["home_team_id"] == team_id else r["home_score"]
            conceded = max(0, conceded or 0)
            goals_against += conceded
            if conceded == 0:
                clean_sheets += 1
            shots += r["my_shots"] or 0
            shots_on += r["my_shots_on"] or 0
            key_passes += r["my_key_passes"] or 0
            dribbles += r["my_dribbles"] or 0
            blocks += r["my_blocks"] or 0
            if r["my_pass_acc"]:
                pass_acc_sum += r["my_pass_acc"]; pass_acc_cnt += 1
            if r["my_absence_reason"] in _RED_REASONS:
                red_cards += 1
            yellow_cards += r["my_yellow_cards"] or 0

    # [2026-08 신설, 신민용 요청: "승강PO도 팀 이력에는 아니더라도
    # 전체 이력에는 포함되어야지"] po_matches는 슛/드리블 등 세부 스탯
    # 컬럼이 원래 없는 얕은 테이블이라(intl_matches 수준) 위 6개 테이블과
    # 같은 SELECT를 그대로 못 쓴다 — 있는 컬럼만 따로 집계한다(슈팅류
    # 누적치는 그대로 0으로 둠, 다른 대회 값에 영향 없음). "팀 이력" 표
    # (career_entries 재직기간별)는 여전히 PO를 포함하지 않는다 — 그건
    # career_entries.red_cards처럼 "리그 전용" 스냅샷 성격이라 별개.
    avail_row = c.execute(
        """SELECT COUNT(*) n FROM po_matches m JOIN po_tournaments t ON m.tournament_id=t.id
            WHERE (m.home_team_id=? OR m.away_team_id=?) AND t.year BETWEEN ? AND ?""",
        (team_id, team_id, start_year, end_year)).fetchone()
    avail_m += avail_row["n"] or 0

    wdl_rows = c.execute(
        """SELECT m.home_team_id, m.home_score, m.away_score
            FROM po_matches m JOIN po_tournaments t ON m.tournament_id=t.id
            WHERE m.home_score>=0 AND (m.home_team_id=? OR m.away_team_id=?)
              AND t.year BETWEEN ? AND ?""",
        (team_id, team_id, start_year, end_year)).fetchall()
    for wr in wdl_rows:
        my_score = wr["home_score"] if wr["home_team_id"] == team_id else wr["away_score"]
        opp_score = wr["away_score"] if wr["home_team_id"] == team_id else wr["home_score"]
        if my_score > opp_score: team_w += 1
        elif my_score == opp_score: team_d += 1
        else: team_l += 1

    rows = c.execute(
        """SELECT m.home_team_id, m.home_score, m.away_score, m.my_goals,
                   m.my_assists, m.my_saves, m.my_rating, m.my_absence_reason, m.my_yellow_cards
            FROM po_matches m JOIN po_tournaments t ON m.tournament_id=t.id
            WHERE m.my_played=1 AND (m.home_team_id=? OR m.away_team_id=?)
              AND t.year BETWEEN ? AND ?""",
        (team_id, team_id, start_year, end_year)).fetchall()
    for r in rows:
        played_m += 1
        goals += r["my_goals"] or 0
        assists += r["my_assists"] or 0
        if r["my_rating"]:
            rating_sum += r["my_rating"]; rating_cnt += 1
        saves += r["my_saves"] or 0
        conceded = r["away_score"] if r["home_team_id"] == team_id else r["home_score"]
        conceded = max(0, conceded or 0)
        goals_against += conceded
        if conceded == 0:
            clean_sheets += 1
        if r["my_absence_reason"] in _RED_REASONS:
            red_cards += 1
        yellow_cards += r["my_yellow_cards"] or 0

    if nationality:
        avail_row = c.execute(
            """SELECT COUNT(*) n FROM intl_matches m JOIN intl_tournaments t ON m.tournament_id=t.id
               WHERE (m.home=? OR m.away=?) AND t.year BETWEEN ? AND ?""",
            (nationality, nationality, start_year, end_year)).fetchone()
        avail_m += avail_row["n"] or 0

        wdl_rows = c.execute(
            """SELECT m.home, m.home_score, m.away_score
               FROM intl_matches m JOIN intl_tournaments t ON m.tournament_id=t.id
               WHERE m.home_score>=0 AND (m.home=? OR m.away=?)
                 AND t.year BETWEEN ? AND ?""",
            (nationality, nationality, start_year, end_year)).fetchall()
        for wr in wdl_rows:
            my_score = wr["home_score"] if wr["home"] == nationality else wr["away_score"]
            opp_score = wr["away_score"] if wr["home"] == nationality else wr["home_score"]
            if my_score > opp_score: team_w += 1
            elif my_score == opp_score: team_d += 1
            else: team_l += 1

        rows = c.execute(
            """SELECT m.home, m.home_score, m.away_score, m.my_goals,
                      m.my_assists, m.my_saves, m.my_rating, m.my_shots,
                      m.my_shots_on, m.my_key_passes, m.my_dribbles,
                      m.my_blocks, m.my_pass_acc, m.my_absence_reason, m.my_yellow_cards
               FROM intl_matches m JOIN intl_tournaments t ON m.tournament_id=t.id
               WHERE m.my_played=1 AND (m.home=? OR m.away=?)
                 AND t.year BETWEEN ? AND ?""",
            (nationality, nationality, start_year, end_year)).fetchall()
        for r in rows:
            played_m += 1
            goals += r["my_goals"] or 0
            assists += r["my_assists"] or 0
            if r["my_rating"]:
                rating_sum += r["my_rating"]; rating_cnt += 1
            saves += r["my_saves"] or 0
            conceded = r["away_score"] if r["home"] == nationality else r["home_score"]
            conceded = max(0, conceded or 0)
            goals_against += conceded
            if conceded == 0:
                clean_sheets += 1
            shots += r["my_shots"] or 0
            shots_on += r["my_shots_on"] or 0
            key_passes += r["my_key_passes"] or 0
            dribbles += r["my_dribbles"] or 0
            blocks += r["my_blocks"] or 0
            if r["my_pass_acc"]:
                pass_acc_sum += r["my_pass_acc"]; pass_acc_cnt += 1
            if r["my_absence_reason"] in _RED_REASONS:
                red_cards += 1
            yellow_cards += r["my_yellow_cards"] or 0
    conn.close()
    return {
        "matches_available": avail_m, "matches_played": played_m,
        "goals": goals, "assists": assists,
        "rating_sum": rating_sum, "rating_cnt": rating_cnt,
        "saves": saves, "goals_against": goals_against, "clean_sheets": clean_sheets,
        "shots": shots, "shots_on": shots_on, "key_passes": key_passes,
        "dribbles": dribbles, "blocks": blocks,
        "pass_acc_sum": pass_acc_sum, "pass_acc_cnt": pass_acc_cnt,
        "wins": team_w, "draws": team_d, "losses": team_l,
        "red_cards": red_cards, "yellow_cards": yellow_cards,
    }


def get_club_and_total_extras_for_period(team_id, nationality, start_year, end_year):
    """[2026-07 신설, 신민용 요청: "팀 이력에 리그만 뜨니 헷갈린다 — 그
    기간의 클럽대회 전체(컵+챔스+클럽월드컵)랑 전체(국가대표까지 포함)를
    따로 보여주자"] career_entries 한 스틴트(기간+team_id) 동안, 리그를
    제외한 나머지 대회 실적을 두 단계로 합산한다:
      - "club": 그 팀 소속으로 뛴 컵대회+챔피언스리그+클럽월드컵 합계
        (국가대표 제외 — 팀 이력 위쪽 리그 줄과 같은 '클럽' 범주)
      - "total": club + 그 기간 동안의 국가대표(국제전, 예선 포함) 전부
    [2026-07 주의] '전체 이력' 표시용으로는 get_full_history_extras_for_period
    (위, 더 상세)를 대신 쓴다 — 이 함수는 구버전 호출부 호환용으로 남겨둠."""
    conn = get_conn(); c = conn.cursor()
    club_m = club_g = club_a = 0
    for tbl, tour_tbl in (("cup_matches", "cup_tournaments"),
                          ("cl_matches", "cl_tournaments"),
                          ("el_matches", "el_tournaments"),
                          ("ecl_matches", "ecl_tournaments"),
                          ("sc_matches", "sc_tournaments"),
                          ("cwc_matches", "cwc_tournaments")):
        row = c.execute(
            f"""SELECT COUNT(*) n, COALESCE(SUM(m.my_goals),0) g, COALESCE(SUM(m.my_assists),0) a
                FROM {tbl} m JOIN {tour_tbl} t ON m.tournament_id=t.id
                WHERE m.my_played=1 AND (m.home_team_id=? OR m.away_team_id=?)
                  AND t.year BETWEEN ? AND ?""",
            (team_id, team_id, start_year, end_year)).fetchone()
        club_m += row["n"] or 0
        club_g += row["g"] or 0
        club_a += row["a"] or 0

    intl_m = intl_g = intl_a = 0
    if nationality:
        irow = c.execute(
            """SELECT COUNT(*) n, COALESCE(SUM(m.my_goals),0) g, COALESCE(SUM(m.my_assists),0) a
               FROM intl_matches m JOIN intl_tournaments t ON m.tournament_id=t.id
               WHERE m.my_played=1 AND (m.home=? OR m.away=?)
                 AND t.year BETWEEN ? AND ?""",
            (nationality, nationality, start_year, end_year)).fetchone()
        intl_m, intl_g, intl_a = irow["n"] or 0, irow["g"] or 0, irow["a"] or 0
    conn.close()
    return {
        "club":  {"matches": club_m, "goals": club_g, "assists": club_a},
        "total": {"matches": club_m + intl_m, "goals": club_g + intl_g, "assists": club_a + intl_a},
    }


def league_total_teams_by_name(league_name: str):
    """[2026-07 신설, 신민용 요청] 커리어/은퇴창/AI요약의 '팀순위'를
    "12위" 대신 "12위/18팀"으로 보여주기 위한 그 리그 전체 팀 수 조회.
    league_total_games_by_name과 동일한 조회 패턴(리그명→league_id→팀 수)
    이지만, 다전제 환산 없이 팀 수 자체를 그대로 반환한다.
    못 찾으면 None(호출부에서 분모 없이 표시)."""
    if not league_name:
        return None
    conn = get_conn()
    row = conn.execute("SELECT id FROM leagues WHERE name=? LIMIT 1", (league_name,)).fetchone()
    if not row:
        conn.close()
        return None
    n_teams = conn.execute(
        "SELECT COUNT(*) AS n FROM teams WHERE league_id=?", (row["id"],)).fetchone()["n"]
    conn.close()
    return n_teams if n_teams > 0 else None


def _get_cl_cup_season_stats(year):
    """[2026-07 신설, 신민용 지적: "발롱도르는 챔스나 컵대회도 반영돼야
    하지 않나"] 그 해 챔피언스리그+국내컵에서 내가 실제로 뛴 경기의
    골/도움/평점 합계. 지금까지 개인 수상(_process_awards)은 리그 스탯
    (season_goals/season_assists/season_rating)만 봤는데, 이 셋은
    match_flow의 리그 경기 루프에서만 갱신되고 cup_engine/champions_engine은
    각자 cup_matches/cl_matches에 my_goals/my_assists/my_rating을 따로
    적재할 뿐 player의 season_* 누적치엔 전혀 반영하지 않는다 — 그래서
    챔스에서 8골을 넣어도 발롱도르 심사엔 0골로 보였다. 실제 발롱도르도
    UCL 활약이 사실상 핵심 변수이므로, 리그 스탯과 합산해서 쓸 수 있게
    별도 집계 함수로 뺀다.
    반환: {"goals","assists","rating_sum","rating_cnt","cl_won"}
    (rating_sum/rating_cnt는 평균이 아니라 합계·횟수 — 호출부에서 리그
    시즌 평균과 가중평균으로 합쳐 쓰기 위함)."""
    conn = get_conn()
    cl = conn.execute(
        """SELECT COALESCE(SUM(m.my_goals),0) g, COALESCE(SUM(m.my_assists),0) a,
                  COALESCE(SUM(m.my_rating),0) rs, COUNT(*) rc
           FROM cl_matches m JOIN cl_tournaments t ON m.tournament_id=t.id
           WHERE t.year=? AND m.my_played=1""", (year,)).fetchone()
    cup = conn.execute(
        """SELECT COALESCE(SUM(m.my_goals),0) g, COALESCE(SUM(m.my_assists),0) a,
                  COALESCE(SUM(m.my_rating),0) rs, COUNT(*) rc
           FROM cup_matches m JOIN cup_tournaments t ON m.tournament_id=t.id
           WHERE t.year=? AND m.my_played=1""", (year,)).fetchone()
    # [2026-08 신설, 10순위 슈퍼컵 시스템 구축 이후, 신민용 요청: "상 받는
    # 것도 슈퍼컵 용으로 추가해야 한다"] 챔스/컵/국가대표와 동일하게,
    # 슈퍼컵에서 낸 개인 기록(골/도움/평점)도 이 합산에 포함시킨다 —
    # 이전엔 슈퍼컵이 없어서 반영할 대상 자체가 없었다.
    sc = conn.execute(
        """SELECT COALESCE(SUM(m.my_goals),0) g, COALESCE(SUM(m.my_assists),0) a,
                  COALESCE(SUM(m.my_rating),0) rs, COUNT(*) rc
           FROM sc_matches m JOIN sc_tournaments t ON m.tournament_id=t.id
           WHERE t.year=? AND m.my_played=1""", (year,)).fetchone()
    cl_t = conn.execute(
        "SELECT my_result FROM cl_tournaments WHERE year=? AND my_in=1", (year,)).fetchone()
    sc_t = conn.execute(
        "SELECT my_result FROM sc_tournaments WHERE year=? AND my_in=1", (year,)).fetchone()
    # [2026-07 버그수정, 신민용 리포트: "월드컵 기간에는 월드컵 기준까지
    # 넣고 그래야지"] 함수 docstring/주변 주석은 "챔스+컵+국가대표 대회"를
    # 전부 반영한다고 되어 있었는데, 실제로는 국가대표 대회(월드컵/대륙컵)
    # 개인 기록(내가 그 대회에서 넣은 골/도움/평점)이 통째로 빠져 있었다.
    # trophy_bonus 쪽엔 국가대표 대회 "팀 성적"(우승/8강 등)은 반영되고
    # 있었지만, 그건 팀 성적일 뿐 "내가 개인적으로 얼마나 생산했는가"와는
    # 별개다 — 월드컵에서 8골을 넣어도 그 8골이 combined_ga에 안 잡히고
    # 있었다는 뜻. intl_matches를 추가로 합산한다.
    intl = conn.execute(
        """SELECT COALESCE(SUM(m.my_goals),0) g, COALESCE(SUM(m.my_assists),0) a,
                  COALESCE(SUM(m.my_rating),0) rs, COUNT(*) rc
           FROM intl_matches m JOIN intl_tournaments t ON m.tournament_id=t.id
           WHERE t.year=? AND m.my_played=1""", (year,)).fetchone()
    conn.close()
    cl_won = bool(cl_t and cl_t["my_result"] and "우승" in cl_t["my_result"])
    # [2026-08 신설] 슈퍼컵 우승 게이트 — cl_won과 같은 방식으로, FIFA
    # 올해의 선수/UEFA·AFC 올해의 선수 등 "우승 시 자동 통과" 조건에
    # cl_won과 나란히 OR로 추가한다(챔스보다는 약한 대회이므로 발롱도르
    # 트로피 점수 자체는 0.2배로 낮게 잡지만, "세계 무대에서 우승해봤다"는
    # 게이트 통과 조건으로는 챔스와 동등하게 인정 — 게이트는 이분법적
    # 자격 검증이라 가중치 개념이 없다).
    sc_won = bool(sc_t and sc_t["my_result"] and "우승" in sc_t["my_result"])
    return {
        "goals": cl["g"] + cup["g"] + intl["g"] + sc["g"],
        "assists": cl["a"] + cup["a"] + intl["a"] + sc["a"],
        "rating_sum": cl["rs"] + cup["rs"] + intl["rs"] + sc["rs"],
        "rating_cnt": cl["rc"] + cup["rc"] + intl["rc"] + sc["rc"],
        "cl_won": cl_won,
        "sc_won": sc_won,
    }


# ══════════════════════════════════════════════════════════════
# [2026-07 신설, 신민용 지적: "발롱도르는 리그만 보지 말고 챔스/컵/
# 국가대표 대회까지 다 반영해야 한다"] 대회별 중요도를 별점 가중치로
# 명시해 점수화한다. 신민용이 제시한 우선순위:
#   1) 개인 퍼포먼스(가장 중요, 항상 _combined_ga/평점이 주축)
#   2) 팀 성적·우승 — 대회별 무게는 챔스 ⭐⭐⭐⭐⭐ > 국대 메이저대회
#      ⭐⭐⭐⭐~⭐⭐⭐⭐⭐ > 리그 ⭐⭐⭐⭐☆ > 자국컵 ⭐⭐☆☆☆ > 슈퍼컵/
#      클럽월드컵 ⭐☆☆☆☆~⭐⭐☆☆☆
#   3) 페어플레이 (카드 시스템 자체가 없어 현재 미반영 — 아래 주석 참고)
#
# 다만 "챔스가 리그보다 별점이 높다"가 "챔스 준우승이 리그 우승보다
# 항상 세다"는 뜻은 아니다 — 신민용이 든 예시(라리가 우승+챔스 8강 vs
# 리그 밖+챔스 준우승)처럼 실제로는 "우승 자체"가 "준우승"보다 근소하게
# 더 세게 평가되는 경우가 많다. 그래서 트로피 점수 자체는 개인 성적
# (_combined_ga, 보통 20~45대)보다 작은 배점(합계 10점 안팎)으로 눌러
# 놓고 — 우선순위 1번(개인 퍼포먼스)이 항상 더 크게 작용하게 하면서,
# 트로피 점수는 개인 성적이 비슷한 경합 상황의 타이브레이커 역할을
# 하도록 설계했다.
#
# [구현 한계] 챔스/리그는 실제 결과(cl_tournaments/get_league_standings)를
# 그대로 쓰지만, AI 라이벌 선수들의 트로피 성적은 이 게임에 별도로
# 저장돼 있지 않다(AI는 스탯 추정치만 존재) — 그래서 "내 트로피 점수"와
# "AI 라이벌의 트로피 점수"를 1:1로 비교하는 건 불가능하고, 대신 내
# 개인 성적+트로피 합산 점수가 발롱도르급 최소 문턱(BALLON_SCORE_MIN)을
# 넘는지로 판정한다(기존에도 AI는 스탯만으로 추정됐으므로 같은 한계선상).
# [2026-08 갱신] 슈퍼컵은 super_cup_engine.py로 실제 구현됐다 — 아래
# _sc_trophy_points가 _cl_trophy_points의 0.2배 가중치로 반영한다(신민용
# 확정: "챔스가 발롱에 1의 영향을 주면 슈퍼컵은 0.2의 영향"). 클럽
# 월드컵은 여전히 이 심사 로직에 포함되지 않는다 — 발롱도르 가중치를
# 매기려면 별도 확정이 필요하다.
#
# [2026-09 확장, 신민용 확정: "핵심은 '유럽이라서 가산점'이 아니라
# '유럽 챔피언스리그가 실제로 더 높은 경쟁 수준의 대회이기 때문에
# 우승 가치가 더 커야 한다'는 것 — 대륙 자체에 점수를 주는 것과
# 완전히 다르다"] cl_tournaments 한 테이블에 5개 대륙(유럽/남미/북미/
# 아시아/아프리카) 챔피언스리그급 대회가 전부 같이 들어있는데,
# _cl_trophy_points는 지금까지 대륙 구분 없이 우승=10.0을 똑같이 줬다
# — 유럽 챔스 우승과 아시아 챔피언스리그 우승이 발롱도르 트로피
# 점수에서 완전히 같은 무게였다는 뜻(팔메이라스/크루스 아술/시미즈
# 같은 비유럽 클럽 선수들이 한 팀에서 여러 명 나란히 최상위권을
# 차지하던 원인 중 하나). "그 국적/대륙 선수라서" 깎거나 올리는 게
# 아니라 "그 대회 자체의 실제 경쟁 수준"을 반영하는 가중치이므로,
# 국적과 무관하게(레알 마드리드 소속이면 국적이 일본이어도 100%,
# 시미즈 소속이면 국적이 브라질이어도 45%) 오직 대회(대륙)로만 정해
# 진다 — 국가/대륙 보정(_CONTINENTAL_CUP_WEIGHT_RATIO, 국가대표 대회
# 전용)과는 완전히 분리된 별개의 표.
#   결과문자열     유럽(가중치1.00) 남미(0.15)  북미(0.10)  아시아(0.08)  아프리카(0.10)
#   우승  (10.0)        10.0          1.5          1.0          0.8           1.0
#   준우승(4.5)          4.5          0.68         0.45         0.36          0.45
#   4강   (2.5)          2.5          0.38         0.25         0.20          0.25
# [2026-09 재조정, 신민용 확정: "유럽 챔스를 너는 너무 무시해 — 유럽
# 챔스 준우승이랑 남미 챔스 우승 중에 유럽 챔스 준우승이 훨씬 평가가
# 높잖아, 4강만 가도 남미 우승보다 평가가 높지 않아?"] 처음 값(남미
# 0.70)은 위 트로피 가치 예시표(챔스 8~9, 리베르타도레스 5~6, 비율
# 0.65 근처)를 그대로 "우승 대 우승" 배율로만 옮긴 것이었는데, 그러면
# 남미 우승(10.0×0.70=7.0)이 유럽 준우승(4.5)은 물론 유럽 4강(2.5)
# 보다도 여전히 높게 나온다 — "유럽 챔스가 압도적으로 더 어려운
# 대회"라는 원래 취지와 실제 계산 결과가 어긋났다. 이번엔 "유럽 4강
# 정도면 이미 남미 우승보다 위"라는 구체적 기준을 만족하도록 역산했다
# — 0.15면 남미 우승(1.5)이 유럽 4강(2.5)보다 확실히 아래, 유럽
# 준우승(4.5)과는 격차가 더 크다. 나머지 대륙(북미/아시아/아프리카)은
# 실제 대회 수준 통설(리베르타도레스 > CAF/CONCACAF ≳ AFC)에 맞춰 남미
# 보다 더 낮게 잡았다 — 이 넷 다 유럽 8강(1.2)보다도 낮으므로, "유럽
# 8강만 가도 어느 대륙 우승보다 위"가 성립한다.
# [2026-09 6차 확장, 신민용 제공 순위 + GPT 제안 수치로 교체] 기존
# _CL_CONTINENT_WEIGHT(대륙 5단계, 챔스 전용) + _cl_trophy_points(우승/
# 준우승/4강/8강/16강/32강 절대점수, 대회 위상 무관)를 완전히 대체한다.
# "대회 자체의 위상"(_CLUB_COMP_WEIGHT)과 "그 대회에서 어디까지
# 갔는가"(_CLUB_COMP_STAGE_WEIGHT)를 분리해서 곱하는 구조로 바꿨다 —
# 유로파리그/컨퍼런스리그가 트로피 점수에서 아예 0점 취급되던 것(신민용
# 리포트로 발견)도 이 김에 해결된다. 기존 trophy_bonus 스케일(챔스
# 우승=10.0)을 그대로 유지하기 위해 마지막에 ×10.0을 곱한다
# (_club_comp_trophy_value 참고).
#
# [신민용 제시 순위: "유럽CL>유럽EL>유럽ECL>남미CL>남미EL>아시아CL>
# 북미CL>아프리카CL>아시아EL>북미EL>아프리카EL>아시아ECL>북미ECL>
# 아프리카ECL", GPT 제안 수치] 이 순서는 기존 대륙 가중치(유럽 압도적,
# 나머지 4개 대륙은 0.08~0.15로 다닥다닥)를 "대륙값×티어배율"로 단순
# 분해해서는 재현이 안 된다(예: 남미EL이 아시아/북미/아프리카CL보다
# 위) — 그래서 15개 (대륙,티어) 조합에 값을 직접 매겼다.
# [빈 자리] 남미 컨퍼런스리그는 신민용이 준 순위표에 없던 항목 —
# 유럽의 EL→ECL 감쇠비(0.52/0.72≈0.722)를 남미 EL(0.32)에 그대로
# 적용해 0.23으로 잠정 배치했다(아시아CL 0.26보다 낮고 북미CL 0.22보다
# 높은 자리 — 확인 필요).
_CLUB_COMP_WEIGHT = {
    # [2026-09 8차 재조정, 신민용 리포트: "유로파 위상이 너무 높은듯 —
    # 유로파 우승으로 발롱도르 순위 안에 드는 건 맞지만 생각보다 위상이
    # 높아진 것 같다"] 7차(품질 상한 _CLUB_COMP_QUALITY_CAP 도입)로
    # "유로파 우승이 옛 챔스 우승급까지 치솟는" 문제는 잡았지만, 대회
    # 자체의 위상값(comp_weight)은 그대로 0.72였다 — 유럽CL(1.00) 다음
    # 위상 정의 가중치 자체를 0.72→0.62로 한 단계 낮춘다. 유럽ECL(0.52)
    # 보다는 여전히 위, 남미CL(0.40)보다도 확실히 위라 "유럽CL>유럽EL>
    # 유럽ECL>남미CL>..." 순서(신민용 확정 순위)는 그대로 유지된다.
    ("유럽", "cl"): 1.00, ("유럽", "el"): 0.62, ("유럽", "ecl"): 0.52,
    ("남미", "cl"): 0.40, ("남미", "el"): 0.32, ("남미", "ecl"): 0.23,
    ("아시아", "cl"): 0.26, ("북미", "cl"): 0.22, ("아프리카", "cl"): 0.19,
    ("아시아", "el"): 0.15, ("북미", "el"): 0.13, ("아프리카", "el"): 0.11,
    ("아시아", "ecl"): 0.085, ("북미", "ecl"): 0.070, ("아프리카", "ecl"): 0.060,
}

# [2026-09 7차 확장, 신민용+GPT 협의: "0.72 자체가 문제가 아니라 참가도×
# 평점 배율(1.30)이 모든 대회에 똑같이 곱해지는 게 문제 — 유로파 우승
# 9.36점이 옛 챔스 우승(10.0)급까지 치솟는다"] 실측(셀타 비고, 리그
# 14위인데 유로파 우승+평점 7.23 → 발롱도르 2위)으로 확인된 문제 —
# comp_weight(대회 위상)는 그대로 두고, 참가도×평점 배율의 상한만 대회
# 티어별로 낮춘다. 위 유럽 3단계(1.30/1.15/1.05)와 남미 CL/EL(1.10/1.05),
# 아시아 CL(1.05)은 GPT가 명시한 값 — 나머지(북미/아프리카 CL, 하위
# 대륙의 EL/ECL)는 같은 감쇠 패턴으로 채워넣은 추정치("1.00~1.05 범위"
# 라고만 명시됐던 부분)라 확인이 더 필요할 수 있다.
_CLUB_COMP_QUALITY_CAP = {
    ("유럽", "cl"): 1.30, ("유럽", "el"): 1.15, ("유럽", "ecl"): 1.05,
    ("남미", "cl"): 1.10, ("남미", "el"): 1.05, ("남미", "ecl"): 1.03,
    ("아시아", "cl"): 1.05, ("북미", "cl"): 1.03, ("아프리카", "cl"): 1.02,
    ("아시아", "el"): 1.02, ("북미", "el"): 1.01, ("아프리카", "el"): 1.00,
    ("아시아", "ecl"): 1.00, ("북미", "ecl"): 1.00, ("아프리카", "ecl"): 1.00,
}

# [2026-09 7차 확장, GPT 제안: "실제로 엄청난 커리어를 가진 선수가 트로피가
# 더 쌓여도 평가가 거의 안 올라가면 안 되니, cap은 비정상적인 폭주
# 방지용으로만 아주 높게 둔다"] score_trophy(trophy_bonus+intl_bonus+
# award_bonus 합)에 거는 안전장치용 상한 — 정상적인 케이스는 거의 안
# 걸리고, 여러 대회 우승이 한 시즌에 몰리는 극단치만 막는다.
_TROPHY_SCORE_CAP = 30.0

# [GPT 제안 그대로] 대회 내 진출 단계 계수 — "대회 기본값을 100%로 놓은
# 최고 성과" 대비 비율. 결승 tal락(준우승)이 0.78인 건 "챔스 준우승 ≳
# 유로파 우승(0.72) > 챔스 4강(0.55)"이라는 경계선을 의도적으로 만든
# 것(GPT 제안 근거: 챔스 8강(0.38) vs 유로파 우승(0.72) — 유로파 우승이
# 압도적으로 높음, 챔스 4강(0.55) vs 유로파 우승(0.72) — 유로파 우승이
# 여전히 위).
_CLUB_COMP_STAGE_WEIGHT = {
    "우승": 1.00, "준우승": 0.78, "4강": 0.55, "8강": 0.38,
    "16강": 0.24, "16강진출전": 0.14, "조별탈락": 0.08,
}
# stage 컬럼 실측값(cl/el/ecl_matches 전부 동일): league/PO/R16/QF/SF/F/TP.
# F부터 역순으로 훑어 "이 팀이 나온 가장 늦은 단계"를 찾는다 — F가 아닌
# 한 그 단계에 나왔다는 것 자체가 "거기서 졌다"는 뜻(다음 단계 기록이
# 없으므로).
_CLUB_COMP_STAGE_ORDER = ["F", "SF", "QF", "R16", "PO", "league"]
_CLUB_COMP_STAGE_LABEL = {
    "SF": "4강", "QF": "8강", "R16": "16강", "PO": "16강진출전", "league": "조별탈락",
}
_CLUB_COMP_TABLES = {
    "cl": ("cl_entries", "cl_tournaments", "cl_matches"),
    "el": ("el_entries", "el_tournaments", "el_matches"),
    "ecl": ("ecl_entries", "ecl_tournaments", "ecl_matches"),
}


def _team_furthest_stage_result(matches_table, tournament_id, team_id):
    """team_id가 그 대회(matches_table 기준)에서 도달한 가장 깊은 단계를
    판정해 라벨('우승'/'준우승'/'4강'/'8강'/'16강'/'16강진출전'/
    '조별탈락') 또는 None(그 대회 자체에 참가 기록 없음)을 반환한다."""
    conn = get_conn()
    for stage in _CLUB_COMP_STAGE_ORDER:
        row = conn.execute(
            f"""SELECT * FROM {matches_table} WHERE tournament_id=? AND stage=?
               AND (home_team_id=? OR away_team_id=?) AND home_score>=0
               ORDER BY id DESC LIMIT 1""",
            (tournament_id, stage, team_id, team_id)).fetchone()
        if row:
            if stage == "F":
                from competition.competition_common import winner_of
                winner = winner_of(row)
                conn.close()
                return "우승" if winner == team_id else "준우승"
            conn.close()
            return _CLUB_COMP_STAGE_LABEL[stage]
    conn.close()
    return None


def _get_club_comp_result(year, team_id):
    """team_id가 그 해 실제로 참가했던 챔스/유로파/컨퍼런스급 대회에서의
    (단계 라벨, 대륙, 티어('cl'/'el'/'ecl')) 3-튜플 — 참가 자체가 없으면
    (None, None, None). 한 팀은 그 해 이 셋 중 최대 하나에만 속한다
    (waterfall 구조 — _club_comp_squad_pool 등 기존 코드의 동일 전제를
    그대로 재사용) — cl→el→ecl 순으로 찾아 처음 걸리는 대회를 쓴다.

    [2026-09 6차 확장] 기존 _get_club_cl_result(챔스 전용, 우승/준우승/
    4강 3단계만 판정)를 완전히 대체한다 — 유로파/컨퍼런스도 잡고,
    _team_furthest_stage_result로 8강/16강/16강진출전/조별탈락까지
    세분화한다. team_id 기반 일반 함수라 AI든 "나"든 구분 없이 그대로
    쓸 수 있다(_get_team_trophy_bonus/_get_ballon_trophy_bonus 둘 다
    이 함수 하나를 공유 — "내 발롱도르"와 "세계기록실 발롱도르"가
    어긋나면 안 된다는 이 파일의 설계 원칙)."""
    for tier, (entries_tbl, tournaments_tbl, matches_tbl) in _CLUB_COMP_TABLES.items():
        conn = get_conn()
        trow = conn.execute(
            f"""SELECT t.id, t.continent FROM {entries_tbl} e
               JOIN {tournaments_tbl} t ON e.tournament_id=t.id
               WHERE e.team_id=? AND t.year=? AND t.status='done' LIMIT 1""",
            (team_id, year)).fetchone()
        conn.close()
        if not trow:
            continue
        stage_label = _team_furthest_stage_result(matches_tbl, trow["id"], team_id)
        return stage_label, trow["continent"], tier
    return None, None, None


def _club_comp_trophy_value(stage_label, continent, tier):
    """competition_weight × stage_weight × 10.0(기존 _cl_trophy_points
    최댓값과 스케일을 맞추기 위한 배율 — 유럽CL 우승 1.00×1.00×10.0=10.0
    으로 예전과 동일). 셋 중 하나라도 없으면(대회 미참가) 0.0."""
    if not stage_label or not continent or not tier:
        return 0.0
    comp_w = _CLUB_COMP_WEIGHT.get((continent, tier), 0.0)
    stage_w = _CLUB_COMP_STAGE_WEIGHT.get(stage_label, 0.0)
    return comp_w * stage_w * 10.0


# [2026-09 신설, 신민용 확정: 국가대표 대륙컵(월드컵 아래 등급 — 유로/
# 코파 아메리카/아시안컵/AFCON 등)에도 대륙 간 경쟁 수준 차이를
# 반영한다. 4개 연맹(유럽/아메리카/아시아/아프리카 — 남미·북미·북중미는
# 이 게임에서 "아메리카" 대륙컵 하나로 합쳐져 있음, _NATION_CONF 참고)
# 사이의 실제 경쟁 수준 차이를 비율로 담아두고, 아래 두 곳
# (_intl_trophy_points=내 선수 전용, _CONF_CUP_WEIGHT=AI 후보 전체용)이
# 같은 표를 공유하게 한다. 예전엔 이 둘이 서로 다른 비율(_intl_trophy_
# points는 "유럽만 100%, 나머지 전부 20%"인 이분법, _CONF_CUP_WEIGHT는
# "유럽=아메리카 100%, 아프리카 67%, 아시아 50%")을 따로 쓰고 있었다 —
# "내 발롱도르"와 "세계기록실 발롱도르"가 절대 어긋나면 안 된다는 이
# 파일의 설계 원칙(파일 맨 위 주석 참고)과 모순이라 하나로 통일한다.
# [클럽 대항전(위 _CLUB_COMP_WEIGHT)과는 완전히 별개 — 이건 국가대표
# 대륙컵 전용이다.]
_CONTINENTAL_CUP_WEIGHT_RATIO = {"유럽": 1.00, "아메리카": 0.85, "아프리카": 0.55, "아시아": 0.45}



# [2026-09 신설, 신민용 요청: "리그 트로피도 리그 등급에 따라 달라야
# 할듯 — SS급부터 S급은 같으며, A급 B급 이렇게 우승 관련해서 트로피가
# 달라야겠지. 이건 컵 대회도 마찬가지"] 지금까지 _league_rank_points/
# _cup_trophy_points는 그 나라 리그 등급과 무관하게 항상 똑같은 절대
# 점수(우승 4.0/1.0 등)를 줬다 — SS등급 리그 우승이든 F등급 리그 우승
# 이든 발롱도르 트로피 점수에 동일하게 기여했다는 뜻.
#
# [2026-09 2차 확장, 신민용+GPT 협의: "A급 안에서도 포르투갈/네덜란드/
# 브라질과 사우디/멕시코/미국은 같은 취급이면 안 된다 — 등급(글자) 하나로
# 뭉뚱그리지 말고 등급 안에서도 나라별 순위를 매기자"] 기존
# _TROPHY_GRADE_WEIGHT(글자 등급 8개에만 값이 있어 같은 등급 안에서는
# 국가 구분이 전혀 없던 방식)를 대체 — 등급별 [최고~최저] 값 구간을
# 정하고, 그 등급 안의 국가 순위(신민용+GPT 순위 확정, 실제 국가대표
# 실력이 아니라 "리그 우승의 발롱도르 가치" 기준)에 선형보간을 적용한다.
# SS/S는 "국내에서는 굳이 세분화하지 않는다"는 원칙대로 등급 내 전원
# 동일값 유지(_COUNTRY_RANK_WITHIN_GRADE에 순서를 넣어도 무시됨 —
# 아래 _build_country_trophy_weight 참고).
#
# [등급 경계 불변식, 신민용 확정: "B급 최상이 A급 최하보다 높으면 안
# 된다 — A급 최약(미국) 우승이 B급 1위(콜롬비아) 우승보다 낮아지면
# 안 됨"] 그래서 등급 구간 자체를 겹치지 않게 잡았다.
#
# [2026-09 3차 재보정, 신민용 지적: "A-B 경계가 0.02밖에 안 되는데
# A 등급 내부 스프레드(포르투갈 0.90~일본 0.814=0.054)보다도 좁다 —
# 등급 내 세분화가 등급 자체의 구분을 삼켜버린다"] 등급 간 경계를
# 0.02→0.05 내외로 넓혔다(A 0.90~0.78, B 0.73~0.61 — A 최저 0.78이
# B 최고 0.73보다 0.05 위). SS-S-A-B-C-D 다섯 경계는 전부 0.05로
# 맞췄고, D-E(0.04)·E-F(0.03)만 살짝 좁다(E/F 폭 자체를 더 좁게 잡은
# 여파 — 현재 E/F 등록 국가가 0개라 당장 영향은 없음, 신민용이 원하면
# 추후 조정). _build_country_trophy_weight 로드 시점에 이 불변식을
# 실제로 검증해 어긋나면 바로 예외를 던진다(조용히 깨진 채로 못
# 지나가게).
_GRADE_VALUE_RANGE = {
    "SS": (1.00, 1.00), "S": (0.95, 0.95),
    "A": (0.90, 0.78), "B": (0.73, 0.61), "C": (0.56, 0.46),
    "D": (0.41, 0.34), "E": (0.30, 0.25), "F": (0.22, 0.18),
}

# 등급 내 순위(1등=그 등급에서 가장 가치 높은 우승). SS/S는 순서가
# 있어도 무시(전원 등급 값 그대로). [2026-09] C의 아랍에미리트, D의
# 웨일스는 신민용+GPT 순위표 원안에 누락돼 있던 국가 — COUNTRY_LEAGUE_
# GRADE에는 있는데 순위표에는 없어서, 값이 없는 채로 두면 등급 평균치로
# 폴백되지만(그 자체로 안전) 일단 여기서는 실제 리그 실력에 맞춰 보이는
# 자리에 직접 끼워 넣었다 — 이 둘의 정확한 위치는 신민용 확인 필요
# (아랍에미리트: C 중하위권 추정 — 최근 자본 투입은 있지만 리그 수준
# 자체는 아직 중하위, 베네수엘라와 이란 사이에 배치. 웨일스: 유럽
# 내에서도 축구 리그로서는 최약체권으로 보고 D 최하위에 배치).
_COUNTRY_RANK_WITHIN_GRADE = {
    "SS": ["잉글랜드"],
    "S": ["독일", "스페인", "이탈리아", "프랑스"],
    "A": ["포르투갈", "네덜란드", "브라질", "아르헨티나", "튀르키예", "벨기에",
          "스코틀랜드", "오스트리아", "스위스", "덴마크", "일본", "체코",
          "사우디아라비아", "멕시코", "미국"],
    "B": ["콜롬비아", "크로아티아", "우루과이", "폴란드", "그리스", "세르비아",
          "우크라이나", "러시아", "노르웨이", "스웨덴", "대한민국", "에콰도르",
          "모로코", "호주", "이집트", "남아프리카공화국", "튀니지", "카타르",
          "캐나다"],
    "C": ["루마니아", "칠레", "이스라엘", "헝가리", "슬로바키아", "불가리아",
          "파라과이", "페루", "코스타리카", "우즈베키스탄", "조지아", "핀란드",
          "아이슬란드", "세네갈", "나이지리아", "가나", "카메룬", "코트디부아르",
          "알제리", "베네수엘라", "아랍에미리트", "이란", "중국", "이라크",
          "키프로스", "아제르바이잔", "벨라루스", "태국", "말레이시아",
          "인도네시아", "베트남", "룩셈부르크", "파나마"],
    "D": ["보스니아 헤르체고비나", "북아일랜드", "몬테네그로", "북마케도니아",
          "코소보", "뉴질랜드", "자메이카", "온두라스", "볼리비아", "엘살바도르",
          "과테말라", "앙골라", "잠비아", "우간다", "말리", "부르키나 파소",
          "기니", "카보베르데", "콩고 민주 공화국", "요르단", "오만", "바레인",
          "시리아", "가봉", "웨일스"],
    "E": [],
    "F": [],
}


def _build_country_trophy_weight():
    """_COUNTRY_RANK_WITHIN_GRADE + _GRADE_VALUE_RANGE로 국가명→트로피
    가중치 딕셔너리를 만든다. 등급 내 순위 i(0=최고)에 선형보간:
    value = hi - i/(n-1)*(hi-lo) (n=1이면 hi 그대로 — SS/S가 이 경로).
    모듈 로드 시 1회 계산 — 게임 진행 중 안 바뀌는 정적 데이터라 매번
    다시 계산할 필요 없음. 마지막에 등급 경계가 실제로 안 겹치는지
    (예: A 최저값 > B 최고값) 검증해서, 나중에 누군가 _GRADE_VALUE_RANGE
    구간을 실수로 겹치게 고쳐도 조용히 넘어가지 않고 바로 걸리게 한다."""
    weight = {}
    grade_order = ("SS", "S", "A", "B", "C", "D", "E", "F")
    for grade in grade_order:
        names = _COUNTRY_RANK_WITHIN_GRADE.get(grade, [])
        hi, lo = _GRADE_VALUE_RANGE[grade]
        n = len(names)
        for i, name in enumerate(names):
            v = hi if n <= 1 else hi - (i / (n - 1)) * (hi - lo)
            weight[name] = round(v, 4)
    # 등급 경계 불변식 검증(신민용 확정: "B급 최상이 A급 최하보다 높으면
    # 안 된다") — 인접 등급끼리 min(상위등급) > max(하위등급)인지 확인.
    for hi_grade, lo_grade in zip(grade_order, grade_order[1:]):
        hi_min = _GRADE_VALUE_RANGE[hi_grade][1]
        lo_max = _GRADE_VALUE_RANGE[lo_grade][0]
        assert hi_min > lo_max, (
            f"등급 경계 겹침: {hi_grade} 최저({hi_min}) <= {lo_grade} 최고({lo_max})")
    return weight


_COUNTRY_TROPHY_WEIGHT = _build_country_trophy_weight()


def _country_trophy_weight(country_name):
    """국가명 → 트로피 가중치. _COUNTRY_RANK_WITHIN_GRADE에 명시된
    국가는 정확한 보간값을, 그 밖의 국가(COUNTRY_LEAGUE_GRADE 미등록
    → 국대 등급 폴백, 또는 등급표엔 있지만 순위표에 아직 안 올라간
    국가)는 그 등급 구간의 중간값을 쓴다 — 순위를 모르니 최고/최저
    어느 쪽으로도 치우치지 않게.

    [2026-09 4차 확장, 신민용+GPT 협의: "이걸 '트로피 전용 가중치'가
    아니라 그 리그의 경쟁 수준을 나타내는 리그 강도 축으로 보는 게
    맞다"] 원래 트로피 점수(_get_team_trophy_grade_weight 경유)에만
    쓰던 이 값을 이제 score_rating/score_goals_assists 보정에도 그대로
    재사용한다(_score_ballon_candidate 참고) — 새 국가 순위표를 또
    만들지 않고 이미 만든 것 하나를 공유. 아래 _league_strength_weight는
    이 함수의 별칭일 뿐 완전히 동일하다 — 호출부 맥락(트로피 vs
    평점/생산성)에 따라 더 읽기 좋은 이름을 쓰기 위함."""
    w = _COUNTRY_TROPHY_WEIGHT.get(country_name)
    if w is not None:
        return w
    grade = get_country_league_grade(country_name)
    hi, lo = _GRADE_VALUE_RANGE.get(grade, (1.0, 1.0))
    return round((lo + hi) / 2.0, 4)


_league_strength_weight = _country_trophy_weight  # 읽기용 별칭, 본체와 완전 동일


# team_id -> 그 팀 리그 국가의 트로피 등급 배율 캐시. teams.league_id/
# leagues.country_id는 세션 중 팀이 이적·승강 등으로 바뀔 수 있으므로
# _invalidate_team_ovr_cache가 같이 비운다(위 _league_goal_mult_cache와
# 동일 관례 — 다만 이건 "팀 단위"라 리그 단위보다 항목 수가 많아 전역
# 1회 대신 팀별 지연 조회로 채운다).
_team_trophy_grade_weight_cache: dict = {}


def _get_team_trophy_grade_weight(team_id):
    """team_id -> _country_trophy_weight(국가명). team_id가 없거나 조회
    실패 시 안전하게 1.00(무보정, 기존 동작과 동일)을 반환한다."""
    if not team_id:
        return 1.0
    w = _team_trophy_grade_weight_cache.get(team_id)
    if w is not None:
        return w
    conn = get_conn()
    row = conn.execute(
        """SELECT cn.name AS country FROM teams t
           JOIN leagues l ON t.league_id = l.id
           JOIN countries cn ON l.country_id = cn.id
           WHERE t.id=?""", (team_id,)).fetchone()
    w = _country_trophy_weight(row["country"]) if row else 1.0
    _team_trophy_grade_weight_cache[team_id] = w
    return w


def _cup_trophy_points(result: str, team_id=None) -> float:
    if not result:
        return 0.0
    if "우승" in result and "준우승" not in result:
        base = 1.0
    elif "준우승" in result:
        base = 0.3
    else:
        return 0.0
    return base * _get_team_trophy_grade_weight(team_id)


def _sc_trophy_points(result: str) -> float:
    """[2026-08 신설, 10순위 슈퍼컵 시스템 구축 이후, 신민용 확정: "챔스가
    발롱에 1의 영향을 주면 슈퍼컵은 0.2의 영향을 주는 것"] 슈퍼컵은 이제
    실제로 구현됐으므로(super_cup_engine.py), 위 주석에서 "가중치를 매길
    대상 자체가 없다"고 적어뒀던 한계가 해소됐다 — 옛 _cl_trophy_points와
    완전히 같은 결과 판정 기준(우승/준우승/4강급)에 0.2를 곱해, 챔스
    우승(10.0 스케일) 대비 정확히 1/5 무게로 반영한다. 슈퍼컵은 연
    1회·4팀뿐인 단기 대회라 챔스만큼 심사에 크게 반영되면 안 된다는
    원래 설계 의도(위 별점 표: "슈퍼컵/클럽월드컵 ⭐☆☆☆☆~⭐⭐☆☆☆")를
    그대로 따른다.
    [2026-09 6차 확장] 클럽 대항전 쪽(_club_comp_trophy_value)은 대륙/
    티어/단계로 세분화됐지만, 슈퍼컵은 대륙·티어 구분이 없는 단일
    대회라 이 자체 판정 기준(우승/준우승/4강급)을 그대로 유지한다 —
    새 체계와 억지로 통합할 이유가 없다."""
    if not result:
        return 0.0
    if "우승" in result and "준우승" not in result:
        base = 10.0
    elif "준우승" in result:
        base = 4.5
    elif "4강" in result or "3위" in result or "4위" in result:
        base = 2.5
    else:
        base = 0.0
    return base * 0.2



def _intl_trophy_points(result: str, kind: str = "world", continent: str = "") -> float:
    """월드컵/대륙컵(코파 아메리카·유로 격) — 개최 연도에만 intl_tournaments에
    행이 생기므로, 이 함수가 0을 넘는 값을 주는 시점 자체가 자연스럽게
    '그 해가 메이저 국가대표 대회 연도'라는 게이트 역할을 한다.
    [2026-07 재조정, 신민용 지적: "월드컵 우승 정도면 배점을 더 크게
    두는 게 현실적"] 우승/준우승 배점을 CL 수준으로 끌어올렸다(기존
    6.0/3.5/2.0/1.0 → 10.0/4.5/2.0/0.8) — 월드컵 우승은 발롱도르 심사에서
    사실상 결정적 변수로 다뤄지는 게 현실에 더 가깝다.

    [2026-07 확장, 신민용 지적: "대륙컵(네이션스컵)은 유럽만 발롱도르에
    영향이 좀 들어가고 나머지(아시안컵/남북미 대륙컵/아프리카 네이션스컵)는
    참가국 수준이 약해서 큰 영향이 없어야 한다"] 월드컵(kind='world')은
    대륙 구분이 없어 그대로 만점을 주고, 대륙컵(kind='continent')은
    _CONTINENTAL_CUP_WEIGHT_RATIO(유럽 100%/아메리카 85%/아프리카 55%/
    아시아 45%)를 곱한다 — 아시안컵 우승(10.0)이 유로 우승과 동일하게
    발롱도르 트로피 점수를 채워주던 것을 막기 위함.
    [2026-09 수정, 신민용 확정: "아시안컵에서 활약해도 아예 게이트를
    막는 건 유럽 편향"이라는 이전 지적과 같은 맥락 — 예전엔 "유럽만
    100%, 나머지 전부 20%"라는 이분법이었는데, 이러면 아메리카(코파
    아메리카급)와 아시아(아시안컵급)가 똑같이 20%로 취급돼 대회 수준
    차이가 전혀 안 보였다. _CONF_CUP_WEIGHT(AI 후보용)와 같은 표를
    공유해 4단계로 세분화한다.

    [2026-08 확장, 신민용 확정] 3단계 지역컵(kind='region', EAFF/AFF/SAFF/
    WAFF/COSAFA/CECAFA/WAFU/UNCAF/카리브)은 대륙컵보다도 한 단계 더 아래
    급이라 — 대륙컵 중 유럽 외(20%)보다도 훨씬 약하게(5%) 잡는다. 지역컵
    조별탈락엔 대륙컵 같은 마이너스 페널티도 안 준다 — 애초에 그 정도로
    비중 있는 대회가 아니라서.
    """
    if not result:
        return 0.0
    if "우승" in result and "준우승" not in result:
        base = 10.0
    elif "준우승" in result:
        base = 4.5
    elif "4강" in result or "3위" in result or "4위" in result:
        base = 2.0
    elif "8강" in result:
        base = 0.8
    else:
        # [2026-07 신설, GPT 3차 피드백 부분 채택: "약한 대륙컵은 잘해도
        # 보너스는 제한적이지만 못하면 손해는 크다(비대칭)"] GPT는 대회
        # 5개 × 잘했을때/못했을때 총 10개 계수의 표를 제안했지만, 이 함수는
        # 결과 문자열만 받고 개인 생산력은 안 받으므로("우승했지만 무득점"과
        # "조별탈락+무득점"을 구분 못함) 그 정교한 매트릭스를 그대로 넣으면
        # 팀이 약해서 일찍 떨어진 것까지 선수 개인 책임으로 감점하게 된다.
        # 그래서 핵심만 최소하게 반영한다 — 유럽 외 대륙컵(아시안컵/남북미
        # 대륙컵/아프리카 네이션스컵) 조별탈락은 0이 아니라 소폭 마이너스로
        # 취급해 "이 정도 대회에서도 존재감을 못 보였다"는 신호를 준다.
        # 월드컵·유로는 그대로 0(중립) — 이미 그 자체로 충분히 어려운
        # 무대라 추가 감점 없이도 개인 생산력 위주 평가가 자연스럽다.
        if kind == "continent" and continent != "유럽":
            return -1.5
        return 0.0   # 조별탈락/예선탈락 등
    if kind == "region":
        base *= 0.05
    elif kind == "continent":
        base *= _CONTINENTAL_CUP_WEIGHT_RATIO.get(continent, 0.45)
    return base


def _league_rank_points(team_id: int) -> float:
    """리그 최종 순위 기반 점수 (1위=리그 우승 4.0, 2위 1.5, 3위 0.5) —
    _get_team_trophy_grade_weight로 그 나라 리그의 국가별 세부 가중치를
    적용(SS/S=1.00, A 0.90~0.78 국가별 세분화 등, 위 _country_trophy_
    weight 문서 참고)."""
    try:
        rows = get_league_standings_by_team(team_id)
    except Exception:
        return 0.0
    for i, r in enumerate(rows):
        if r.get("id") == team_id:
            if i == 0:
                base = 4.0
            elif i == 1:
                base = 1.5
            elif i == 2:
                base = 0.5
            else:
                return 0.0
            return base * _get_team_trophy_grade_weight(team_id)
    return 0.0


def _get_ballon_trophy_bonus(year: int, team_id: int) -> float:
    """그 해 챔스+리그순위+자국컵+국가대표 메이저대회 성적을 합산한
    발롱도르용 트로피 보너스 점수 (0~약 25.5점 범위, 개인 성적 대비
    작게 설계됨 — 위 설계 노트 참고). [2026-07 재조정] 우승급 실적의
    배점을 올려 상한이 기존 19.5→25.5로 늘었지만, 그 해 챔스+월드컵+
    리그+자국컵을 전부 우승해야 나오는 극단치라 실질 영향은 제한적."""
    conn = get_conn()
    cup_t = conn.execute(
        "SELECT my_result FROM cup_tournaments WHERE year=? AND my_in=1", (year,)).fetchone()
    sc_t = conn.execute(
        "SELECT my_result FROM sc_tournaments WHERE year=? AND my_in=1", (year,)).fetchone()
    intl_t = conn.execute(
        "SELECT kind, continent, my_result FROM intl_tournaments WHERE year=? AND my_selected=1",
        (year,)).fetchone()
    conn.close()
    bonus = 0.0
    # [2026-09 6차 확장, 신민용 확정: "유로파/컨퍼런스리그도 대륙별
    # 위상·진출 단계로 트로피 가치가 나야 한다"] AI 후보(_get_team_
    # trophy_bonus)와 완전히 동일한 _get_club_comp_result/_club_comp_
    # trophy_value를 그대로 쓴다 — team_id 기반 일반 함수라 "나"/AI
    # 구분 없이 재사용 가능, "내 발롱도르"와 "세계기록실 발롱도르"가
    # 어긋나면 안 된다는 이 함수의 설계 원칙 그대로 유지.
    cl_stage, cl_continent, cl_tier = _get_club_comp_result(year, team_id)
    bonus += _club_comp_trophy_value(cl_stage, cl_continent, cl_tier)
    bonus += _cup_trophy_points(cup_t["my_result"] if cup_t else None, team_id=team_id)
    bonus += _sc_trophy_points(sc_t["my_result"] if sc_t else None)
    bonus += _intl_trophy_points(
        intl_t["my_result"] if intl_t else None,
        intl_t["kind"] if intl_t else "world",
        intl_t["continent"] if intl_t else "")
    if team_id:
        bonus += _league_rank_points(team_id)
    return bonus


def _major_stage_carry(year: int, team_id: int) -> bool:
    """[2026-07 신설, 신민용 지적: "A급 이상 리그에서 성적 좋은 애들은
    월드컵이나 이런 기간에 캐리해서 상 싹쓸이하면 A급 리그라도 발롱
    받을 수 있게 만드는 게 좋을 듯. 챔스나 이런 것도 마찬가지"]
    기존엔 BALLON_DOR_GRADES(SS/S)에 없는 리그(A급 이하, 예: K리그)
    소속 선수는 자국리그에서 아무리 압도적이어도(심지어 월드컵 우승+
    골든볼을 받아도!) 발롱도르 후보 자격 자체가 없었다. 이제 A급 이하
    리그 선수도 후보가 될 수 있게 하되, 반드시 '세계 무대에서 실제로
    증명'했어야 한다는 게이트를 하나 추가한다 — 자국리그 골 폭탄만으로는
    여전히 안 되고, 월드컵 결승급 활약(우승/준우승) 또는 유럽 챔피언십
    (유로) 우승이 있어야 이 게이트를 통과한다.

    [2026-09 정정, 신민용: "아시안컵에서 활약해도 챔스 우승한 것보단
    낮은 게 맞지만, 그렇다고 아예 게이트 자체를 통과 못 시키는 건
    유럽 편향이다"] 원래 이 문단은 "아시안컵/남북미 대륙컵/아프리카
    네이션스컵은 참가 수준이 약해서 게이트로 인정 안 함, 유럽만 인정"
    이었다 — 그런데 이건 세계 어디서든 동등하게 선수를 평가한다는
    발롱도르 취지와 안 맞고, 유럽 국적이 아니면 A급 이하 리그에서
    아무리 국가대표로 잘해도 절대 후보조차 될 수 없다는 뜻이었다.
    이제 4개 연맹(유럽/아메리카/아시아/아프리카) 대륙컵 우승을 전부
    동등하게 게이트 통과 조건으로 인정한다(대회 "가치" 차이는 게이트가
    아니라 _get_player_intl_bonus의 가산점 쪽에서 가중치로 반영 —
    유럽/아메리카 6점, 아프리카 4점, 아시아 3점). 클럽 챔피언스리그도
    마찬가지로 대륙 무관하게 우승만 보면 통과(AI 경로 _get_club_cl_
    result와 동일 기준)."""
    conn = get_conn()
    intl_t = conn.execute(
        "SELECT id, kind, continent, my_result FROM intl_tournaments WHERE year=? AND my_selected=1",
        (year,)).fetchone()
    conn.close()
    # [2026-09 재보정, 신민용 리포트: "국가대표도 주전/로테/대기가 나뉘는데
    # 0경기 뛴 대기 선수도 우승 값을 받는다"] my_selected=1은 "스쿼드에
    # 뽑혔는가"일 뿐 "실제로 뛰었는가"가 아니다 — _player_appeared_in_
    # tournament로 최소 출전(appearances>0) 조건을 추가한다. AI 쪽
    # _has_major_stage_proof도 동일하게 고쳐서 "나"와 "AI" 기준이 계속
    # 일관되게 유지된다(v2 피드백 #3 원칙 그대로 준수).
    if intl_t:
        result = intl_t["my_result"] or ""
        _played = _player_appeared_in_tournament(intl_t["id"], _SIA_MY_PLAYER_ID)
        if intl_t["kind"] == "world" and ("우승" in result or "준우승" in result) and _played:
            return True
        # [2026-09 수정, 신민용 확정: "아시안컵 우승도 인정해야 한다 —
        # 유로만 인정하는 건 유럽 편향"] my_selected=1은 이미 "내 국적이
        # 속한 연맹의 대륙컵"으로 정확히 좁혀져 있으므로(연맹당 대회
        # 1개뿐), continent=='유럽' 제약을 없애면 곧바로 "내 대륙컵
        # 우승이면 통과"가 된다 — 4개 연맹(유럽/아메리카/아시아/아프리카)
        # 전부 동등 취급.
        if intl_t["kind"] == "continent" and "우승" in result and _played:
            return True
    # [2026-09 6차 확장] AI 경로(_has_major_stage_proof)와 완전히 동일한
    # _get_club_comp_result를 쓴다 — 유로파/컨퍼런스리그 우승도 이제
    # 인정한다(예전엔 cl_tournaments만 봐서 유로파/컨퍼런스 우승이면
    # 그냥 통과 못 했다).
    cl_stage, _cl_continent, cl_tier = _get_club_comp_result(year, team_id)
    if cl_stage == "우승" and _player_appeared_in_club_cl(year, _SIA_MY_PLAYER_ID, tier=cl_tier or "cl"):
        return True
    return False


# ═════════════════════════════════════════════════════════════
# 역대 개인상(발롱도르/푸스카스) — 세계 단위 계산 (2026-09 신설)
# design_ballon_dor.md 설계 문서 참고. AI 선수 전원 + 나 자신을 완전히
# 같은 파이프라인(게이트→점수→정렬)으로 채점해 hist.season_individual_
# awards에 저장한다 — "내 발롱도르"와 "세계기록실 발롱도르"가 절대
# 어긋나지 않도록 계산은 여기 한 곳에서만 하고, _process_awards는 그
# 결과에서 내 순위만 조회한다(아래쪽 _process_awards 정의부 참고).
#
# [범위상 의도된 단순화] 국내컵/슈퍼컵 트로피 점수는 우승 여부만 본다
# (준우승 등은 0) — 원래도 배점이 작고(각 1.0/0.2점) Top30 순위에 미치는
# 영향이 미미한 반면, cup_entries/sc_entries는 CL과 스키마가 달라 완전히
# 똑같은 방식으로 일반화하려면 코드가 꽤 커진다. 배점이 가장 큰 CL
# (10.0/4.5/2.5)만 _batch_cl_placements로 우승/준우승/4강까지 정확히
# 구분한다. 이 단순화는 순위표에 미치는 영향이 작아 Phase 1에서는 이대로
# 가고, 필요해지면 나중에 컴퓨테이션만 확장하면 된다(스키마 변경 불필요).
# ═════════════════════════════════════════════════════════════

_SIA_MY_PLAYER_ID = -1  # world_browser.MY_PLAYER_ID와 반드시 같은 값 —
                        # 순환 import를 피하려고 여기 별도 상수로 둔다.


def _get_my_season_award_rank(year, award_type):
    """season_individual_awards에서 내(MY_PLAYER_ID) 그 해 순위 조회 —
    없으면(후보 자격 자체가 없었거나 Top30/Top10 밖) None. _process_awards
    가 발롱도르 판정 최종 결과를 여기서 조회해 쓴다(아래 참고) — "내
    발롱도르"와 "세계기록실 발롱도르"가 같은 계산에서 나오도록 보장."""
    conn = get_conn()
    row = conn.execute(
        "SELECT rank FROM season_individual_awards WHERE year=? AND award_type=? AND player_id=?",
        (year, award_type, _SIA_MY_PLAYER_ID)).fetchone()
    conn.close()
    return row["rank"] if row else None


def _get_historical_league_rank_points(year, team_id):
    """_league_rank_points(team_id)는 '지금 시즌' 실시간 순위표만 보므로
    과거 연도를 훑는 이 계산엔 못 쓴다(v2 피드백에서 확인된 문제) —
    hist.league_season_standings에서 그 해 승점을 다시 계산해 순위를
    매기는 버전. 배점은 _league_rank_points와 동일(1위 4.0/2위 1.5/3위 0.5).

    [2026-09 버그수정, 신민용+GPT 리포트: "발롱도르 저장값에 리그 순위
    점수가 통째로 빠져 있다(재계산하면 값이 다르다)"] 원인: _advance_week
    안에서 발롱도르 계산(_end_of_season)이 그 해 최종 순위를 hist.
    league_season_standings에 채우는 archive_old_seasons()/_summarize_
    and_prune_archive()(_generate_all_league_schedules 안에서 호출)보다
    먼저 실행된다 — 즉 발롱도르가 계산되는 바로 그 순간엔 이 표에 방금
    끝난 시즌 행이 아직 없다. 정식 수정(호출 순서 자체를 바꾸는 것)은
    파워랭킹 등 다른 로직과의 상호작용을 더 확인해야 해서, 대신 여기서
    self-healing 폴백을 넣는다: hist 표에 없으면 그 시점에 아직 archive
    되지 않고 남아있는 main.match_results에서 즉석으로 같은 승점/순위
    계산을 한다(로직은 완전히 동일, 데이터 소스만 다름). 나중에 hist
    표가 채워진 뒤 다시 조회하면 그때는 정상적으로 hist 경로를 탄다."""
    conn = get_conn()
    trow = conn.execute("SELECT league_id FROM teams WHERE id=?", (team_id,)).fetchone()
    if not trow or not trow["league_id"]:
        conn.close()
        return 0.0
    league_id = trow["league_id"]
    rows = conn.execute(
        """SELECT team_id, wins, draws, losses, goals_for, goals_against
           FROM hist.league_season_standings WHERE league_id=? AND year=?""",
        (league_id, year)).fetchall()
    if not rows:
        # [2026-09 신설] 폴백 — 위 코멘트 참고. match_results는 이 시점엔
        # 아직 archive_old_seasons()가 지우지 않은 상태라 그 해 경기가
        # 그대로 남아있다(완료된 경기만: 스코어 NULL이 아닌 것).
        # [2026-09 성능, 첫해 52→1주차 지연의 두 번째 원인 — 실측] 아래
        # 리그 단위 GROUP BY는 통계(sqlite_stat1)가 낡으면 idx_mr_year(연도)로
        # 계획이 떨어져 그 해 전체 경기를 훑는다(통계 없음: 710리그 23.1s,
        # 정상 통계: 0.26s). 정상 통계일 때 이미 쓰는 idx_mr_league_season을
        # 명시해 통계와 무관하게 같은 계획을 쓴다. GROUP BY team_id는 어느
        # 인덱스로 읽든 임시 B-트리 정렬을 거쳐 team_id 순으로 나오고 합계는
        # 순서와 무관하므로 결과 행·순서가 같다(710개 리그 × 두 통계 상태에서
        # 원래 SQL과 전수 대조 동일). 인덱스가 잠깐 없는 순간(대량 갱신용
        # 인덱스 끄기 등)엔 원래 SQL로 그대로 계산한다.
        _rank_args = (league_id, year, league_id, year)
        try:
            rows = conn.execute(
                """SELECT team_id,
                          SUM(win) AS wins, SUM(draw) AS draws, SUM(loss) AS losses,
                          SUM(gf) AS goals_for, SUM(ga) AS goals_against
                   FROM (
                       SELECT home_team_id AS team_id,
                              CASE WHEN home_score>away_score THEN 1 ELSE 0 END AS win,
                              CASE WHEN home_score=away_score THEN 1 ELSE 0 END AS draw,
                              CASE WHEN home_score<away_score THEN 1 ELSE 0 END AS loss,
                              home_score AS gf, away_score AS ga
                       FROM match_results INDEXED BY idx_mr_league_season
                       WHERE league_id=? AND year=? AND home_score IS NOT NULL AND away_score IS NOT NULL
                       UNION ALL
                       SELECT away_team_id AS team_id,
                              CASE WHEN away_score>home_score THEN 1 ELSE 0 END AS win,
                              CASE WHEN away_score=home_score THEN 1 ELSE 0 END AS draw,
                              CASE WHEN away_score<home_score THEN 1 ELSE 0 END AS loss,
                              away_score AS gf, home_score AS ga
                       FROM match_results INDEXED BY idx_mr_league_season
                       WHERE league_id=? AND year=? AND home_score IS NOT NULL AND away_score IS NOT NULL
                   )
                   GROUP BY team_id""",
                _rank_args).fetchall()
        except sqlite3.OperationalError:
            rows = conn.execute(
                """SELECT team_id,
                          SUM(win) AS wins, SUM(draw) AS draws, SUM(loss) AS losses,
                          SUM(gf) AS goals_for, SUM(ga) AS goals_against
                   FROM (
                       SELECT home_team_id AS team_id,
                              CASE WHEN home_score>away_score THEN 1 ELSE 0 END AS win,
                              CASE WHEN home_score=away_score THEN 1 ELSE 0 END AS draw,
                              CASE WHEN home_score<away_score THEN 1 ELSE 0 END AS loss,
                              home_score AS gf, away_score AS ga
                       FROM match_results
                       WHERE league_id=? AND year=? AND home_score IS NOT NULL AND away_score IS NOT NULL
                       UNION ALL
                       SELECT away_team_id AS team_id,
                              CASE WHEN away_score>home_score THEN 1 ELSE 0 END AS win,
                              CASE WHEN away_score=home_score THEN 1 ELSE 0 END AS draw,
                              CASE WHEN away_score<home_score THEN 1 ELSE 0 END AS loss,
                              away_score AS gf, home_score AS ga
                       FROM match_results
                       WHERE league_id=? AND year=? AND home_score IS NOT NULL AND away_score IS NOT NULL
                   )
                   GROUP BY team_id""",
                _rank_args).fetchall()
    conn.close()
    if not rows:
        return 0.0
    standings = sorted(
        rows, key=lambda r: (r["wins"] * 3 + r["draws"], r["goals_for"] - r["goals_against"]),
        reverse=True)
    for i, r in enumerate(standings):
        if r["team_id"] == team_id:
            return 4.0 if i == 0 else 1.5 if i == 1 else 0.5 if i == 2 else 0.0
    return 0.0


def _get_award_role(year, player_id):
    """개인상 참가도 계산용 — 그 해 이 선수의 역할 라벨(주전/로테이션/
    대기/전력외/유망주, compute_squad_roles가 매긴 것)을 그대로 가져온다.
    [2026-09 신설] _get_player_comp_contribution이 cl/cup/sc 세 번
    호출되는데 역할은 대회와 무관하게 하나뿐이라, 호출부(_get_team_
    trophy_bonus)가 이 함수로 한 번만 조회해 세 곳에 똑같이 넘긴다."""
    conn = get_conn()
    if player_id == _SIA_MY_PLAYER_ID:
        row = conn.execute(
            "SELECT role FROM my_player_position_history WHERE year=?", (year,)).fetchone()
    else:
        row = conn.execute(
            "SELECT role FROM hist.ai_player_position_history WHERE player_id=? AND year=?",
            (player_id, year)).fetchone()
    conn.close()
    return row["role"] if row else None


# [2026-09 신설, 신민용+GPT 확정: "_get_player_comp_contribution의 참가도가
# matches/3.0인데, matches가 로스터 전원에게 똑같이 부여되는 '팀이 그
# 대회에서 뛴 총 경기수'라 사실상 항상 1.0으로 꽉 찬다 — 위 _SQUAD_DEPTH_
# DECAY와 같은 철학(역할 기반)으로 통일하자"] 생산 스탯(saves/goals/
# clean_sheets)에 이미 쓰는 뎁스 감쇠 배율을 에이스(1.15) 기준으로
# 정규화해 그대로 참가도로 재사용한다 — matches 기반 계산과 섞지 않고
# 완전히 교체한다(사용자 확정: "matches를 완전히 없애는 게 현재 DB
# 구조에서는 더 정직하다" — matches는 팀이 그 대회에 참가했는지 여부
# 확인 용도로만 남긴다). role이 없으면(이 기능 신설 이전 과거 시즌 등)
# 기존과 동일하게 풀 참가도(1.0)로 폴백한다.
_ROLE_PARTICIPATION = {
    "주전": round(_SQUAD_DEPTH_DECAY[0] / _SQUAD_DEPTH_DECAY[0], 4),
    "로테이션": round(_SQUAD_DEPTH_DECAY[1] / _SQUAD_DEPTH_DECAY[0], 4),
    "대기": round(_SQUAD_DEPTH_DECAY[2] / _SQUAD_DEPTH_DECAY[0], 4),
    "전력외": round(_SQUAD_DEPTH_DECAY[3] / _SQUAD_DEPTH_DECAY[0], 4),
    "유망주": round(_SQUAD_DEPTH_DECAY[3] / _SQUAD_DEPTH_DECAY[0], 4),
}


def _get_player_comp_contribution(year, player_id, competition, team_id=None, role=None,
                                   quality_cap=1.3):
    """[2026-09 신설, 신민용 지적: "슈퍼컵 이런 것도 우승만 중요한 게
    아니라 그 과정에서 평점도 중요하다 — 평점이 낮거나 벤치였으면 우승해도
    의미가 없다"] competition('cl'/'cup'/'sc')에서 이 선수의 참가도×평점
    품질을 0~quality_cap 배율로 환산 — 팀이 우승해도 안 뛰었거나 형편없었으면
    (평점 낮음) 트로피 보너스가 거의 안 붙게 만든다. AI는 hist.ai_player_
    season_stats_by_comp, 나는 cl_matches/cup_matches/sc_matches의
    my_played/my_rating을 직접 집계한다(내 쪽엔 이런 대회별 요약 표가
    따로 없어서).

    [2026-09 6차 확장, 신민용+GPT 협의: "0.72(유로파 대회 기본값) 자체가
    문제가 아니라 1.30 배율이 모든 대회에 똑같이 곱해지는 게 문제 —
    유로파 우승 9.36점이 옛 챔스 우승(10.0)급까지 올라간 원인"] 배율
    상한을 고정 1.3이 아니라 호출부가 대회 티어별로 넘기는 quality_cap
    으로 바꾼다(기본값 1.3은 cup/sc처럼 티어 구분이 없는 대회의 기존
    동작을 그대로 유지) — _CLUB_COMP_QUALITY_CAP 참고.

    [2026-09 버그수정, 신민용+GPT 리포트: "로스터 전원이 팀 경기수를
    공유해서(matches가 개인별 실제 출전이 아님) 참가도가 사실상 항상
    1.0이 된다 — 로테이션 GK가 CL 우승 트로피를 주전과 똑같이 다 먹는다"]
    참가도를 matches 기반(min(1.0, matches/3.0))에서 역할 기반
    (_ROLE_PARTICIPATION)으로 완전히 교체한다. matches는 이제 "이 팀이
    그 대회에 참가했는가"(행 존재 여부) 확인 용도로만 남는다 — 그 값
    자체를 참가도 계산에 쓰지 않는다. role은 호출부(_get_team_trophy_
    bonus)가 _get_award_role로 한 번만 조회해 넘겨준다(cl/cup/sc 세 번
    호출이 매번 다시 조회하지 않도록).

    [2026-09 버그수정, 신민용 리포트: "아시아 챔스 뛰고 시즌 중 아스날로
    이적했는데 내가 가기 전 아스날이 딴 유럽 챔스 우승이 발롱도르 점수로
    들어온다"] team_id 없이 그 해 아무 {competition}나 뛰었는지만 보면,
    한 해 안에 대륙/나라를 옮긴 선수는 "전혀 다른 팀의 전혀 다른 대회"에서
    쌓은 참가도가 엉뚱한 트로피(_get_club_comp_result가 찾아준 team_id의
    우승)에 곱해져 버린다 — 실제로는 그 우승에 단 한 경기도 기여하지
    않았는데도 참가도가 0보다 커서 게이트를 통과하는 것. team_id를 받으면
    "그 팀이 뛴 경기"로 좁혀서, 트로피의 주인(team_id)과 내가 실제로
    뛴 경기가 정확히 같은 대회 스틴트인지 확인한다."""
    if player_id == _SIA_MY_PLAYER_ID:
        table_map = {"cl": ("cl_matches", "cl_tournaments"),
                     "cup": ("cup_matches", "cup_tournaments"),
                     "sc": ("sc_matches", "sc_tournaments")}
        mtable, ttable = table_map[competition]
        conn = get_conn()
        if team_id:
            row = conn.execute(
                f"""SELECT COUNT(*) AS matches, AVG(m.my_rating) AS rating
                    FROM {mtable} m JOIN {ttable} t ON m.tournament_id=t.id
                    WHERE t.year=? AND m.my_played=1
                      AND (m.home_team_id=? OR m.away_team_id=?)""",
                (year, team_id, team_id)).fetchone()
        else:
            row = conn.execute(
                f"""SELECT COUNT(*) AS matches, AVG(m.my_rating) AS rating
                    FROM {mtable} m JOIN {ttable} t ON m.tournament_id=t.id
                    WHERE t.year=? AND m.my_played=1""", (year,)).fetchone()
        conn.close()
        matches = row["matches"] if row else 0
        rating = row["rating"] if row and row["rating"] is not None else 0.0
    else:
        conn = get_conn()
        row = conn.execute(
            """SELECT matches, rating FROM hist.ai_player_season_stats_by_comp
               WHERE player_id=? AND year=? AND competition=?""",
            (player_id, year, competition)).fetchone()
        conn.close()
        matches = row["matches"] if row else 0
        rating = row["rating"] if row and row["rating"] is not None else 0.0
    if not matches:
        return 0.0
    participation = _ROLE_PARTICIPATION.get(role, 1.0)
    quality = max(0.2, min(quality_cap, 1.0 + (rating - 6.0) / 1.5))
    return participation * quality


